/* Node.js: plan topic explanations (concept / explanation / real example), keyed w<module>k<topic> */
const EXPL_ND_01 = {
  "w0k0": {c:"JavaScript có 7 kiểu primitive (<code>string</code>, <code>number</code>, <code>bigint</code>, <code>boolean</code>, <code>undefined</code>, <code>null</code>, <code>symbol</code>) và object. <code>===</code> so sánh không ép kiểu, <code>==</code> ép kiểu theo thuật toán loose equality. <code>number</code> là số thực IEEE 754 64-bit, nên chỉ biểu diễn chính xác số nguyên trong khoảng ±<code>Number.MAX_SAFE_INTEGER</code> (2^53 − 1).", e:"<ul><li><code>typeof null === 'object'</code> là bug lịch sử; <code>NaN !== NaN</code>, kiểm tra bằng <code>Number.isNaN</code> hoặc <code>Object.is</code>. Mảng là object, kiểm tra bằng <code>Array.isArray</code>.</li> <li><code>==</code> có quy tắc khó nhớ: <code>null == undefined</code> là true nhưng <code>null == 0</code> là false; <code>'' == 0</code>, <code>'0' == false</code>, <code>[] == false</code> đều true. Quy ước an toàn: luôn dùng <code>===</code>, ngoại lệ hay được chấp nhận là <code>x == null</code> để bắt cả null lẫn undefined.</li> <li>Falsy gồm <code>false</code>, <code>0</code>, <code>-0</code>, <code>0n</code>, <code>''</code>, <code>null</code>, <code>undefined</code>, <code>NaN</code>. Bẫy kinh điển ở backend: <code>if (!amount)</code> coi giao dịch 0 đồng là thiếu dữ liệu, <code>limit || 20</code> ghi đè giá trị 0 hợp lệ. Dùng <code>??</code> và kiểm tra <code>=== undefined</code> khi 0 hoặc chuỗi rỗng là giá trị hợp lệ.</li> <li>Float: <code>0.1 + 0.2</code> ra <code>0.30000000000000004</code>, <code>(1.005).toFixed(2)</code> ra <code>\"1.00\"</code>. Tiền không bao giờ lưu bằng float: lưu số nguyên theo đơn vị nhỏ nhất (cent, hoặc đồng với VND), trong PostgreSQL dùng <code>bigint</code> hoặc <code>numeric</code>, chỉ format thành chuỗi thập phân ở tầng hiển thị.</li> <li>Vượt 2^53 là mất chính xác âm thầm: <code>JSON.parse('{\"id\":9007199254740993}')</code> ra <code>9007199254740992</code>. Vì vậy driver <code>pg</code> mặc định trả cột <code>int8</code> và <code>numeric</code> dưới dạng string. <code>BigInt</code> (<code>10n</code>) chính xác tuyệt đối nhưng chia thì cắt phần lẻ (<code>10n / 3n === 3n</code>), không trộn được với number (TypeError), và <code>JSON.stringify</code> ném <code>TypeError: Do not know how to serialize a BigInt</code>.</li></ul> Câu hỏi vặn hay gặp: \"id kiểu bigint trả cho mobile thế nào?\" Trả dạng string trong JSON, vì client JS/Dart cũng parse number thành double.", x:"Báo cáo tháng của Expense Tracker lệch vài cent so với tổng mà app mobile tự cộng, vì service cộng <code>amount</code> dạng float rồi mới làm tròn. Cùng lúc, id giao dịch kiểu <code>bigint</code> khi ra JSON bị làm tròn. Sửa: domain chỉ làm việc với số nguyên, parse chuỗi tiền thay vì nhân float, và serialize bigint thành string:<pre>const items = [0.1, 0.2, 0.3];\nitems.reduce((s, x) =&gt; s + x, 0);            // 0.6000000000000001\n\nfunction toCents(s) {                         // \"19.99\" -&gt; 1999, never via float math\n  const [int, frac = ''] = s.split('.');\n  const sign = int.startsWith('-') ? -1 : 1;\n  return sign * (Math.abs(Number(int)) * 100 + Number(frac.padEnd(2, '0')));\n}\n['0.10', '0.20', '0.30'].map(toCents).reduce((s, x) =&gt; s + x, 0); // 60\n\nconst row = { id: 9007199254740993n, totalCents: 60 };\nJSON.stringify(row, (_k, v) =&gt; (typeof v === 'bigint' ? v.toString() : v));\n// {\"id\":\"9007199254740993\",\"totalCents\":60}</pre>Trong lab, <code>toCents</code> còn phải validate định dạng (tối đa 2 chữ số thập phân) trước khi gọi; phần đó làm bằng schema Zod ở biên."},
  "w0k1": {c:"Scope quyết định biến nhìn thấy được ở đâu: <code>var</code> theo function scope, <code>let</code>/<code>const</code>/<code>class</code> theo block scope. Hoisting là việc khai báo được đăng ký khi vào scope, trước khi chạy dòng nào; <code>var</code> được khởi tạo <code>undefined</code>, còn <code>let</code>/<code>const</code> nằm trong TDZ (temporal dead zone) tới đúng dòng khai báo. Closure là function giữ tham chiếu tới môi trường từ vựng nơi nó được tạo, kể cả khi scope đó đã chạy xong.", e:"<ul><li>Function declaration được hoist cả thân nên gọi trước khai báo được. Function expression gán vào <code>var</code> chỉ hoist tên (ra <code>TypeError: x is not a function</code>); gán vào <code>const</code> thì <code>ReferenceError: Cannot access 'x' before initialization</code>.</li> <li>TDZ áp dụng cả với <code>typeof</code>: <code>typeof x</code> trước dòng <code>let x</code> ném ReferenceError, khác với biến chưa từng khai báo (trả <code>'undefined'</code>).</li> <li>Vòng lặp: <code>for (var i...)</code> chỉ có một binding <code>i</code> dùng chung, callback chạy sau đều thấy giá trị cuối. <code>for (let i...)</code> tạo binding mới cho mỗi vòng. Đây là câu hỏi in output phổ biến nhất.</li> <li>Closure giữ tham chiếu chứ không chụp giá trị: biến đổi sau đó thì closure thấy giá trị mới. Closure cũng giữ sống mọi thứ nó tham chiếu, nên cache ở module scope hay listener đăng ký theo request là nguồn memory leak thường gặp ở server chạy lâu.</li> <li>Ứng dụng ở backend: factory nhận dependency (<code>createTxRepo(db)</code>), middleware có config, memoize, rate limiter đếm theo key. ESM luôn strict nên gán biến chưa khai báo ném ReferenceError thay vì tạo global ngầm như sloppy mode.</li></ul>", x:"Import sao kê trong Expense Tracker ghi log lỗi sai số dòng: mọi dòng lỗi đều báo \"line 501\" với file 500 dòng. Code cũ dùng <code>var</code>, các callback <code>catch</code> chạy sau khi vòng lặp kết thúc nên đều đọc <code>i</code> cuối. Kèm theo đó là một closure leak:<pre>// BUG: one shared binding, every catch sees i === rows.length\nfor (var i = 0; i &lt; rows.length; i++) {\n  repo.insert(rows[i]).catch((err) =&gt; log.warn({ line: i + 1, err }, 'insert failed'));\n}\n// Fix: let creates a new binding per iteration\nfor (let i = 0; i &lt; rows.length; i++) {\n  repo.insert(rows[i]).catch((err) =&gt; log.warn({ line: i + 1, err }, 'insert failed'));\n}\n\n// Leak: this Map lives as long as the process, keyed by every userId ever seen\nconst cache = new Map();\nexport function getRates(userId) {\n  if (!cache.has(userId)) cache.set(userId, loadRates(userId));\n  return cache.get(userId);\n}</pre>Cache ở module scope không có giới hạn kích thước hay TTL sẽ lớn dần tới khi pod bị OOMKilled. Dùng LRU có <code>max</code> và TTL, hoặc chuyển sang Redis. Ngoài ra vòng lặp trên bắn 500 insert song song không giới hạn; ở module sau sẽ chuyển sang insert theo batch."},
  "w0k2": {c:"<code>this</code> được xác định lúc gọi (call-site), không phải lúc khai báo; ngoại lệ là arrow function, nó không có <code>this</code> riêng mà lấy từ scope bao ngoài. Mỗi object có một [[Prototype]], việc tra property đi ngược lên prototype chain; <code>class</code> là cú pháp gọn trên chính cơ chế prototype đó.", e:"<ul><li>Thứ tự ưu tiên: <code>new</code> (this là object mới) &gt; <code>call</code>/<code>apply</code>/<code>bind</code> (chỉ định rõ) &gt; <code>obj.method()</code> (this là <code>obj</code>) &gt; gọi trơn (<code>undefined</code> trong strict mode, mà ESM và thân class luôn strict).</li> <li>Mất <code>this</code> khi tách method: <code>const f = svc.convert; f()</code> hoặc <code>router.get('/tx', controller.list)</code> ném <code>TypeError: Cannot read properties of undefined</code>. Sửa bằng <code>bind</code>, bọc arrow <code>(req, res) =&gt; controller.list(req, res)</code>, hoặc khai báo class field arrow. Class field arrow tạo một function cho mỗi instance và không nằm trên prototype, nên lớp con không override rồi gọi <code>super.list()</code> được.</li> <li><code>fn.call(thisArg, a, b)</code>, <code>fn.apply(thisArg, [a, b])</code>, <code>fn.bind(thisArg)</code> trả function mới gắn cứng <code>this</code>; bind thêm lần nữa không đổi được, arrow function thì bỏ qua thisArg hoàn toàn. Arrow cũng không có <code>arguments</code>, <code>prototype</code> và không dùng với <code>new</code>.</li> <li>Prototype: <code>Object.getPrototypeOf(tx) === Transaction.prototype</code>; method nằm trên prototype nên mọi instance dùng chung. Object literal dùng làm dictionary vẫn kế thừa <code>Object.prototype</code>, đó là gốc của prototype pollution: merge đệ quy JSON người dùng có key <code>\"__proto__\"</code> có thể gắn property lên mọi object. Dùng <code>Map</code>, <code>Object.create(null)</code> hoặc validate bằng schema.</li> <li>Class: <code>#field</code> là private thật lúc chạy, khác <code>private</code> của TypeScript chỉ kiểm tra lúc compile. Constructor lớp con phải gọi <code>super()</code> trước khi chạm vào <code>this</code>.</li></ul>", x:"Một route mới của Expense Tracker API (Express) trả 500 ngay lần gọi đầu, stack trace chỉ vào <code>this.service</code>. Method được truyền như một giá trị nên khi Express gọi, <code>this</code> là undefined:<pre>class TransactionController {\n  constructor(service) { this.service = service; }\n  async list(req, res) {\n    res.json(await this.service.list(req.user.id));   // this === undefined here\n  }\n}\nconst ctrl = new TransactionController(txService);\n\nrouter.get('/transactions', ctrl.list);                // BUG: method detached from ctrl\nrouter.get('/transactions', ctrl.list.bind(ctrl));     // fix 1\nrouter.get('/transactions', (req, res) =&gt; ctrl.list(req, res)); // fix 2\n\nclass TransactionController2 {\n  #service;                                            // runtime-private\n  constructor(service) { this.#service = service; }\n  list = async (req, res) =&gt; {                         // fix 3: arrow field, one copy per instance\n    res.json(await this.#service.list(req.user.id));\n  };\n}</pre>NestJS và Fastify gọi handler qua instance nên ít gặp lỗi này; nó hay xuất hiện khi truyền method làm callback (<code>emitter.on('x', this.onX)</code>, <code>items.map(this.format)</code>)."},
  "w0k3": {c:"Callback kiểu error-first <code>(err, data) =&gt; ...</code> là cách viết async gốc của Node. Promise đại diện cho một giá trị trong tương lai, có ba trạng thái pending, fulfilled, rejected và chỉ settle một lần. <code>async</code>/<code>await</code> là cú pháp trên Promise: <code>await</code> tạm dừng function, trả quyền cho event loop và tiếp tục ở một microtask khi promise settle.", e:"<ul><li>Callback dễ sai: gọi callback hai lần, quên <code>return</code> sau khi gọi lỗi, <code>throw</code> trong callback không bắt được bằng try/catch bên ngoài. Dùng <code>util.promisify</code> hoặc bản promise sẵn có: <code>node:fs/promises</code>, <code>node:timers/promises</code>, <code>node:stream/promises</code>, <code>node:dns/promises</code>.</li> <li>Callback của <code>then</code> luôn chạy bất đồng bộ (microtask), kể cả khi promise đã resolve. <code>async function</code> luôn trả Promise, giá trị <code>return</code> được bọc lại, <code>throw</code> thành rejection.</li> <li><code>Promise.all</code>: fail-fast, reject với lỗi đầu tiên nhưng không hủy các promise còn lại, chúng vẫn chạy. <code>allSettled</code>: không bao giờ reject, trả mảng <code>{status, value | reason}</code>. <code>race</code>: settle theo promise xong đầu tiên, kể cả khi đó là reject; dùng làm timeout được nhưng việc thua cuộc vẫn chạy tiếp. <code>any</code>: lấy promise fulfill đầu tiên; tất cả reject thì ném <code>AggregateError</code>.</li> <li><code>await</code> trong vòng <code>for</code> là tuần tự, cộng dồn latency. Ngược lại <code>Promise.all(ids.map(load))</code> với 10.000 id là 10.000 query cùng lúc, cạn connection pool. Giới hạn concurrency bằng batch hoặc thư viện kiểu <code>p-limit</code>.</li> <li><code>items.forEach(async (x) =&gt; ...)</code> không chờ gì cả: forEach bỏ qua promise trả về, request trả response trước khi xong việc và lỗi thành unhandled rejection.</li></ul>", x:"Endpoint <code>GET /dashboard</code> của Expense Tracker mất 600 ms vì ba query độc lập chạy tuần tự (tổng chi tháng, top danh mục, ngân sách còn lại), mỗi query khoảng 200 ms. Còn job nhắc ngân sách gửi push tới mọi thiết bị của user thì fail cả lô chỉ vì một token hết hạn:<pre>// Before: ~600 ms, each await waits for the previous one\nconst total = await reports.monthTotal(userId, month);\nconst top = await reports.topCategories(userId, month);\nconst budget = await budgets.remaining(userId, month);\n\n// After: ~200 ms, independent queries run concurrently\nconst [total2, top2, budget2] = await Promise.all([\n  reports.monthTotal(userId, month),\n  reports.topCategories(userId, month),\n  budgets.remaining(userId, month),\n]);\n\n// Push: one bad token must not fail the others\nconst results = await Promise.allSettled(devices.map((d) =&gt; push.send(d.token, msg)));\nconst dead = devices.filter((_, i) =&gt; results[i].status === 'rejected');\nawait deviceRepo.markInvalid(dead.map((d) =&gt; d.id));</pre><code>Promise.all</code> chỉ đúng khi các query thực sự độc lập và pool đủ kết nối. Nếu ba query phải đọc cùng một snapshot nhất quán thì chúng cần chạy trong một transaction, khi đó lại phải tuần tự trên cùng một connection."},
  "w0k4": {c:"Lỗi trong code bất đồng bộ đi theo promise rejection chứ không theo call stack: <code>try/catch</code> chỉ bắt được khi promise được <code>await</code> bên trong khối <code>try</code>. Rejection không ai xử lý sinh sự kiện <code>unhandledRejection</code>; từ Node 15 chế độ mặc định là <code>throw</code>, process thoát với exit code 1. <code>Error.cause</code> (ES2022) giữ lỗi gốc khi bọc lỗi; <code>AggregateError</code> gom nhiều lỗi trong <code>.errors</code>.", e:"<ul><li><code>return promise</code> trong <code>try</code> mà không <code>await</code>: function trả promise ra ngoài ngay, khi nó reject thì <code>catch</code> bên trong đã qua rồi. Trong try/catch phải <code>return await</code>. ESLint nên bật <code>@typescript-eslint/no-floating-promises</code>, <code>no-misused-promises</code> và <code>return-await</code> ở chế độ <code>in-try-catch</code>.</li> <li>Quên <code>await</code>: <code>if (await user.canEdit())</code> viết thành <code>if (user.canEdit())</code> luôn đúng vì Promise là truthy. Floating promise (ghi audit log, gửi push không await) thì lỗi của nó không có ai bắt và có thể làm sập process.</li> <li>Handler <code>process.on('unhandledRejection')</code> chỉ để log có ngữ cảnh rồi shutdown có kiểm soát, không phải để nuốt lỗi và chạy tiếp. Lỗi ném trong callback của <code>setTimeout</code> hay listener EventEmitter không đi vào promise chain nào cả, nó thành uncaught exception.</li> <li>Bọc lỗi giữ nguyên nguyên nhân: <code>throw new Error('import failed', { cause: err })</code>. <code>util.inspect</code>/<code>console.log</code> của Node in cả chuỗi <code>[cause]: ...</code>; cấu hình logger để serialize <code>cause</code>. Luôn <code>throw</code> instance của <code>Error</code>, đừng throw string (mất stack).</li> <li>Express 4 không bắt rejection của async handler (request treo hoặc process sập); Express 5 tự chuyển promise bị reject vào <code>next(err)</code>. NestJS, Fastify xử lý async handler sẵn.</li></ul> Kiểu dữ liệu: trong TypeScript strict, biến trong <code>catch (e)</code> là <code>unknown</code>; phải narrow (<code>e instanceof Error</code>) trước khi đọc <code>e.message</code>.", x:"Pod của Expense Tracker API restart vài lần mỗi ngày, log chỉ có <code>Error: getaddrinfo ENOTFOUND</code> không rõ từ đâu. Nguyên nhân là một floating promise gửi push sau khi tạo giao dịch; khi dịch vụ push lỗi DNS thì rejection không ai bắt và Node thoát với code 1. Cùng chỗ đó, lỗi DB bị bọc mất nguyên nhân:<pre>async function createTransaction(input) {\n  let tx;\n  try {\n    tx = await repo.insert(input);\n  } catch (err) {\n    // keep the original error for logs, expose a domain error upward\n    throw new Error('Could not save transaction', { cause: err });\n  }\n  // BUG (old): push.notify(tx) without await or catch -&gt; unhandledRejection -&gt; exit 1\n  push.notify(tx).catch((err) =&gt; log.warn({ err, txId: tx.id }, 'push failed'));\n  return tx;\n}\n\nprocess.on('unhandledRejection', (reason) =&gt; {\n  log.fatal({ err: reason }, 'unhandled rejection');\n  shutdown(1);                       // graceful close, then exit; don't keep running\n});</pre>Push không phải phần bắt buộc của request nên được \"fire and forget\" có chủ đích với <code>.catch</code>; tốt hơn nữa là đẩy vào queue (BullMQ) để có retry."},
  "w0k5": {c:"Iterator là object có <code>next()</code> trả <code>{ value, done }</code>; iterable là object có <code>[Symbol.iterator]()</code> trả iterator, và <code>for...of</code>, spread, destructuring đều dựa trên protocol này. Generator (<code>function*</code>) tạo iterator lười, dừng ở mỗi <code>yield</code>. Async iterator có <code>[Symbol.asyncIterator]()</code>, <code>next()</code> trả Promise và được duyệt bằng <code>for await...of</code>.", e:"<ul><li>Lười: giá trị chỉ được tính khi bên ngoài kéo, nên biểu diễn được chuỗi vô hạn hoặc dữ liệu lớn hơn RAM. Từ Node 22 có iterator helpers trên <code>Iterator.prototype</code>: <code>map</code>, <code>filter</code>, <code>take</code>, <code>drop</code>, <code>toArray</code>…; <code>Array.fromAsync</code> gom một async iterable thành mảng.</li> <li>Iterator chỉ dùng một lần: duyệt lại cùng generator object lần hai thì rỗng.</li> <li>Thoát sớm bằng <code>break</code>, <code>return</code> hoặc throw trong <code>for...of</code> sẽ gọi <code>iterator.return()</code>, khối <code>finally</code> trong generator chạy, đó là chỗ đóng cursor, release connection.</li> <li>Readable stream, <code>readline</code>, <code>events.on(emitter, 'x')</code> đều là async iterable. <code>for await</code> xử lý từng phần tử một, phần tử sau chỉ được kéo khi phần tử trước xong, nên có backpressure tự nhiên. Async generator dùng làm transform trong <code>stream.pipeline()</code> được.</li> <li>Bẫy: <code>for await (const r of promises)</code> với mảng promise đã chạy sẵn. Nếu promise thứ hai reject trong lúc đang chờ promise thứ nhất, rejection đó chưa có ai xử lý và process sập vì unhandled rejection. Dùng <code>Promise.all</code>/<code>allSettled</code> cho mảng promise, để <code>for await</code> cho nguồn kéo dần.</li></ul> Câu hỏi hay gặp: \"duyệt hết các trang của một API phân trang thế nào cho gọn?\" Async generator ẩn logic phân trang, bên gọi chỉ cần <code>for await</code>.", x:"Export CSV cả năm cho một user có 300.000 giao dịch: bản đầu <code>SELECT *</code> rồi build chuỗi trong RAM, pod vượt memory limit. Bản sửa dùng async generator đọc theo keyset pagination và stream thẳng ra response:<pre>async function* transactionsOf(userId, year, pageSize = 1000) {\n  let after = 0;\n  while (true) {\n    const rows = await repo.page({ userId, year, afterId: after, limit: pageSize });\n    if (rows.length === 0) return;\n    yield* rows;                       // hand rows out one by one\n    after = rows.at(-1).id;\n  }\n}\n\nasync function* toCsv(rows) {\n  yield 'date,amount,category,note\\n';\n  for await (const r of rows) {\n    yield [r.date, (r.amountCents / 100).toFixed(2), r.category, csvEscape(r.note)].join(',') + '\\n';\n  }\n}\n\n// Fastify: reply.send accepts a Readable\nreply.type('text/csv').send(Readable.from(toCsv(transactionsOf(userId, 2026))));</pre>Client tải chậm thì stream tự giảm tốc kéo dữ liệu, generator không đọc trang tiếp theo cho tới khi cần. Keyset (<code>WHERE id &gt; $after</code>) thay cho <code>OFFSET</code> để mỗi trang có chi phí như nhau."},
  "w0k6": {c:"Shallow copy chỉ sao chép tầng đầu (<code>{...obj}</code>, <code>Object.assign</code>, <code>[...arr]</code>), các object lồng bên trong vẫn dùng chung tham chiếu. Deep copy tạo bản độc lập ở mọi tầng; <code>structuredClone</code> (global từ Node 17) làm việc này theo thuật toán structured clone. <code>Map</code>/<code>Set</code> là collection có key kiểu bất kỳ; <code>WeakMap</code>/<code>WeakRef</code> giữ tham chiếu yếu, không ngăn GC thu hồi object.", e:"<ul><li><code>structuredClone</code> giữ được <code>Date</code>, <code>Map</code>, <code>Set</code>, <code>RegExp</code>, typed array, <code>BigInt</code>, <code>Error</code> và cả tham chiếu vòng; nhưng ném <code>DataCloneError</code> với function, làm mất prototype của class (clone một <code>Money</code> ra plain object, <code>instanceof</code> là false), bỏ getter/setter và key kiểu symbol.</li> <li><code>JSON.parse(JSON.stringify(x))</code>: <code>Date</code> thành string, <code>undefined</code> bị bỏ, <code>Map</code> thành <code>{}</code>, <code>NaN</code> thành <code>null</code>, <code>BigInt</code> thì ném lỗi. Chỉ hợp khi dữ liệu vốn là JSON thuần.</li> <li><code>Object.freeze</code> là shallow, object lồng bên trong vẫn sửa được; <code>readonly</code>/<code>Readonly</code> của TypeScript chỉ có ở compile time. Immutability ở backend chủ yếu dành cho config, value object (<code>Money</code> trả object mới thay vì sửa chính nó) và object dùng chung giữa các request.</li> <li><code>Map</code> so với object làm dictionary: key kiểu bất kỳ, giữ thứ tự chèn, có <code>size</code>, không đụng key <code>__proto__</code>/<code>constructor</code>. <code>Set</code> để khử trùng lặp; từ Node 22 có <code>union</code>, <code>intersection</code>, <code>difference</code>.</li> <li><code>WeakMap</code>: key phải là object (hoặc symbol chưa đăng ký), không duyệt được, entry biến mất khi key bị GC; hợp để gắn metadata vào object có vòng đời riêng như request, socket. <code>WeakRef</code>/<code>FinalizationRegistry</code> không đảm bảo thời điểm (thậm chí có chạy hay không), chỉ dùng cho tối ưu cache, không dùng cho logic đúng sai.</li></ul>", x:"Sự cố nghiêm trọng nhất của loại này: user A mở danh sách giao dịch thì thấy bộ lọc danh mục của user B. Filter mặc định nằm ở module scope, mỗi request \"copy\" bằng spread rồi push vào mảng lồng bên trong, thực chất là sửa mảng dùng chung cho mọi request:<pre>const DEFAULT_FILTER = { categories: [], from: null, to: null };\n\nfunction buildFilter(query) {\n  const f = { ...DEFAULT_FILTER };        // shallow: f.categories IS DEFAULT_FILTER.categories\n  if (query.category) f.categories.push(query.category);  // BUG: mutates shared state\n  return f;\n}\n\n// Fix 1: build fresh nested values\nfunction buildFilter2(query) {\n  return { ...DEFAULT_FILTER, categories: query.category ? [query.category] : [] };\n}\n// Fix 2: make the default deeply immutable so mistakes throw in strict mode\nconst DEFAULTS = Object.freeze({ categories: Object.freeze([]), from: null, to: null });</pre>Bài học: state ở module scope sống suốt vòng đời process và được chia sẻ giữa mọi request đồng thời; Node không có \"mỗi request một thread\" để cô lập giúp bạn."},
  "w0k7": {c:"<code>strict: true</code> bật cả nhóm kiểm tra: <code>strictNullChecks</code>, <code>noImplicitAny</code>, <code>strictFunctionTypes</code>, <code>strictPropertyInitialization</code>, <code>useUnknownInCatchVariables</code>…; từ TypeScript 6.0 (03/2026) strict đã là mặc định khi tsconfig không ghi gì, và TypeScript 7.0 giữ nguyên mặc định này. Union (<code>A | B</code>) mô tả giá trị là một trong nhiều kiểu; discriminated union có một trường tag chung để compiler phân biệt; narrowing là việc compiler thu hẹp kiểu sau các phép kiểm tra.", e:"<ul><li>Narrowing qua <code>typeof</code>, <code>instanceof</code>, <code>in</code>, so sánh <code>===</code> với tag, truthiness, type predicate (<code>x is Expense</code>) và assertion function (<code>asserts x is T</code>). Narrowing của biến <code>let</code> có thể bị mất bên trong callback vì compiler không biết callback chạy lúc nào.</li> <li>Discriminated union + <code>switch</code> trên tag + nhánh <code>default</code> gán vào <code>never</code> cho exhaustive check: thêm biến thể mới là compile lỗi ở mọi chỗ chưa xử lý. Cũng dùng để mô hình kết quả nghiệp vụ (<code>{ ok: true, value } | { ok: false, error }</code>) thay cho throw.</li> <li>Generics: để kiểu chảy theo dữ liệu (<code>function paginate&lt;T extends { id: string }&gt;(rows: T[])</code>). Đừng thêm tham số generic chỉ xuất hiện một lần, đó chỉ là cast trá hình.</li> <li>Utility types: <code>Partial</code>, <code>Required</code>, <code>Pick</code>, <code>Omit</code>, <code>Record</code>, <code>Readonly</code>, <code>ReturnType</code>, <code>Awaited</code>, <code>NonNullable</code>. <code>Omit</code> không phân phối trên union. <code>satisfies</code> kiểm tra giá trị khớp kiểu mà vẫn giữ kiểu cụ thể nhất.</li> <li><code>unknown</code> vs <code>any</code>: <code>any</code> tắt kiểm tra và lây sang mọi biểu thức chạm vào nó; <code>unknown</code> buộc narrow trước khi dùng. <code>JSON.parse</code>, <code>req.body</code> của nhiều framework trả <code>any</code>, nên ép thành <code>unknown</code> rồi parse bằng schema.</li></ul> Nên bật thêm <code>noUncheckedIndexedAccess</code> (không nằm trong strict): <code>rows[0]</code> có kiểu <code>T | undefined</code>, bắt được lỗi truy cập mảng rỗng.", x:"Expense Tracker thêm loại giao dịch chuyển tiền giữa hai ví. Nhờ discriminated union và exhaustive check, build báo lỗi đúng hàm tính số dư chưa xử lý <code>transfer</code>, thay vì để số dư sai lọt lên production:<pre>type Transaction =\n  | { kind: 'expense'; walletId: string; amountCents: number; categoryId: string }\n  | { kind: 'income'; walletId: string; amountCents: number }\n  | { kind: 'transfer'; fromWalletId: string; toWalletId: string; amountCents: number };\n\nfunction balanceDelta(tx: Transaction, walletId: string): number {\n  switch (tx.kind) {\n    case 'expense': return tx.walletId === walletId ? -tx.amountCents : 0;\n    case 'income':  return tx.walletId === walletId ? tx.amountCents : 0;\n    case 'transfer':\n      if (tx.fromWalletId === walletId) return -tx.amountCents;\n      return tx.toWalletId === walletId ? tx.amountCents : 0;\n    default: {\n      const unreachable: never = tx;   // compile error when a new kind is added\n      throw new Error('Unknown kind: ' + JSON.stringify(unreachable));\n    }\n  }\n}\n\ntype TransactionPatch = Partial&lt;Omit&lt;Extract&lt;Transaction, { kind: 'expense' }&gt;, 'kind'&gt;&gt;;</pre>Trong nhánh <code>'expense'</code>, <code>tx.categoryId</code> truy cập được; truy cập nó ở nhánh <code>'income'</code> là compile lỗi."},
  "w0k8": {c:"Có ba cách chạy TypeScript trên Node: compile bằng <code>tsc</code> (hoặc bundler/SWC) ra JS rồi chạy; dùng loader như <code>tsx</code> (esbuild) chạy thẳng; hoặc dùng type stripping có sẵn của Node, bật mặc định từ v23.6/v22.18 và stable từ v25.2/v24.12. Cả <code>tsx</code> lẫn Node chỉ xóa type, không kiểm tra kiểu, nên <code>tsc --noEmit</code> vẫn là bước bắt buộc trong CI.", e:"<ul><li><code>\"module\": \"nodenext\"</code> (kéo theo <code>moduleResolution: nodenext</code>) bắt TypeScript mô phỏng đúng cách Node phân giải: file là ESM hay CJS tùy đuôi và trường <code>\"type\"</code> trong package.json, import tương đối trong ESM phải ghi đuôi file. Khi chạy .ts trực tiếp thì ghi đuôi <code>.ts</code> và bật <code>allowImportingTsExtensions</code> (kèm <code>noEmit</code>) hoặc <code>rewriteRelativeImportExtensions</code> nếu vẫn emit.</li> <li>Type stripping chỉ xóa cú pháp kiểu. Cú pháp cần sinh code JS sẽ lỗi <code>ERR_UNSUPPORTED_TYPESCRIPT_SYNTAX</code>: <code>enum</code>, <code>namespace</code> có code runtime, parameter properties (<code>constructor(private repo: Repo)</code>), <code>import x = require()</code>. Decorator không được hỗ trợ, nên app NestJS (decorator kiểu legacy cùng <code>emitDecoratorMetadata</code>) vẫn phải build bằng <code>tsc</code> hoặc SWC. Flag <code>--experimental-transform-types</code> đã bị gỡ ở Node 26. Bật <code>erasableSyntaxOnly</code> trong tsconfig để <code>tsc</code> báo các cú pháp này sớm.</li> <li>Import type phải có từ khóa <code>type</code> (<code>import type { Tx }</code> hoặc <code>import { type Tx }</code>), nếu không Node coi là import giá trị và lỗi lúc chạy; <code>verbatimModuleSyntax</code> ép điều này ở compile time.</li> <li>Node bỏ qua tsconfig: <code>paths</code> không hoạt động, thay bằng subpath imports (<code>\"#src/*\"</code> trong package.json). Node không xử lý .ts trong <code>node_modules</code> và không hỗ trợ .tsx.</li> <li>TypeScript 6.0 (03/2026) đổi mặc định (<code>strict</code> bật, <code>types</code> mặc định rỗng nên phải khai báo <code>\"types\": [\"node\"]</code>) và deprecate <code>baseUrl</code>, <code>moduleResolution: node10</code>, <code>target: es5</code>; TypeScript 7.0 (bản port native viết bằng Go, 07/2026) nhanh hơn khoảng 8 đến 12 lần và biến các option đó thành lỗi.</li></ul> Production: nhiều team vẫn build ra JS để start nhanh và kiểm soát source map; dev dùng <code>node --watch src/main.ts</code>.", x:"Expense Tracker API (Fastify) chuyển sang chạy .ts trực tiếp trong dev. Ngay lần chạy đầu: <code>SyntaxError: The requested module './types.ts' does not provide an export named 'Transaction'</code>. Lý do: <code>Transaction</code> chỉ là type, khi strip xong Node vẫn thấy một named import giá trị không tồn tại:<pre>// src/routes/tx.ts\nimport { Transaction, toCents } from './types.ts';        // BUG at runtime\nimport { type Transaction, toCents } from './types.ts';   // fix\n\n// tsconfig.json (relevant part)\n{\n  \"compilerOptions\": {\n    \"module\": \"nodenext\",\n    \"target\": \"es2024\",\n    \"strict\": true,\n    \"noEmit\": true,\n    \"allowImportingTsExtensions\": true,\n    \"verbatimModuleSyntax\": true,\n    \"erasableSyntaxOnly\": true,\n    \"types\": [\"node\"]\n  }\n}\n\n// package.json scripts\n\"dev\": \"node --watch src/main.ts\",\n\"typecheck\": \"tsc --noEmit\",\n\"test\": \"node --test\"</pre>Đồng thời đổi các <code>enum TxKind</code> thành union literal (<code>type TxKind = 'income' | 'expense'</code>) hoặc object <code>as const</code>, vì enum không qua được type stripping."},
  "w0k9": {c:"Mọi dữ liệu đi vào từ bên ngoài (body, query, header, biến môi trường, webhook, message trong queue, file CSV) phải được coi là <code>unknown</code>. Validate ở biên bằng schema: một schema vừa kiểm tra lúc chạy vừa sinh type qua <code>z.infer</code>, nên không có hai nguồn sự thật. \"Parse, don't validate\": hàm parse nhận <code>unknown</code> và trả dữ liệu đã đúng kiểu, hoặc lỗi.", e:"<ul><li><code>req.body as CreateTxDto</code> chỉ thuyết phục compiler, không kiểm tra gì lúc chạy; client gửi <code>amount: \"abc\"</code> vẫn đi thẳng xuống DB.</li> <li><code>parse</code> ném <code>ZodError</code>, <code>safeParse</code> trả <code>{ success, data }</code> hoặc <code>{ success: false, error }</code>. Zod 4 (stable từ 07/2025): validator dạng top-level <code>z.email()</code>, <code>z.uuid()</code>, <code>z.iso.datetime()</code>, tham số <code>error</code> thống nhất để tùy biến message, <code>z.prettifyError</code>/<code>z.treeifyError</code> để format lỗi.</li> <li>Query string luôn là string: <code>z.coerce.number()</code> cho <code>limit</code>. Bẫy: <code>z.coerce.boolean()</code> dùng <code>Boolean(x)</code> nên <code>\"false\"</code> thành true; Zod 4 có <code>z.stringbool()</code> cho trường hợp này.</li> <li><code>z.object</code> mặc định bỏ key lạ; <code>z.strictObject</code> báo lỗi. Không bao giờ spread thẳng body vào câu insert: đó là mass assignment, client gửi kèm <code>userId</code> là ghi giao dịch vào tài khoản người khác. <code>userId</code> lấy từ token đã xác thực.</li> <li><code>.transform</code> để chuẩn hóa (chuỗi tiền thành cents, trim note); khi có transform thì <code>z.input</code> khác <code>z.output</code>. Parse <code>process.env</code> lúc khởi động để thiếu biến là fail ngay, không phải lúc request đầu tiên.</li></ul> Chỉ parse ở biên; bên trong domain tin vào type. Framework có chỗ cắm sẵn: type provider của Fastify, pipe của NestJS.", x:"Lab module 0: schema cho <code>POST /transactions</code> của Expense Tracker. Bản cũ cast body và từng nhận <code>amount: 12.5</code> (float) lẫn <code>userId</code> do client gửi. Bản mới (Zod 4):<pre>import { z } from 'zod';\nimport { toCents } from '../domain/money.ts';\n\nexport const CreateTransaction = z.strictObject({\n  walletId: z.uuid(),\n  amount: z.string()\n    .regex(/^-?\\d+(\\.\\d{1,2})?$/, 'at most 2 decimals')\n    .transform(toCents),                       // \"12.34\" -&gt; 1234\n  categoryId: z.uuid().optional(),\n  note: z.string().trim().max(200).default(''),\n  occurredAt: z.iso.datetime({ offset: true }),\n});\nexport type CreateTransactionInput = z.infer&lt;typeof CreateTransaction&gt;; // amount: number\n\nexport const ListQuery = z.object({\n  limit: z.coerce.number().int().min(1).max(100).default(20),\n  includeDeleted: z.stringbool().default(false),   // \"false\" -&gt; false\n});\n\nconst r = CreateTransaction.safeParse(body);\nif (!r.success) return reply.code(400).send({ error: z.prettifyError(r.error) });\nawait service.create(user.id, r.data);</pre>Body có <code>userId</code> lạ, <code>walletId</code> sai định dạng và <code>amount</code> là number sẽ nhận 400 với cả ba lỗi liệt kê cùng lúc. Hàm parse một dòng CSV sao kê dùng lại đúng schema này nên API và import có cùng luật."},
  "w1k0": {c:"Node.js gồm V8 (biên dịch JIT và chạy JavaScript, quản lý heap và GC), libuv (event loop, async I/O đa nền tảng, thread pool) và lớp binding C++ cùng thư viện core (<code>node:fs</code>, <code>node:http</code>, <code>node:crypto</code>…). \"Single-threaded\" nghĩa là code JavaScript của bạn chạy trên một thread chính với một call stack; bản thân process vẫn có nhiều thread khác (thread pool của libuv, thread GC và compiler của V8).", e:"<ul><li>Network I/O (TCP, HTTP, socket) không dùng thread pool: libuv dùng cơ chế non-blocking của OS (epoll trên Linux, kqueue trên macOS, IOCP trên Windows), một thread theo dõi hàng chục nghìn kết nối.</li> <li>Thread pool (mặc định 4 thread, tối đa 1024, chỉnh bằng <code>UV_THREADPOOL_SIZE</code>) chạy những việc OS không có API async tốt: phần lớn thao tác <code>fs</code>, <code>dns.lookup</code> (getaddrinfo), crypto async (<code>pbkdf2</code>, <code>scrypt</code>, <code>randomBytes</code>…), <code>zlib</code> async, và native addon như <code>bcrypt</code>.</li> <li>Pool dùng chung cho cả process: vài request hash mật khẩu chiếm hết 4 slot là <code>fs.readFile</code> và <code>dns.lookup</code> phải xếp hàng. Mọi HTTP call ra ngoài theo hostname đều qua <code>dns.lookup</code>, nên triệu chứng là latency gọi API bên thứ ba tăng \"không rõ lý do\".</li> <li><code>UV_THREADPOOL_SIZE</code> phải có hiệu lực trước khi pool được dùng lần đầu; cách chắc chắn là đặt biến môi trường khi khởi động process. Tăng quá số core chỉ thêm context switch với việc CPU-bound.</li> <li>Mô hình này hợp với tải I/O-bound (nhiều kết nối, mỗi request ít CPU). Việc CPU-bound trên main thread chặn mọi request; scale bằng nhiều process (replica, cluster) hoặc <code>worker_threads</code>.</li></ul> Hệ quả hay bị hỏi: không có \"một thread cho mỗi request\", nên state ở module scope dùng chung cho mọi request; context theo request phải truyền tường minh hoặc dùng <code>AsyncLocalStorage</code>.", x:"Đợt đăng ký người dùng hàng loạt sau một chiến dịch marketing: p99 của <code>POST /auth/login</code> tăng lên vài giây, đồng thời <code>POST /imports</code> (đọc file tạm bằng <code>fs</code>) và các call tới dịch vụ tỷ giá cũng chậm theo, dù CPU mới khoảng 50%. Nguyên nhân là <code>scrypt</code> với tham số cao chiếm trọn 4 thread của pool:<pre>import { scrypt } from 'node:crypto';\nimport { promisify } from 'node:util';\nconst scryptAsync = promisify(scrypt);\n\n// Each call occupies one libuv pool thread for ~100 ms.\n// 4 threads -&gt; the 5th login, every fs.readFile and dns.lookup now wait in line.\nexport async function hashPassword(password, salt) {\n  return scryptAsync(password, salt, 64, { N: 2 ** 15, r: 8, p: 1, maxmem: 64 * 1024 * 1024 });\n}</pre>Cách xử lý: đặt <code>UV_THREADPOOL_SIZE</code> bằng số core trong Dockerfile/manifest, giới hạn số login đồng thời mỗi pod (rate limit theo IP và tài khoản), và tách các tác vụ nặng sang process hoặc service riêng khi tải tiếp tục tăng. Đo trước và sau bằng p99 latency của từng endpoint chứ không chỉ nhìn CPU."},
  "w1k1": {c:"Event loop của Node (libuv) lặp qua các phase theo thứ tự: timers → pending callbacks → idle/prepare → poll → check → close callbacks. Sau mỗi callback, Node xả hết hàng <code>process.nextTick</code> rồi tới hàng microtask (Promise) trước khi chạy callback tiếp theo.", e:"<ul><li>timers: chạy callback của <code>setTimeout</code>/<code>setInterval</code> đã tới hạn; delay là ngưỡng tối thiểu, không phải thời điểm chính xác (<code>0</code> bị đổi thành 1 ms). poll: lấy sự kiện I/O mới và chạy callback; nếu không còn việc thì block chờ I/O tới hạn timer gần nhất. check: <code>setImmediate</code>. close: các sự kiện <code>'close'</code> như <code>socket.on('close')</code>.</li> <li>Trong CommonJS, hàng <code>nextTick</code> được xả trước hàng Promise. Cả hai đều xả cạn trước khi event loop đi tiếp, nên <code>nextTick</code> hoặc <code>then</code> đệ quy làm I/O \"chết đói\"; <code>setImmediate</code> đệ quy thì không vì mỗi vòng lặp chỉ chạy những immediate đã có từ đầu phase.</li> <li><code>setTimeout(fn, 0)</code> và <code>setImmediate</code> gọi từ main module: thứ tự không xác định (phụ thuộc vào thời gian chuẩn bị vòng lặp). Gọi từ trong một I/O callback: <code>setImmediate</code> luôn chạy trước, vì sau poll là check.</li> <li>Bẫy ESM: code top-level của module ESM chạy bên trong một promise job, nên ở đó <code>Promise.resolve().then(...)</code> in trước <code>process.nextTick(...)</code>, ngược với file .cjs.</li> <li>Tài liệu Node khuyên dùng <code>queueMicrotask</code> hoặc <code>setImmediate</code> cho code mới; <code>nextTick</code> chủ yếu để emit sự kiện sau khi caller kịp gắn listener.</li></ul> Interviewer thường đưa một đoạn code và yêu cầu đoán output; trả lời theo từng bước: code đồng bộ, nextTick, microtask, rồi các phase.", x:"Hai đoạn dưới đã chạy thử bằng Node 24 (file .cjs), mỗi đoạn 20 lần, output luôn như chú thích. Cố ý tách riêng: nếu để chung một file, <code>timeout</code> ở top-level có thể chạy trước hoặc sau các callback I/O tùy tốc độ đọc file:<pre>// a.cjs\nconsole.log('1 sync');\nsetTimeout(() =&gt; console.log('timeout'), 0);\nPromise.resolve().then(() =&gt; console.log('promise'));\nprocess.nextTick(() =&gt; console.log('nextTick'));\nconsole.log('2 sync');\n// 1 sync, 2 sync, nextTick, promise, timeout\n\n// b.cjs: inside an I/O callback (poll phase), check comes before the next timers phase\nconst fs = require('node:fs');\nfs.readFile(__filename, () =&gt; {\n  setTimeout(() =&gt; console.log('io: timeout'), 0);\n  setImmediate(() =&gt; console.log('io: immediate'));\n  Promise.resolve().then(() =&gt; console.log('io: promise'));\n  process.nextTick(() =&gt; console.log('io: nextTick'));\n});\n// io: nextTick, io: promise, io: immediate, io: timeout</pre>Sự cố thật: worker tính lại số dư cho mọi ví sau khi import xử lý từng ví bằng <code>process.nextTick(next)</code> để \"không chặn\". Kết quả là health check <code>/healthz</code> timeout và Kubernetes restart pod giữa chừng, vì hàng nextTick không bao giờ cạn cho tới khi xong hết. Đổi sang <code>setImmediate(next)</code> (hoặc <code>await setImmediate()</code> từ <code>node:timers/promises</code>) để mỗi vòng lặp còn chỗ cho I/O."},
  "w1k2": {c:"Chặn event loop là khi một đoạn JavaScript đồng bộ chạy lâu trên main thread: trong lúc đó không request nào được nhận, timer trễ, health check không trả lời. Event loop delay (lag) là độ trễ giữa lúc một callback lẽ ra chạy và lúc nó thực sự chạy, là chỉ số chính để phát hiện hiện tượng này.", e:"<ul><li>Nguồn hay gặp: tổng hợp báo cáo bằng vòng lặp JS trên hàng trăm nghìn dòng thay vì <code>SUM ... GROUP BY</code> trong SQL; sort/map mảng lớn; <code>JSON.parse</code>/<code>JSON.stringify</code> payload hàng chục MB (đồng bộ, tỷ lệ với kích thước); API <code>*Sync</code> (<code>readFileSync</code>, <code>pbkdf2Sync</code>, <code>zlib.gzipSync</code>, <code>bcrypt.hashSync</code>) trong handler.</li> <li>ReDoS: regex có quantifier lồng nhau như <code>/^(\\w+\\s?)*$/</code> gặp chuỗi dài không khớp sẽ backtrack theo cấp số mũ; mỗi ký tự thêm vào nhân đôi thời gian. Phòng: giới hạn độ dài input trước khi match, tránh <code>(a+)+</code>, kiểm tra regex bằng công cụ như <code>safe-regex2</code>, hoặc dùng engine không backtrack (RE2).</li> <li>Đo: <code>perf_hooks.monitorEventLoopDelay()</code> trả histogram tính bằng nanosecond (<code>percentile(99)</code>, <code>max</code>), export ra metrics và cảnh báo khi p99 vượt ngưỡng; <code>performance.eventLoopUtilization()</code> cho biết tỷ lệ thời gian loop bận. Tìm thủ phạm bằng <code>node --cpu-prof</code> hoặc DevTools qua <code>--inspect</code>.</li> <li>Sửa: đẩy tính toán xuống DB; chia nhỏ vòng lặp và nhường lượt bằng <code>setImmediate</code>; chuyển sang <code>worker_threads</code>; giới hạn kích thước body (Fastify <code>bodyLimit</code> mặc định 1 MiB, <code>express.json()</code> mặc định 100kb) và phân trang response.</li></ul> Câu hỏi vặn: \"hàm <code>async</code> thì có chặn không?\" Có, <code>async</code> không đưa code sang thread khác; vòng lặp nặng trong hàm async vẫn chạy trên main thread cho tới <code>await</code> đầu tiên.", x:"Endpoint <code>GET /reports/yearly</code> của Expense Tracker build cả năm giao dịch thành một object rồi <code>JSON.stringify</code> khoảng 80 MB; mỗi lần có người xuất báo cáo, mọi request khác của pod đứng vài trăm ms. Thêm đo event loop delay để thấy rõ (đoạn dưới chạy thử với một vòng lặp bận 200 ms):<pre>const { monitorEventLoopDelay } = require('node:perf_hooks');\nconst h = monitorEventLoopDelay({ resolution: 20 });\nh.enable();\n\nsetTimeout(() =&gt; {                       // simulate a 200 ms synchronous job\n  const t = Date.now();\n  while (Date.now() - t &lt; 200);\n}, 50);\n\nsetTimeout(() =&gt; {\n  h.disable();\n  console.log('p99 ms', Math.round(h.percentile(99) / 1e6), 'max ms', Math.round(h.max / 1e6));\n}, 400);\n// p99 ms 203 max ms 203\n\n// ReDoS check used on the note field: 26 chars + '!' already takes ~0.4 s\n/^(\\w+\\s?)*$/.test('a'.repeat(26) + '!');</pre>Sửa: tổng hợp bằng SQL theo tháng và danh mục, stream CSV thay vì JSON khổng lồ, giới hạn <code>note</code> 200 ký tự và bỏ regex lồng quantifier. Metric <code>eventloop_delay_p99</code> được đưa lên dashboard cùng p99 latency."},
  "w1k3": {c:"CommonJS (CJS) dùng <code>require()</code> đồng bộ và <code>module.exports</code>, mỗi file được bọc trong một function nên có <code>__dirname</code>, <code>__filename</code>. ES Modules (ESM) dùng <code>import</code>/<code>export</code> tĩnh, được phân tích trước khi chạy, load bất đồng bộ, hỗ trợ top-level <code>await</code>, export là live binding và luôn ở strict mode. Node chọn loại theo đuôi (<code>.mjs</code>/<code>.cjs</code>) hoặc trường <code>\"type\"</code> trong package.json gần nhất, mặc định là <code>\"commonjs\"</code>.", e:"<ul><li><code>\"type\": \"module\"</code> khiến mọi file <code>.js</code> trong package là ESM; file <code>.cjs</code> vẫn là CJS. Trong ESM, import tương đối phải ghi đủ đuôi file, không tự tìm <code>index.js</code>.</li> <li>Trường <code>exports</code> định nghĩa entry công khai của package và chặn deep import (<code>ERR_PACKAGE_PATH_NOT_EXPORTED</code>); conditional exports (<code>\"types\"</code>, <code>\"import\"</code>, <code>\"require\"</code>, <code>\"default\"</code>) cho phép ship cả hai định dạng. Dual package hazard: cùng một package bị load hai lần (bản ESM và bản CJS), singleton bị nhân đôi, <code>instanceof</code> sai.</li> <li><code>require(esm)</code>: không cần flag từ v22.12 và v20.19, hết experimental từ v25.4. Giới hạn: nếu module (hoặc đồ thị nó import) có top-level await thì ném <code>ERR_REQUIRE_ASYNC_MODULE</code>, khi đó dùng <code>import()</code>. <code>require()</code> trả namespace object (default export nằm ở <code>.default</code>), trừ khi module export một giá trị dưới tên <code>\"module.exports\"</code>. Nhờ vậy thư viện ESM-only giờ dùng được từ app CJS.</li> <li>ESM import CJS: default import là <code>module.exports</code>; named import chỉ có khi Node phân tích tĩnh nhận ra được.</li> <li>ESM không có <code>__dirname</code>, <code>__filename</code>, <code>require</code>: dùng <code>import.meta.dirname</code>, <code>import.meta.filename</code> (có từ v20.11/v21.2, hết experimental ở v24.0/v22.16), <code>createRequire(import.meta.url)</code> khi thật sự cần <code>require</code>.</li></ul>", x:"Expense Tracker API chuyển sang ESM để dùng một thư viện chỉ phát hành ESM. Sau khi thêm <code>\"type\": \"module\"</code>, script chạy migration crash ngay: <code>ReferenceError: __dirname is not defined in ES module scope</code>. Đồng thời một import thiếu đuôi báo <code>ERR_MODULE_NOT_FOUND</code>:<pre>// package.json\n{\n  \"type\": \"module\",\n  \"imports\": { \"#src/*\": \"./dist/*\" },\n  \"exports\": { \".\": \"./dist/main.js\" },\n  \"engines\": { \"node\": \"&gt;=24\" }\n}\n\n// scripts/migrate.js\nimport path from 'node:path';\nimport { readdir } from 'node:fs/promises';\nimport { runMigrations } from '#src/db/migrate.js';   // extension required in ESM\n\n// const dir = path.join(__dirname, '../migrations');  // ReferenceError in ESM\nconst dir = path.join(import.meta.dirname, '../migrations');\nconst files = (await readdir(dir)).filter((f) =&gt; f.endsWith('.sql')).sort();\nawait runMigrations(files.map((f) =&gt; path.join(dir, f)));  // top-level await is fine in ESM</pre>Một script CJS cũ còn <code>require('#src/db/migrate.js')</code> vẫn chạy được nhờ <code>require(esm)</code>, cho tới khi ai đó thêm top-level await vào đồ thị module đó và nhận <code>ERR_REQUIRE_ASYNC_MODULE</code>. Kết luận của team: chuyển hẳn sang ESM, chỉ giữ <code>.cjs</code> cho file config bắt buộc."},
  "w1k4": {c:"<code>EventEmitter</code> (<code>node:events</code>) là cơ chế publish/subscribe trong một process: <code>emit</code> gọi lần lượt các listener theo thứ tự đăng ký, đồng bộ, ngay trong call stack hiện tại. Stream, <code>http.Server</code>, socket và <code>process</code> đều kế thừa nó.", e:"<ul><li><code>emit</code> là đồng bộ: listener chậm thì emitter chậm, listener ném lỗi thì lỗi bay về chỗ gọi <code>emit</code>. Listener <code>async</code> reject thì không ai bắt, trừ khi tạo emitter với <code>captureRejections: true</code> để chuyển rejection thành sự kiện <code>'error'</code>.</li> <li><code>on</code>/<code>once</code>/<code>off</code>: <code>off</code> cần đúng tham chiếu function đã đăng ký, nên arrow viết inline thì không gỡ được. <code>events.once(emitter, name)</code> trả Promise (reject nếu có <code>'error'</code> trước), <code>events.on(emitter, name)</code> trả async iterator; cả hai nhận <code>{ signal }</code> để hủy.</li> <li><code>'error'</code> là sự kiện đặc biệt: <code>emit('error', err)</code> mà không có listener thì <code>err</code> được ném ra, không ai bắt là process sập. Mọi stream, socket, client Redis đều phải có listener <code>'error'</code>.</li> <li><code>MaxListenersExceededWarning</code>: hơn 10 listener cho một sự kiện trên một emitter. Đây chỉ là cảnh báo, nhưng gần như luôn báo hiệu leak: đăng ký listener theo request mà không gỡ. Đừng vội <code>setMaxListeners(0)</code> để tắt cảnh báo.</li> <li>EventEmitter chỉ sống trong một process. Khi chạy nhiều replica, sự kiện cần đi qua Redis pub/sub, queue hoặc Socket.IO adapter; dùng emitter cho domain event trong process là được, nhưng đừng coi đó là message bus bền vững.</li></ul>", x:"Expense Tracker có endpoint SSE <code>GET /wallets/:id/stream</code> đẩy số dư mới cho web dashboard. Sau vài giờ, log xuất hiện <code>MaxListenersExceededWarning</code> và memory tăng đều: mỗi kết nối gắn một listener vào emitter toàn cục mà không gỡ khi client ngắt:<pre>import { EventEmitter } from 'node:events';\nexport const walletEvents = new EventEmitter();\nwalletEvents.on('error', (err) =&gt; log.error({ err }, 'walletEvents error'));\n\napp.get('/wallets/:id/stream', (req, reply) =&gt; {\n  reply.raw.writeHead(200, { 'content-type': 'text/event-stream' });\n  const onBalance = (e) =&gt; {\n    if (e.walletId === req.params.id) reply.raw.write('data: ' + JSON.stringify(e) + '\\n\\n');\n  };\n  walletEvents.on('balance', onBalance);\n  // BUG (old): missing cleanup, listener and closure over reply live forever\n  req.raw.on('close', () =&gt; walletEvents.off('balance', onBalance));\n});\n\n// after a transaction is committed\nwalletEvents.emit('balance', { walletId, balanceCents });</pre>Bản sửa gỡ listener khi socket đóng. Khi scale lên 3 pod, client nối vào pod A không nhận sự kiện phát ở pod B, nên bước tiếp theo là publish sự kiện qua Redis pub/sub và mỗi pod tự chuyển vào emitter cục bộ."},
  "w1k5": {c:"<code>Buffer</code> là vùng byte có kích thước cố định nằm ngoài heap JS (subclass của <code>Uint8Array</code>); encoding (<code>utf8</code>, <code>base64</code>, <code>hex</code>, <code>latin1</code>…) chỉ có nghĩa khi chuyển giữa byte và string. Stream xử lý dữ liệu theo từng chunk qua bốn loại Readable, Writable, Duplex, Transform; backpressure là cơ chế để nguồn đọc nhanh không làm ngập đích ghi chậm.", e:"<ul><li><code>Buffer.alloc</code> điền số 0; <code>Buffer.allocUnsafe</code> nhanh hơn nhưng có thể chứa dữ liệu cũ trong bộ nhớ. <code>buf.subarray()</code> chia sẻ bộ nhớ với buffer gốc (<code>buf.slice</code> đã deprecated). Độ dài byte khác độ dài chuỗi: <code>Buffer.byteLength('Ăn trưa')</code> lớn hơn <code>'Ăn trưa'.length</code> vì tiếng Việt có dấu chiếm 2 đến 3 byte UTF-8.</li> <li>Ký tự nhiều byte có thể bị cắt giữa hai chunk; gọi <code>chunk.toString()</code> từng chunk sẽ sinh ký tự lỗi. Dùng <code>setEncoding('utf8')</code>, <code>StringDecoder</code> hoặc <code>TextDecoderStream</code>, những thứ này giữ lại byte dở dang chờ chunk sau.</li> <li>Backpressure: <code>writable.write()</code> trả <code>false</code> khi buffer nội bộ vượt <code>highWaterMark</code>, phải dừng ghi tới sự kiện <code>'drain'</code>. Mặc định <code>highWaterMark</code> là 64 KiB cho byte stream (tăng từ 16 KiB ở Node 22) và 16 object với <code>objectMode</code>. Bỏ qua giá trị trả về của <code>write()</code> là RAM phình ra theo tốc độ chênh lệch.</li> <li><code>pipeline()</code> (<code>node:stream/promises</code>) nối các stream, tự xử lý backpressure, và khi một mắt xích lỗi thì destroy toàn bộ, trả promise reject. <code>.pipe()</code> không chuyển tiếp lỗi và không destroy nguồn, dễ rò file descriptor.</li> <li>Transform tự viết: implement <code>transform(chunk, enc, cb)</code> và <code>flush(cb)</code>; hoặc đưa thẳng một async generator vào <code>pipeline()</code>, gọn và ít lỗi hơn.</li></ul>", x:"Lab module 1: import file CSV sao kê 200 MB vào Expense Tracker. Bản đầu dùng <code>rs.on('data', (c) =&gt; rows.push(...parse(c)))</code>, tích hết vào mảng rồi mới insert; RAM lên hơn 1 GB và một số dòng bị hỏng ở chỗ chunk cắt ngang. Bản sửa (đã chạy thử với file mẫu, kết quả đúng số dòng):<pre>import { createReadStream } from 'node:fs';\nimport { Writable } from 'node:stream';\nimport { pipeline } from 'node:stream/promises';\n\nasync function* toBatches(source, size = 1000) {\n  let rest = '', batch = [];\n  for await (const chunk of source) {           // chunk is a string thanks to encoding\n    const lines = (rest + chunk).split('\\n');\n    rest = lines.pop();                          // last line may be cut in half\n    for (const line of lines) {\n      batch.push(line);\n      if (batch.length === size) { yield batch; batch = []; }\n    }\n  }\n  if (rest) batch.push(rest);\n  if (batch.length) yield batch;\n}\n\nawait pipeline(\n  createReadStream(filePath, { encoding: 'utf8' }),\n  toBatches,\n  new Writable({\n    objectMode: true,\n    write(batch, _enc, cb) { repo.insertMany(parseRows(batch)).then(() =&gt; cb(), cb); },\n  }),\n);</pre>Writable chỉ gọi <code>cb</code> khi insert xong, nên nguồn tự dừng đọc khi DB chậm: RAM giữ ở mức vài chục MB bất kể file lớn cỡ nào. Lỗi ở bất kỳ bước nào làm <code>pipeline</code> reject và đóng file. Trường hợp thực tế cần thêm: bỏ BOM ở đầu file và ghi chú thích hợp cho trường có dấu phẩy trong ngoặc kép (dùng thư viện CSV parser)."},
  "w1k6": {c:"<code>node:fs/promises</code> cung cấp API filesystem trả Promise (chạy trên thread pool của libuv); <code>node:path</code> xử lý đường dẫn theo quy tắc của từng OS. <code>readFile</code> đọc toàn bộ file vào bộ nhớ một lần; file lớn hoặc không biết trước kích thước thì đọc bằng stream, <code>readline</code> hoặc <code>FileHandle</code> theo từng đoạn.", e:"<ul><li><code>readFile</code> file 500 MB tốn 500 MB Buffer, chuyển sang string còn tốn thêm, và chuỗi V8 có giới hạn độ dài (khoảng 2^29 ký tự trên 64-bit) nên file đủ lớn sẽ ném <code>ERR_STRING_TOO_LONG</code>. Đọc theo dòng: <code>readline.createInterface({ input: createReadStream(p), crlfDelay: Infinity })</code> kết hợp <code>for await</code>.</li> <li><code>path.join</code> chỉ nối và chuẩn hóa; <code>path.resolve</code> xử lý từ phải sang trái tới khi được đường dẫn tuyệt đối, nếu không thì ghép với <code>process.cwd()</code>. Đường dẫn tương đối trong code được tính theo cwd lúc chạy, không theo vị trí file; dùng <code>import.meta.dirname</code>.</li> <li>Path traversal: tên file từ client như <code>../../etc/passwd</code>. Sau khi <code>path.resolve(baseDir, name)</code>, kiểm tra kết quả bắt đầu bằng <code>baseDir + path.sep</code>; tốt hơn là không dùng tên file của client làm đường dẫn mà sinh id riêng.</li> <li>Ghi an toàn: ghi vào file tạm rồi <code>rename</code> (atomic trên cùng filesystem) để không bao giờ có file ghi dở. <code>mkdir(p, { recursive: true })</code>, <code>rm(p, { recursive: true, force: true })</code>. <code>fs.watch</code> hành vi khác nhau giữa các OS, đừng dựa vào cho logic quan trọng.</li> <li>API <code>*Sync</code> chỉ dùng lúc khởi động (đọc config, cert), không bao giờ trong handler. Upload: stream thẳng ra đĩa hoặc object storage với giới hạn kích thước, không buffer cả file.</li></ul> Câu hỏi hay gặp: \"<code>fs.promises</code> có nhanh hơn bản sync không?\" Một lời gọi đơn lẻ thì không, nhưng nó không chặn event loop, nên server vẫn phục vụ request khác trong lúc chờ đĩa.", x:"Expense Tracker lưu ảnh hóa đơn đính kèm giao dịch dưới thư mục <code>uploads/</code> (bản dev, trước khi chuyển sang S3). Audit bảo mật phát hiện endpoint tải hóa đơn đọc được file bất kỳ trên server:<pre>import path from 'node:path';\nimport { createReadStream } from 'node:fs';\nimport { stat } from 'node:fs/promises';\n\nconst UPLOAD_DIR = path.resolve(import.meta.dirname, '../uploads');\n\n// BUG (old): GET /receipts/..%2F..%2F.env -&gt; reads the app secrets\n// const file = UPLOAD_DIR + '/' + req.params.name;\n\napp.get('/receipts/:name', async (req, reply) =&gt; {\n  const file = path.resolve(UPLOAD_DIR, req.params.name);\n  if (!file.startsWith(UPLOAD_DIR + path.sep)) return reply.code(404).send();\n  const s = await stat(file).catch(() =&gt; null);\n  if (!s?.isFile()) return reply.code(404).send();\n  return reply.type('image/jpeg').send(createReadStream(file));   // stream, not readFile\n});</pre>Bản sửa resolve rồi kiểm tra prefix, stream file ra thay vì <code>readFile</code>. Thiết kế cuối cùng còn chặt hơn: lưu receipt theo id ngẫu nhiên trong DB gắn với <code>userId</code>, kiểm tra quyền sở hữu, và không bao giờ nhận tên file từ client."},
  "w1k7": {c:"<code>worker_threads</code> chạy nhiều thread JavaScript trong cùng process, mỗi worker có V8 isolate và event loop riêng, giao tiếp qua message (structured clone, có thể transfer <code>ArrayBuffer</code>) hoặc <code>SharedArrayBuffer</code>. <code>child_process</code> tạo process OS riêng (<code>spawn</code>, <code>exec</code>, <code>execFile</code>, <code>fork</code>). <code>cluster</code> fork nhiều process Node cùng lắng nghe một port.", e:"<ul><li>Worker dành cho việc CPU-bound viết bằng JS: parse/tổng hợp dữ liệu lớn, phân loại giao dịch theo luật, tạo báo cáo. Worker không làm I/O nhanh hơn. Khởi tạo một worker tốn thời gian và bộ nhớ cho isolate riêng, nên dùng pool cố định (ví dụ thư viện Piscina) thay vì tạo mỗi request. Dữ liệu gửi qua <code>postMessage</code> bị copy; buffer lớn thì transfer để tránh copy.</li> <li><code>child_process</code> để chạy chương trình bên ngoài (ffmpeg, công cụ PDF, script Python). <code>spawn</code> stream stdout; <code>exec</code> chạy qua shell và buffer output (có <code>maxBuffer</code>). Không bao giờ ghép input người dùng vào chuỗi lệnh <code>exec</code> (shell injection); dùng <code>execFile</code>/<code>spawn</code> với mảng tham số. <code>fork</code> tạo process Node có kênh IPC.</li> <li><code>cluster</code>: process primary chia kết nối cho các worker process (round-robin mặc định, trừ Windows). Trên Kubernetes thường chạy một process mỗi container và scale bằng replica; cluster hay PM2 hợp hơn khi deploy trên VM.</li> <li>Process không chia sẻ bộ nhớ: cache in-memory, rate limit đếm trong RAM, session đều bị tách theo process. Socket.IO nhiều process cần sticky session và adapter (Redis).</li> <li>Worker crash không giết main thread: lắng nghe <code>'error'</code> và <code>'exit'</code> để thay worker mới; main thread crash thì mọi worker chết theo.</li></ul>", x:"Import CSV của Expense Tracker có bước tự động gán danh mục bằng vài trăm luật (so khớp từ khóa, số tiền, merchant) trên từng dòng. Chạy trên main thread, event loop delay p99 lên 400 ms trong suốt quá trình import. Đưa bước này sang worker (khung tối thiểu, đã chạy thử):<pre>// categorize.mjs\nimport { Worker, isMainThread, parentPort, workerData } from 'node:worker_threads';\n\nif (isMainThread) {\n  // in production: a fixed-size pool created once at startup, not one Worker per batch\n  const w = new Worker(new URL(import.meta.url), { workerData: { rules } });\n  w.on('error', (err) =&gt; log.error({ err }, 'categorizer crashed'));\n  w.postMessage(batchOfRows);\n  w.once('message', (categorized) =&gt; repo.insertMany(categorized));\n} else {\n  const { rules } = workerData;\n  parentPort.on('message', (rows) =&gt; parentPort.postMessage(rows.map((r) =&gt; applyRules(r, rules))));\n}</pre>Event loop delay của API trở về dưới 20 ms trong lúc import. Còn việc xuất báo cáo PDF thì dùng <code>spawn</code> một công cụ có sẵn và stream stdout ra response, vì đó là chương trình ngoài chứ không phải code JS."},
  "w1k8": {c:"<code>process</code> là object toàn cục đại diện cho tiến trình hiện tại: <code>env</code>, <code>argv</code>, <code>cwd()</code>, <code>memoryUsage()</code>, <code>exitCode</code>, các listener cho signal và lỗi chưa bắt. <code>AbortController</code>/<code>AbortSignal</code> là cơ chế chuẩn để hủy thao tác bất đồng bộ, được <code>fetch</code>, <code>timers/promises</code>, <code>fs</code>, stream, <code>events.once</code>, <code>child_process</code> hỗ trợ.", e:"<ul><li><code>process.env</code> chỉ chứa string hoặc <code>undefined</code>: <code>\"false\"</code> là truthy, <code>\"3000\"</code> không phải number. Parse và validate env bằng schema lúc khởi động.</li> <li>Signal: <code>SIGTERM</code> là tín hiệu Kubernetes và <code>docker stop</code> gửi khi muốn dừng container, sau grace period (mặc định 30 giây ở Kubernetes, 10 giây ở <code>docker stop</code>) sẽ là <code>SIGKILL</code>. <code>SIGINT</code> là Ctrl+C. Gắn listener là thay hành vi mặc định (thoát ngay), nên handler phải tự thoát. Chạy qua <code>npm start</code> trong container không phải lúc nào cũng chuyển tiếp signal đúng; chạy <code>node</code> trực tiếp hoặc dùng init như <code>docker run --init</code>.</li> <li>Exit code: 0 là thành công, 1 cho uncaught exception và unhandled rejection; bị signal giết thì shell thấy 128+N (143 với SIGTERM, 137 với SIGKILL, thường gặp khi bị OOMKilled). <code>process.exit()</code> cắt ngang ngay, log còn đang ghi bất đồng bộ có thể mất; ưu tiên đặt <code>process.exitCode</code> rồi để event loop tự rỗng.</li> <li><code>uncaughtException</code>: sau lỗi này state của process không còn đáng tin. Log có ngữ cảnh rồi thoát để orchestrator khởi động lại, đừng dùng nó để chạy tiếp.</li> <li><code>AbortSignal.timeout(ms)</code> hủy với lỗi tên <code>TimeoutError</code>; <code>AbortSignal.any([a, b])</code> gộp timeout với việc client ngắt kết nối. Truyền signal xuống mọi tầng (fetch, query) thì việc hủy mới có tác dụng thật.</li></ul>", x:"Mỗi lần deploy, app mobile của Expense Tracker nhận vài lỗi 502 và có job import bị mất nửa chừng: pod nhận <code>SIGTERM</code> nhưng app không xử lý, process chết ngay khi request và job đang chạy. Graceful shutdown cho Expense Tracker API:<pre>let shuttingDown = false;\nasync function shutdown(signal) {\n  if (shuttingDown) return;\n  shuttingDown = true;\n  log.info({ signal }, 'shutting down');\n  const force = setTimeout(() =&gt; process.exit(1), 25_000).unref(); // below the 30 s grace period\n  try {\n    await app.close();          // stop accepting, wait for in-flight requests\n    await importWorker.close(); // BullMQ: let the current job finish\n    await Promise.all([db.end(), redis.quit()]);\n    process.exitCode = 0;\n  } catch (err) {\n    log.error({ err }, 'shutdown failed');\n    process.exitCode = 1;\n  } finally {\n    clearTimeout(force);\n  }\n}\nprocess.once('SIGTERM', shutdown);\nprocess.once('SIGINT', shutdown);\n\n// outbound call with a hard timeout, also cancelled if the client disconnects\nconst signal = AbortSignal.any([AbortSignal.timeout(3000), clientAbort.signal]);\nconst res = await fetch(fxUrl, { signal });</pre>Kèm theo, readiness probe trả lỗi ngay khi <code>shuttingDown</code> để load balancer ngừng gửi request mới trước khi server đóng."},
  "w1k9": {c:"Node.js phát hành theo lịch của Release WG: bản số chẵn lên LTS (Active LTS rồi Maintenance, tổng 30 tháng), bản số lẻ không lên LTS. Tại 19/10/2026: Node 24 (Krypton) là Active LTS tới 20/10/2026 rồi chuyển Maintenance tới 30/04/2028; Node 26 là Current, dự kiến lên LTS ngày 28/10/2026; Node 22 ở Maintenance tới 30/04/2027; Node 20 đã EOL từ 30/04/2026. Từ Node 27, lịch đổi: mỗi năm một bản major, bản nào cũng lên LTS.", e:"<ul><li>Lịch mới (công bố trên blog nodejs.org): mỗi bản có giai đoạn Alpha từ tháng 10 tới tháng 3 (được phép thay đổi breaking), Current từ tháng 4 tới tháng 10, rồi 30 tháng LTS. Node 26 là bản cuối theo mô hình cũ; 27.0.0 ra mắt bản Current vào 2027. Production chỉ chạy LTS; dùng Alpha/Current trong CI để phát hiện sớm vấn đề.</li> <li><code>fetch</code> (dựa trên undici) global và stable từ Node 21. Luôn truyền <code>signal</code> để có timeout, và đọc hết hoặc hủy body để trả kết nối về pool.</li> <li><code>node:test</code> + <code>node:assert</code> (test runner stable từ Node 20) có mock, watch, reporter; <code>--watch</code> (stable từ v22.0/v20.13) thay nodemon; <code>--run</code> chạy script trong package.json không qua npm.</li> <li><code>--env-file</code>/<code>--env-file-if-exists</code> hết experimental từ v24.10/v22.21, cùng <code>process.loadEnvFile()</code>, thay được <code>dotenv</code> cho dev. Không thay secret manager trên production.</li> <li>Permission model: <code>--permission</code> stable từ v23.5/v22.13, cấp quyền bằng <code>--allow-fs-read</code>, <code>--allow-fs-write</code>, <code>--allow-child-process</code>, <code>--allow-worker</code>, <code>--allow-addons</code>; <code>--allow-net</code> có từ v25.0 và vẫn đang phát triển. Đây là \"dây an toàn\" cho code tin cậy, không phải sandbox chống mã độc.</li> <li><code>node:sqlite</code>: thêm ở v22.5, bỏ flag từ v23.4/v22.13, lên release candidate ở v25.7; API đồng bộ, hợp cho test, CLI, dữ liệu nhúng, không thay PostgreSQL cho API nhiều người dùng. Type stripping (chạy .ts trực tiếp) xem chủ đề TypeScript.</li></ul>", x:"Expense Tracker API khởi đầu trên Node 22. Tháng 10/2026 team nâng lên Node 24 (Active LTS, còn hỗ trợ tới 04/2028) và lên lịch đánh giá Node 26 sau khi nó vào LTS, thay vì đợi Node 22 EOL 04/2027 rồi mới chạy. Nhân tiện bỏ bớt dev dependency nhờ built-in:<pre>// package.json\n{\n  \"engines\": { \"node\": \"&gt;=24\" },\n  \"scripts\": {\n    \"dev\": \"node --watch --env-file-if-exists=.env src/main.ts\",\n    \"test\": \"node --test\",\n    \"typecheck\": \"tsc --noEmit\"\n  }\n}\n// removed: nodemon, dotenv, ts-node\n\n# Dockerfile\nFROM node:24-slim\n# run node directly so SIGTERM reaches the app\nCMD [\"node\", \"--permission\", \"--allow-fs-read=/app\", \"--allow-fs-write=/tmp\", \"--allow-worker\", \"dist/main.js\"]</pre>Permission model chặn được một lỗi path traversal ghi file ra ngoài <code>/tmp</code> trong lúc test, nhưng nó không giới hạn network ở Node 24, nên vẫn cần NetworkPolicy ở tầng hạ tầng. Lab import dùng <code>worker_threads</code> nên phải có <code>--allow-worker</code>; native addon (ví dụ <code>bcrypt</code>) cần thêm <code>--allow-addons</code>. Khi bật permission phải chạy toàn bộ test suite để tìm quyền còn thiếu."},
};

const EXPL_ND_23 = {
  "w2k0": {c:"HTTP là giao thức request/response không trạng thái: client gửi method, URL, header và body; server trả status code, header và body. Ngữ nghĩa (method, status, header) được chuẩn hóa trong RFC 9110 và giống nhau dù chạy trên HTTP/1.1, HTTP/2 hay HTTP/3.", e:"<ul><li>Safe và idempotent: <code>GET</code>, <code>HEAD</code>, <code>OPTIONS</code> là safe (không đổi trạng thái); <code>PUT</code>, <code>DELETE</code> là idempotent (gọi N lần, trạng thái server như gọi một lần); <code>POST</code> không idempotent, <code>PATCH</code> không đảm bảo. Proxy, SDK hay app mobile chỉ được tự retry an toàn với request idempotent; muốn retry <code>POST</code> thì cần Idempotency-Key.</li> <li>Status code hay bị hỏi vặn: 401 là chưa xác thực (thiếu hoặc sai token), 403 là đã biết bạn là ai nhưng không có quyền; trả 404 thay 403 khi không muốn lộ tài nguyên của người khác tồn tại. 400 cho request sai cú pháp, 422 (Unprocessable Content) cho dữ liệu đúng cú pháp nhưng sai nghiệp vụ, 409 cho xung đột, 412 khi <code>If-Match</code> không khớp, 429 kèm <code>Retry-After</code>. 201 nên kèm <code>Location</code>; 5xx chỉ dành cho lỗi phía server.</li> <li>Header quan trọng: <code>Content-Type</code>/<code>Accept</code>, <code>Authorization</code>, <code>Cache-Control</code>, <code>ETag</code> + <code>If-None-Match</code> (trả 304, tiết kiệm băng thông cho mobile), <code>If-Match</code> cho optimistic concurrency.</li> <li>Keep-alive: HTTP/1.1 mặc định giữ kết nối. <code>server.keepAliveTimeout</code> của Node mặc định 5 giây; nếu load balancer phía trước có idle timeout dài hơn (ALB mặc định 60 giây), LB có thể gửi request vào socket Node vừa đóng và sinh 502 lác đác. Đặt <code>keepAliveTimeout</code> lớn hơn idle timeout của LB, <code>headersTimeout</code> lớn hơn nữa. Phía client, từ Node 19 <code>http.globalAgent</code> bật keepAlive mặc định, <code>fetch</code> (undici) cũng tái dùng kết nối.</li> <li>HTTP/2: multiplexing nhiều stream trên một kết nối TCP, nén header bằng HPACK, hết cần domain sharding; vẫn còn head-of-line blocking ở tầng TCP khi mất gói, HTTP/3 chạy trên QUIC (UDP) để giải quyết. Thực tế Node thường nói HTTP/1.1 sau reverse proxy, proxy lo TLS và HTTP/2.</li> <li>CORS là cơ chế của trình duyệt, không phải lớp bảo mật của server. Request không \"đơn giản\" (method khác GET/HEAD/POST, có header <code>Authorization</code>, <code>Content-Type: application/json</code>) sẽ có preflight <code>OPTIONS</code> kèm <code>Access-Control-Request-Method/Headers</code>; server trả <code>Access-Control-Allow-*</code> và <code>Max-Age</code> để cache kết quả. Có credentials thì không được dùng <code>*</code>. App mobile native không bị CORS chặn.</li></ul>", x:"Web dashboard của Expense Tracker chạy ở domain khác API. Mọi <code>POST /v1/transactions</code> từ trình duyệt báo lỗi CORS, trong khi Postman và app mobile vẫn chạy. Nguyên nhân: middleware xác thực JWT được đăng ký trước <code>cors</code>; preflight <code>OPTIONS</code> không mang <code>Authorization</code> nên bị trả 401 và trình duyệt chặn request thật. Đồng thời log ALB có 502 rải rác do keep-alive timeout. Sửa cả hai:<pre>import cors from 'cors';\n\nconst allowed = new Set(['https://app.expense.example', 'http://localhost:5173']);\napp.use(cors({\n  origin: (origin, cb) =&gt; cb(null, !origin || allowed.has(origin)),\n  credentials: true,\n  allowedHeaders: ['Authorization', 'Content-Type', 'Idempotency-Key'],\n  maxAge: 600,                      // browser caches the preflight for 10 minutes\n}));                                // registered BEFORE auth: preflight never hits the JWT check\napp.use(authMiddleware);\n\nconst server = app.listen(3000);\nserver.keepAliveTimeout = 65_000;   // longer than the ALB idle timeout (60s)\nserver.headersTimeout = 66_000;</pre>Bài học: lỗi CORS mà Postman vẫn chạy thường là preflight bị middleware khác chặn hoặc thiếu header trong <code>allowedHeaders</code>."},
  "w2k1": {c:"REST là phong cách thiết kế API xoay quanh resource (danh từ) định danh bằng URL, thao tác bằng method HTTP chuẩn và không giữ trạng thái phiên trên server. Một REST API tốt nhất quán về cách đặt tên, phân trang, filter, versioning và định dạng lỗi.", e:"<ul><li>Resource: danh từ số nhiều, lồng tối đa khoảng 2 cấp (<code>/v1/wallets/{id}/transactions</code>). Hành động không khớp CRUD thì mô hình hóa thành resource: <code>POST /v1/transfers</code> thay vì <code>POST /wallets/1/transferMoney</code>.</li> <li>Versioning: version trong URL (<code>/v1</code>) dễ debug, dễ route và hợp với mobile vì bản app cũ còn sống hàng tháng; version qua header/media type sạch hơn nhưng khó cache và khó thử. Quy tắc: thêm field là non-breaking, đổi tên/xóa field hay đổi kiểu là breaking; client phải bỏ qua field lạ.</li> <li>Offset (<code>LIMIT/OFFSET</code>) dễ làm, nhảy trang được, nhưng <code>OFFSET 100000</code> vẫn bắt DB đọc rồi bỏ 100 nghìn dòng, và có bản ghi mới chèn vào thì item bị trùng hoặc sót giữa các trang. Cursor (keyset) lọc theo vị trí của phần tử cuối: <code>WHERE (occurred_at, id) &lt; ($2, $3)</code>, ổn định và nhanh đều với index phù hợp; cursor nên opaque (base64) và luôn kèm cột unique làm tie-breaker. Không nhảy trang được và thường không trả total (<code>COUNT(*)</code> trên bảng lớn đắt), chỉ trả <code>nextCursor</code>.</li> <li>Filter/sort qua query param rõ nghĩa (<code>?month=2026-10&amp;categoryId=…&amp;sort=-amount</code>); whitelist field được sort để tránh SQL injection và tránh sort trên cột không có index.</li> <li>Lỗi theo RFC 9457 (thay thế RFC 7807): media type <code>application/problem+json</code>, các member chuẩn <code>type</code>, <code>title</code>, <code>status</code>, <code>detail</code>, <code>instance</code>. <code>type</code> là URI định danh loại lỗi (vắng mặt thì coi như <code>about:blank</code>, tức không có ngữ nghĩa ngoài status code). Được thêm extension member như <code>errors</code> cho lỗi validation; client phải bỏ qua extension không hiểu.</li></ul>", x:"Màn danh sách giao dịch trên app mobile dùng infinite scroll với <code>?page=N</code>. Người dùng import CSV sao kê trong lúc đang cuộn: các dòng mới chèn lên đầu làm trang sau lặp lại giao dịch đã thấy; với user có vài trăm nghìn giao dịch, trang càng sâu càng chậm. Chuyển sang keyset với index <code>(user_id, occurred_at DESC, id DESC)</code>:<pre>SELECT id, amount_minor, occurred_at, category_id\nFROM transactions\nWHERE user_id = $1\n  AND (occurred_at, id) &lt; ($2, $3)     -- decoded from the opaque cursor\nORDER BY occurred_at DESC, id DESC\nLIMIT 51;                               -- limit + 1 to know whether there is a next page</pre>Response trả <code>{ items, nextCursor }</code>. Lỗi validation đi cùng một định dạng cho mọi endpoint, mobile chỉ cần một parser:<pre>HTTP/1.1 422 Unprocessable Content\nContent-Type: application/problem+json\n\n{ \"type\": \"https://api.expense.example/problems/validation\",\n  \"title\": \"Invalid request\", \"status\": 422,\n  \"detail\": \"1 field is invalid\", \"instance\": \"/v1/transactions\",\n  \"errors\": [{ \"pointer\": \"/amount\", \"message\": \"must be a positive decimal\" }] }</pre>"},
  "w2k2": {c:"Express là framework tối giản: ứng dụng là chuỗi middleware <code>(req, res, next)</code> chạy theo thứ tự đăng ký, <code>Router</code> gom route theo prefix, error middleware có bốn tham số <code>(err, req, res, next)</code>. Express 5 ra bản 5.0 tháng 09/2024, bản 5.1 được gắn tag <code>latest</code> trên npm từ 03/2025, yêu cầu Node 18 trở lên.", e:"<ul><li>Middleware chạy tuần tự; mỗi middleware phải gọi <code>next()</code> hoặc kết thúc response, nếu không request treo tới timeout. Thứ tự đăng ký là thứ tự chạy: body parser, CORS, auth trước router; handler 404 và error handler đặt cuối.</li> <li>Async error: ở Express 4, promise bị reject trong handler không được bắt, request treo và process nhận <code>unhandledRejection</code>; phải bọc <code>express-async-handler</code> hoặc try/catch rồi <code>next(err)</code>. Express 5 tự chuyển lỗi throw hoặc promise reject từ handler/middleware tới <code>next(err)</code>, nên không cần <code>express-async-errors</code> nữa. Lưu ý: chỉ promise được trả về mới được bắt; lỗi ném trong callback của <code>setTimeout</code> hay event emitter vẫn lọt.</li> <li>Cú pháp path đổi theo path-to-regexp mới: wildcard phải đặt tên (<code>/*splat</code>, hoặc <code>/{*splat}</code> để khớp cả path gốc), tham số tùy chọn dùng ngoặc nhọn (<code>/:file{.:ext}</code> thay <code>:ext?</code>), không còn regex trong chuỗi path, các ký tự <code>()[]?+!</code> là reserved. Route cũ sai cú pháp làm app crash ngay khi khởi động.</li> <li><code>req.query</code> giờ là getter chỉ đọc và query parser mặc định là <code>\"simple\"</code> (không còn parse <code>?filter[month]=…</code> thành object lồng); <code>req.body</code> là <code>undefined</code> khi không có body parser (bản 4 là <code>{}</code>); <code>express.urlencoded()</code> mặc định <code>extended: false</code>.</li> <li>Response: <code>res.status()</code> chỉ nhận số nguyên 100–999; bỏ các chữ ký cũ như <code>res.json(obj, 201)</code>, <code>res.send(200)</code>, cùng <code>app.del</code>, <code>req.param()</code>, <code>res.sendfile</code>.</li> <li>Error middleware được Express nhận diện qua số tham số (<code>fn.length === 4</code>): bỏ <code>next</code> vì lint báo \"unused\" là nó thành middleware thường. Nếu <code>res.headersSent</code> thì gọi <code>next(err)</code> để Express đóng kết nối.</li></ul>", x:"Nâng API Expense Tracker từ Express 4 lên 5 gặp ba lỗi: app không khởi động vì route <code>'/v1/reports/*'</code>; middleware validate gán <code>req.query = parsed</code> ném <code>TypeError</code> (gán vào property chỉ có getter trong ESM/strict mode); client web gửi <code>?filter[month]=2026-10</code> giờ nhận về key phẳng <code>\"filter[month]\"</code>. Sửa:<pre>const app = express();\napp.set('query parser', 'extended');            // keep qs-style nested objects for old clients\napp.use(express.json({ limit: '100kb' }));\n\napp.get('/v1/reports/{*path}', reportHandler);  // was '/v1/reports/*'; req.params.path is an array\n\napp.get('/v1/transactions', async (req, res) =&gt; {\n  const query = ListQuery.parse(req.query);     // keep the result in a variable, never assign req.query\n  const page = await txService.list(req.user.id, query);  // a rejection goes to the error middleware\n  res.json(page);\n});\n\napp.use((err, req, res, next) =&gt; {              // 4 params: that is how Express detects it\n  if (res.headersSent) return next(err);\n  res.status(err.status ?? 500).type('application/problem+json')\n     .json({ title: err.status ? err.message : 'Internal Server Error', status: err.status ?? 500 });\n});</pre>Sau khi nâng cấp, toàn bộ wrapper <code>asyncHandler(...)</code> được xóa, nhờ Express 5 tự bắt promise reject."},
  "w2k3": {c:"Fastify là framework HTTP chú trọng hiệu năng và tính đóng gói: mọi thứ (route, decorator, hook) đăng ký qua plugin; JSON Schema của route được compile thành validator (Ajv) và serializer (fast-json-stringify). Bản hiện tại là Fastify 5, yêu cầu Node 20 trở lên.", e:"<ul><li>Encapsulation: mỗi <code>app.register(plugin)</code> tạo một context con; decorator, hook và route khai báo trong đó chỉ thấy được ở context đó và các con của nó. Muốn chia sẻ ra ngoài (DB client, decorator <code>authenticate</code>) thì bọc plugin bằng <code>fastify-plugin</code>. Bẫy kinh điển: quên <code>fp()</code> nên plugin anh em gọi <code>app.db</code> nhận <code>undefined</code>.</li> <li>Plugin được nạp bất đồng bộ theo thứ tự đăng ký (thư viện avvio); muốn dùng thứ plugin vừa thêm thì <code>await app.register(...)</code> hoặc đợi <code>app.ready()</code>. Từ v5, một plugin không được trộn kiểu callback <code>done</code> với async.</li> <li>Lifecycle: <code>onRequest</code> → <code>preParsing</code> → parse body → <code>preValidation</code> → validation → <code>preHandler</code> → handler → <code>preSerialization</code> → <code>onSend</code> → <code>onResponse</code>; <code>onError</code> chạy khi có lỗi, trước <code>setErrorHandler</code>. Xác thực token nên đặt ở <code>onRequest</code> (chưa tốn công parse body), kiểm tra quyền cần dữ liệu đã validate thì đặt ở <code>preHandler</code>.</li> <li>Validation: <code>body</code>, <code>querystring</code>, <code>params</code>, <code>headers</code> được kiểm tra trước handler, sai thì trả 400. Fastify 5 bắt buộc schema đầy đủ (<code>type: 'object'</code> + <code>properties</code>), bỏ kiểu viết tắt. Cấu hình Ajv mặc định có coerce kiểu (query string <code>\"10\"</code> thành số), điền default và loại field thừa khi schema đặt <code>additionalProperties: false</code>.</li> <li>Serialization: khai báo <code>response</code> schema theo status code thì Fastify dùng serializer sinh sẵn, nhanh hơn <code>JSON.stringify</code> và chỉ xuất field có trong schema, nên chặn được rò field nhạy cảm. Mặt trái: thêm field mới vào DTO mà quên khai báo trong schema thì client không bao giờ nhận được, và không có lỗi nào báo.</li> <li>Type provider (<code>@fastify/type-provider-typebox</code>, <code>fastify-type-provider-zod</code>) suy kiểu TypeScript từ schema để không phải khai báo hai lần.</li></ul>", x:"Bản Fastify của Expense Tracker gặp hai sự cố trong cùng tuần. Một: <code>GET /v1/me</code> trả nguyên bản ghi user, gồm cả <code>passwordHash</code>, vì route không có response schema. Hai: route trong plugin <code>reports</code> báo <code>app.authenticate is not a function</code> vì plugin auth không bọc <code>fastify-plugin</code>, decorator bị đóng gói trong context riêng. Sửa:<pre>import fp from 'fastify-plugin';\n\n// plugins/auth.ts: fp() removes encapsulation so siblings can see the decorator\nexport default fp(async (app) =&gt; {\n  app.decorate('authenticate', async (req) =&gt; { await req.jwtVerify(); });  // @fastify/jwt\n});\n\n// routes/me.ts\napp.get('/v1/me', {\n  onRequest: [app.authenticate],\n  schema: {\n    response: {\n      200: {\n        type: 'object',\n        properties: { id: { type: 'string' }, email: { type: 'string' }, currency: { type: 'string' } },\n      },               // passwordHash is not declared, so the serializer never writes it\n    },\n  },\n}, async (req) =&gt; usersRepo.findById(req.user.sub));</pre>Từ đó team đặt quy tắc: route nào cũng phải có response schema, và test e2e kiểm tra response không chứa field ngoài danh sách cho phép."},
  "w2k4": {c:"NestJS là framework có kiến trúc module và dependency injection (lấy cảm hứng từ Angular), chạy trên Express (mặc định) hoặc Fastify. Module gom controller (nhận request) và provider (service, repository) do IoC container tạo và inject. Nest 11 (01/2025) chuyển sang Express 5; Nest 12 (08/2026) phát hành mọi package dạng ESM và yêu cầu Node 20.19+ hoặc 22.12+.", e:"<ul><li>DI: provider mặc định là singleton trong cả app. Scope <code>REQUEST</code> tạo instance mới mỗi request và \"lan\" lên mọi provider phụ thuộc vào nó, tốn hiệu năng. Muốn dùng provider ở module khác thì module chứa nó phải <code>exports</code> và module dùng phải <code>imports</code>; lỗi \"Nest can't resolve dependencies\" thường do thiếu một trong hai hoặc import vòng (cần <code>forwardRef</code>, tốt hơn là tách module).</li> <li>Thứ tự request (theo tài liệu Request lifecycle): middleware (global rồi module) → guard (global → controller → route) → interceptor phần trước handler (global → controller → route) → pipe (global → controller → route → tham số) → handler → interceptor phần sau (ngược lại: route → controller → global) → exception filter (route → controller → global; filter là thành phần duy nhất không ưu tiên global, và chỉ filter khớp đầu tiên xử lý lỗi).</li> <li>Vai trò: middleware không biết handler nào sẽ chạy; guard có <code>ExecutionContext</code> và <code>Reflector</code> để đọc metadata như <code>@Roles()</code>, trả true/false; interceptor bọc handler bằng RxJS (log thời gian, timeout, map response, cache); pipe transform và validate tham số; filter đổi exception thành response.</li> <li>Bẫy: guard từ chối thì interceptor chưa hề chạy, nên interceptor đo latency sẽ không thấy request 401/403. Đăng ký bằng <code>app.useGlobalGuards(new X())</code> thì nằm ngoài DI, không inject được <code>Reflector</code> hay service; muốn DI thì khai báo provider với token <code>APP_GUARD</code>, <code>APP_PIPE</code>, <code>APP_INTERCEPTOR</code>, <code>APP_FILTER</code>.</li> <li>Nest 12 thêm validation theo Standard Schema: <code>@Body()</code>, <code>@Query()</code>, <code>@Param()</code> nhận option <code>schema</code> (Zod, Valibot…) và <code>StandardSchemaValidationPipe</code>; <code>class-validator</code> vẫn được hỗ trợ. App CommonJS vẫn chạy được nhờ <code>require(esm)</code> của Node.</li></ul>", x:"Expense Tracker dùng NestJS. Team thêm <code>LoggingInterceptor</code> để đo latency nhưng dashboard không có request 401/403 nào, và <code>RolesGuard</code> đăng ký bằng <code>app.useGlobalGuards(new RolesGuard())</code> crash vì <code>this.reflector</code> là undefined. Sửa bằng cách đưa mọi thành phần global vào DI và đo latency ở middleware (chạy trước guard):<pre>@Module({\n  providers: [\n    { provide: APP_GUARD, useClass: JwtAuthGuard },     // inside DI, unlike useGlobalGuards(new ...)\n    { provide: APP_GUARD, useClass: RolesGuard },       // guards run in this order\n    { provide: APP_INTERCEPTOR, useClass: TimeoutInterceptor },\n    { provide: APP_FILTER, useClass: ProblemDetailsFilter },\n  ],\n})\nexport class AppModule implements NestModule {\n  configure(consumer: MiddlewareConsumer) {\n    consumer.apply(RequestTimingMiddleware).forRoutes('*');  // sees 401/403 too\n  }\n}\n\n@Controller('v1/wallets')\nexport class WalletsController {\n  constructor(private readonly wallets: WalletsService) {}\n\n  @Delete(':id')\n  @Roles('owner')                                       // metadata read by RolesGuard via Reflector\n  remove(@Param('id', ParseUUIDPipe) id: string, @CurrentUser() user: User) {\n    return this.wallets.remove(user.id, id);\n  }\n}</pre>Câu trả lời phỏng vấn nên nêu được: lỗi ném ở guard hay pipe vẫn đi tới exception filter, nhưng không đi qua phần \"sau handler\" của interceptor."},
  "w2k5": {c:"Validation là kiểm tra mọi dữ liệu đi vào qua ranh giới hệ thống (body, query, params, header, file, webhook, message từ queue) theo một schema trước khi tới logic nghiệp vụ; DTO là kiểu mô tả hình dạng dữ liệu đó. Type của TypeScript bị xóa khi chạy nên không bảo vệ gì ở runtime.", e:"<ul><li>Zod (bản 4): schema là giá trị runtime, suy ra kiểu bằng <code>z.infer</code>; <code>safeParse</code> trả <code>{ success, data }</code> hoặc <code>{ success, error }</code> thay vì throw; <code>z.coerce.number()</code> cho query string (mọi thứ trong query đều là chuỗi); <code>z.toJSONSchema()</code> chuyển sang JSON Schema để dùng cho OpenAPI. Zod 4 tuân theo Standard Schema nên cắm được vào framework hỗ trợ chuẩn này.</li> <li>class-validator + class-transformer: decorator trên class DTO, phổ biến trong Nest với <code>ValidationPipe({ whitelist: true, forbidNonWhitelisted: true, transform: true })</code>. Thiếu <code>whitelist</code> thì field lạ như <code>userId</code>, <code>role</code> lọt vào, thành lỗ hổng mass assignment; object lồng cần <code>@ValidateNested()</code> kèm <code>@Type(() =&gt; X)</code>, quên là object con không được kiểm tra.</li> <li>JSON Schema (Ajv trong Fastify, OpenAPI): trung lập ngôn ngữ, dùng chung được cho tài liệu và client; nhớ <code>additionalProperties: false</code>.</li> <li>Không tin client: <code>userId</code> lấy từ token chứ không từ body; validate định dạng không thay cho kiểm tra quyền (<code>categoryId</code> hợp lệ nhưng có thuộc user này không?); tiền nhận dạng chuỗi thập phân hoặc số nguyên đơn vị nhỏ nhất, không nhận float; giới hạn độ dài chuỗi, số phần tử mảng, khoảng ngày cho phép.</li> <li>Validate cả hai đầu: response schema để không lộ field, và validate biến môi trường lúc khởi động để app chết sớm thay vì lỗi lúc 2 giờ sáng.</li></ul>", x:"Phiên bản đầu của <code>PATCH /v1/transactions/:id</code> truyền thẳng <code>req.body</code> vào ORM. Một client lỗi (hoặc kẻ tấn công) gửi <code>{\"userId\": \"…\"}</code> và chuyển giao dịch sang tài khoản người khác; một bản app khác gửi <code>amount: 0.1 + 0.2</code> dạng float làm tổng báo cáo lệch. Sửa bằng schema chặt và kiểm tra quyền riêng:<pre>import { z } from 'zod';\n\nconst Money = z.string().regex(/^-?\\d{1,12}(\\.\\d{1,2})?$/);      // decimal as a string, never a float\n\nconst UpdateTransaction = z.strictObject({                        // unknown keys -&gt; validation error\n  amount: Money.optional(),\n  categoryId: z.uuid().optional(),\n  note: z.string().trim().max(500).optional(),\n  occurredAt: z.iso.datetime({ offset: true }).optional(),\n});\ntype UpdateTransaction = z.infer&lt;typeof UpdateTransaction&gt;;\n\nconst result = UpdateTransaction.safeParse(req.body);\nif (!result.success) throw new ValidationProblem(result.error.issues);   // -&gt; 422 problem+json\nconst input = result.data;\nif (input.categoryId) await categories.assertOwnedBy(req.user.id, input.categoryId);  // authorization\nawait txRepo.update({ id: req.params.id, userId: req.user.id }, input);  // owner comes from the token</pre>Kết luận: schema chặn hình dạng dữ liệu, còn quyền sở hữu luôn phải kiểm tra bằng điều kiện <code>userId</code> lấy từ token."},
  "w2k6": {c:"Xử lý lỗi tập trung nghĩa là mọi lỗi đổ về một chỗ (error middleware của Express, <code>setErrorHandler</code> của Fastify, exception filter của Nest) để ánh xạ thành response nhất quán, ghi log và đo đếm. Nền tảng là tách lỗi nghiệp vụ (dự kiến được, client xử lý được) khỏi lỗi hệ thống (bug, hạ tầng hỏng).", e:"<ul><li>Lỗi nghiệp vụ: số dư không đủ, danh mục đã tồn tại, ví đã khóa. Trả 4xx kèm mã lỗi ổn định (<code>INSUFFICIENT_FUNDS</code>) để mobile <code>switch</code> theo mã và hiển thị câu thông báo đã dịch; log ở mức info/warn, không alert.</li> <li>Lỗi hệ thống: DB mất kết nối, null reference, timeout dịch vụ ngoài. Trả 500 (hoặc 503) với message chung kèm <code>requestId</code>/trace id; log mức error kèm stack và alert. Không bao giờ đưa <code>err.message</code> của driver hay stack trace ra response: lộ tên bảng, câu SQL, đường dẫn file. Express chỉ ẩn stack ở handler mặc định khi <code>NODE_ENV=production</code>, nên luôn có handler riêng.</li> <li>Mã lỗi là một phần của contract API: không đổi tên, chỉ thêm mới; client dựa vào mã, không dựa vào text. Đặt mã trong <code>type</code> URI của Problem Details hoặc extension <code>code</code>.</li> <li>Ánh xạ lỗi thư viện ở một chỗ: Prisma <code>P2002</code> (vi phạm unique) thành 409, <code>P2025</code> (không tìm thấy bản ghi) thành 404; PostgreSQL <code>23505</code> là unique violation, <code>40001</code>/<code>40P01</code> là serialization failure/deadlock, đáng retry thay vì trả lỗi ngay.</li> <li>Mức process: từ Node 15, <code>unhandledRejection</code> mặc định làm crash process. Với <code>uncaughtException</code>, log rồi thoát để Kubernetes/PM2 khởi động lại; đừng cố chạy tiếp vì trạng thái bộ nhớ không còn đáng tin.</li></ul>", x:"App mobile hiển thị nguyên văn <code>duplicate key value violates unique constraint \"categories_user_id_name_key\"</code> khi người dùng tạo danh mục trùng tên: lộ tên bảng, ràng buộc, và không dịch được. Nguyên nhân là handler cũ trả thẳng <code>err.message</code>. Sửa bằng một lớp lỗi nghiệp vụ và một error handler duy nhất:<pre>import { Prisma } from './generated/prisma/client';\n\nexport class AppError extends Error {\n  constructor(readonly code: string, readonly status: number, message: string,\n              readonly extra: Record&lt;string, unknown&gt; = {}) { super(message); }\n}\n\nfunction toAppError(err: unknown): AppError | null {\n  if (err instanceof AppError) return err;\n  if (err instanceof Prisma.PrismaClientKnownRequestError) {\n    if (err.code === 'P2002') return new AppError('CONFLICT', 409, 'Resource already exists');\n    if (err.code === 'P2025') return new AppError('NOT_FOUND', 404, 'Resource not found');\n  }\n  return null;                                   // unknown -&gt; system error\n}\n\napp.use((err, req, res, next) =&gt; {\n  if (res.headersSent) return next(err);\n  const known = toAppError(err);\n  if (!known) req.log.error({ err }, 'unhandled');          // full stack stays in the logs only\n  const status = known?.status ?? 500;\n  res.status(status).type('application/problem+json').json({\n    type: 'https://api.expense.example/problems/' + (known?.code ?? 'INTERNAL').toLowerCase(),\n    title: known?.message ?? 'Internal Server Error',\n    status, instance: req.originalUrl, requestId: req.id, ...known?.extra,\n  });\n});</pre>Service chủ động ném <code>new AppError('CATEGORY_EXISTS', 409, ...)</code> khi kiểm tra trước được, còn ánh xạ P2002 là lưới an toàn cho race condition."},
  "w2k7": {c:"Upload file qua HTTP thường dùng <code>multipart/form-data</code> (body chia thành nhiều phần ngăn bởi boundary), hoặc để client upload thẳng lên object storage bằng presigned URL. Yêu cầu cốt lõi: không đọc cả file vào RAM, giới hạn kích thước và loại file, không để upload lớn chiếm tài nguyên server.", e:"<ul><li>Multer (Express, bản 2.x) với <code>memoryStorage</code> giữ cả file trong Buffer: 20 request 50MB đồng thời là 1GB RAM. Luôn đặt <code>limits: { fileSize, files }</code>; vượt giới hạn Multer báo lỗi mã <code>LIMIT_FILE_SIZE</code>, ánh xạ thành 413 (Content Too Large). Với Fastify, <code>@fastify/multipart</code> cho <code>req.file()</code> trả về stream, có <code>limits.fileSize</code> và mặc định ném lỗi khi file vượt giới hạn.</li> <li>Giới hạn ở nhiều tầng: reverse proxy (<code>client_max_body_size</code> của nginx), body parser, thư viện multipart, và cả số dòng tối đa khi parse CSV.</li> <li>Stream lên S3: đưa stream vào <code>Upload</code> của <code>@aws-sdk/lib-storage</code> (tự chia multipart upload, có backpressure) thay vì ghi file tạm rồi upload; dùng <code>stream/promises</code> <code>pipeline</code> để lỗi giữa chừng hủy cả chuỗi và không rò file descriptor.</li> <li>Presigned URL: server chỉ ký URL có hạn ngắn, client upload thẳng S3, server không tốn băng thông và không giữ kết nối lâu. Presigned PUT không có điều kiện khoảng kích thước; muốn ép kích thước tối đa dùng presigned POST với điều kiện <code>content-length-range</code> (<code>@aws-sdk/s3-presigned-post</code>). Sau khi upload, server vẫn phải kiểm tra lại object (<code>HeadObject</code>: kích thước, content type) trước khi xử lý.</li> <li>Không tin <code>Content-Type</code> hay tên file từ client: kiểm tra magic bytes, tự sinh key (UUID) để tránh path traversal và ghi đè, quét malware nếu là file người khác sẽ tải về. Xử lý nặng (parse 50 nghìn dòng CSV) đưa vào job queue, API trả 202.</li></ul>", x:"Bản đầu của tính năng import sao kê CSV dùng Multer <code>memoryStorage</code> rồi <code>buffer.toString()</code> cả file. Một người dùng upload file xuất từ ngân hàng 300MB, pod bị OOMKilled và kéo theo mọi request đang chạy trên pod đó. Thiết kế lại: mobile xin presigned POST, upload thẳng S3, rồi gọi <code>POST /v1/imports</code> với <code>key</code>; server <code>HeadObject</code> kiểm tra kích thước, tạo job BullMQ, worker stream file từ S3 và parse từng dòng.<pre>import { createPresignedPost } from '@aws-sdk/s3-presigned-post';\nimport { randomUUID } from 'node:crypto';\n\napp.post('/v1/imports/upload-url', async (req, res) =&gt; {\n  const key = `imports/${req.user.id}/${randomUUID()}.csv`;     // server-chosen key, no client filename\n  const { url, fields } = await createPresignedPost(s3, {\n    Bucket: process.env.IMPORT_BUCKET,\n    Key: key,\n    Conditions: [\n      ['content-length-range', 1, 10 * 1024 * 1024],              // S3 rejects anything over 10 MB\n      ['eq', '$Content-Type', 'text/csv'],\n    ],\n    Fields: { 'Content-Type': 'text/csv' },\n    Expires: 600,                                                 // seconds\n  });\n  res.status(201).json({ url, fields, key });\n});</pre>Kết quả: API không còn nhận byte file nào, bộ nhớ pod ổn định, giới hạn kích thước được S3 cưỡng chế thay vì dựa vào client."},
  "w2k8": {c:"OpenAPI là đặc tả mô tả HTTP API bằng YAML/JSON (path, tham số, schema, xác thực, các response lỗi); bản mới nhất là 3.2 (09/2025). Swagger UI render đặc tả thành trang tài liệu thử được. Có hai cách làm: code-first (sinh spec từ code) và contract-first (viết spec trước rồi sinh code, validator, mock từ spec).", e:"<ul><li>Code-first: <code>@nestjs/swagger</code> đọc decorator và DTO (plugin CLI suy ra từ type TypeScript), <code>@fastify/swagger</code> lấy từ JSON Schema của route, Zod chuyển qua <code>z.toJSONSchema()</code>. Ưu: spec không lệch khỏi code. Nhược: thiết kế API dễ bị dẫn dắt bởi implementation và chỉ review được sau khi đã code.</li> <li>Contract-first: viết <code>openapi.yaml</code>, review trong PR cùng team mobile/web trước khi code, dựng mock server để mobile làm song song; server validate request theo spec. Hợp khi nhiều team phụ thuộc vào cùng API.</li> <li>Sinh client: <code>openapi-typescript</code> (chỉ sinh type) + <code>openapi-fetch</code> cho web, <code>orval</code> cho React Query, <code>openapi-generator</code> cho Kotlin/Swift/Dart. Đặt <code>operationId</code> ổn định vì nó thành tên hàm trong client sinh ra; đổi nó là breaking với code client.</li> <li>Giữ spec trung thực bằng CI: lint (Spectral, Redocly CLI) và so sánh breaking change giữa nhánh và main (oasdiff). Khai báo đủ response lỗi (<code>application/problem+json</code>), <code>nullable</code>/<code>required</code>, enum.</li> <li>Bẫy: thêm giá trị vào enum trong response là breaking với client sinh code chặt (Kotlin, Swift decode thất bại). Thống nhất với mobile luôn có nhánh \"unknown\" khi decode enum.</li> <li>Trang <code>/docs</code> của API nội bộ nên tắt hoặc đặt sau auth ở production.</li></ul>", x:"Backend thêm giá trị <code>transfer</code> vào enum <code>type</code> của giao dịch. App iOS bản cũ dùng client sinh từ OpenAPI, decode enum thất bại nên cả danh sách giao dịch không hiện, trong khi web vẫn chạy. Sau sự cố, team export spec trong CI và chặn thay đổi nguy hiểm trước khi merge:<pre>// scripts/export-openapi.ts\nconst app = await NestFactory.create(AppModule, { logger: false });\nconst config = new DocumentBuilder()\n  .setTitle('Expense Tracker API').setVersion('1.0').addBearerAuth().build();\nconst document = SwaggerModule.createDocument(app, config);\nwriteFileSync('openapi.json', JSON.stringify(document, null, 2));\nawait app.close();\n\n# CI step (oasdiff is a standalone CLI)\noasdiff breaking main-openapi.json openapi.json --fail-on WARN</pre>Kèm theo là quy tắc: thay đổi enum ở response phải đi qua review của mobile, và client mobile dùng giá trị fallback cho enum lạ."},
  "w2k9": {c:"GraphQL cho client gửi query mô tả chính xác các field cần tới một endpoint duy nhất, server resolve theo schema có kiểu. gRPC là RPC chạy trên HTTP/2 với Protocol Buffers, contract nằm trong file <code>.proto</code>, hỗ trợ streaming hai chiều. Cả hai là lựa chọn thay thế hoặc bổ sung cho REST, không phải bản nâng cấp của nó.", e:"<ul><li>Chọn GraphQL khi nhiều client (mobile, web, dashboard) cần hình dạng dữ liệu khác nhau và một màn hình gom nhiều resource; giảm over-fetching và số round trip. Cái giá: cache HTTP khó (thường là POST một endpoint, persisted query + GET giúp phần nào), phân quyền theo field, phải giới hạn độ sâu và độ phức tạp query để chống DoS, monitoring theo tên operation thay vì URL, lỗi thường trả 200 kèm mảng <code>errors</code>.</li> <li>N+1 trong GraphQL: resolver <code>Transaction.category</code> chạy một lần cho mỗi giao dịch, 100 giao dịch thành 1 + 100 query. DataLoader gom mọi <code>load(key)</code> gọi trong cùng một tick thành một lần <code>batchLoadFn(keys)</code> và cache theo key. Hai luật: tạo DataLoader mới cho mỗi request (cache không rò dữ liệu giữa user, không cũ), và batch function phải trả mảng cùng độ dài, cùng thứ tự với <code>keys</code>.</li> <li>gRPC hợp cho giao tiếp nội bộ giữa service: payload nhị phân nhỏ, sinh code nhiều ngôn ngữ, có deadline và streaming. Nhược: trình duyệt không gọi gRPC trực tiếp được (cần gRPC-Web hoặc Connect qua proxy), khó debug bằng curl, kết nối HTTP/2 sống lâu nên load balancer L4 phân tải kém, cần LB L7.</li> <li>Thư viện Node: Apollo Server, GraphQL Yoga, Mercurius (Fastify), <code>@nestjs/graphql</code>; gRPC dùng <code>@grpc/grpc-js</code> + <code>@grpc/proto-loader</code> hoặc Connect.</li> <li>REST vẫn là mặc định cho public API, webhook, upload file và nội dung cache được qua CDN.</li></ul>", x:"Dashboard web của Expense Tracker dùng GraphQL để vẽ trang tổng quan. Query lấy 100 giao dịch gần nhất kèm category và wallet sinh ra 201 câu SQL, p95 tăng vọt khi dữ liệu lớn. Thêm DataLoader tạo theo từng request:<pre>import DataLoader from 'dataloader';\n\nexport function createLoaders(db) {\n  return {\n    category: new DataLoader(async (ids) =&gt; {\n      const rows = await db.category.findMany({ where: { id: { in: [...ids] } } });\n      const byId = new Map(rows.map((c) =&gt; [c.id, c]));\n      return ids.map((id) =&gt; byId.get(id) ?? null);     // same length and order as ids\n    }),\n  };\n}\n\nconst resolvers = {\n  Transaction: {\n    category: (tx, _args, ctx) =&gt; ctx.loaders.category.load(tx.categoryId),\n  },\n};\n\n// context is created per request: the cache lives only for this request and this user\n// context: async ({ req }) =&gt; ({ user: req.user, loaders: createLoaders(prisma) })</pre>Số query giảm từ 201 xuống 3. App mobile vẫn dùng REST vì màn hình đơn giản và tận dụng được ETag; gRPC chỉ cân nhắc nếu sau này tách worker báo cáo thành service riêng."},
  "w3k0": {c:"Cơ sở dữ liệu quan hệ (PostgreSQL, MySQL) lưu dữ liệu thành bảng có schema cố định, liên kết bằng khóa ngoại; JOIN, ràng buộc và transaction ACID trên nhiều bảng là thế mạnh. Cơ sở dữ liệu document (MongoDB) lưu document BSON có cấu trúc linh hoạt, tối ưu cho việc đọc và ghi trọn một aggregate trong một lần.", e:"<ul><li>Dữ liệu tài chính như Expense Tracker (ví, giao dịch, chuyển tiền, ngân sách, báo cáo gom nhóm) có nhiều quan hệ, cần ràng buộc chặt và truy vấn tổng hợp, nên quan hệ là lựa chọn mặc định.</li> <li>PostgreSQL so với MySQL: PostgreSQL có hệ kiểu phong phú (<code>jsonb</code> với GIN index, array, range), partial và expression index, <code>RETURNING</code>, DDL chạy trong transaction, nhiều extension (pg_trgm, PostGIS, pgvector). MySQL (InnoDB) phổ biến, nhiều dịch vụ managed, replication quen thuộc. Khác biệt hay bị hỏi: isolation mặc định của MySQL là REPEATABLE READ, của PostgreSQL là READ COMMITTED, nên cùng một đoạn code có thể cư xử khác nhau khi chạy đồng thời.</li> <li>MongoDB hợp khi dữ liệu dạng cây luôn được đọc cùng nhau (catalog sản phẩm có thuộc tính khác nhau, cấu hình), schema thay đổi nhanh, khối lượng ghi lớn hoặc cần sharding sẵn có. Mongo có multi-document transaction (yêu cầu replica set hoặc sharded cluster) nhưng tốn hơn và không phải lối dùng chính; document tối đa 16MB.</li> <li>\"Schemaless\" chỉ là chuyển schema từ DB vào code (Mongoose schema, validator), và dữ liệu cũ nhiều phiên bản cùng tồn tại mà code phải xử lý.</li> <li>Thường không cần hai DB: phần dữ liệu linh hoạt có thể nằm trong cột <code>jsonb</code> của PostgreSQL.</li></ul>", x:"Team tranh luận có nên dùng MongoDB cho Expense Tracker vì \"mỗi giao dịch là một document\". Đặt yêu cầu lên bàn: báo cáo tháng cần tổng theo danh mục và ví, so với ngân sách; chuyển tiền giữa hai ví phải atomic; danh mục không được trùng tên trong một user. Ba thứ này đều là thế mạnh của SQL. Chỉ có dữ liệu thô của sao kê ngân hàng là mỗi ngân hàng một định dạng, nên để trong <code>jsonb</code>:<pre>CREATE TABLE transactions (\n  id           uuid PRIMARY KEY DEFAULT uuidv7(),       -- built-in since PostgreSQL 18\n  user_id      uuid NOT NULL REFERENCES users(id),\n  wallet_id    uuid NOT NULL REFERENCES wallets(id),\n  amount_minor bigint NOT NULL,\n  occurred_at  timestamptz NOT NULL,\n  bank_raw     jsonb                                    -- shape differs per bank\n);\nCREATE INDEX tx_bank_raw ON transactions USING gin (bank_raw jsonb_path_ops);\n\nSELECT id, amount_minor FROM transactions\nWHERE user_id = $1 AND bank_raw @&gt; '{\"channel\": \"ATM\"}';  -- containment query uses the GIN index</pre>Kết luận: PostgreSQL cho toàn bộ dữ liệu, <code>jsonb</code> cho phần không cấu trúc, không vận hành thêm một hệ DB thứ hai."},
  "w3k1": {c:"Thiết kế schema là chọn bảng, cột, kiểu dữ liệu và ràng buộc sao cho chính database bảo vệ tính đúng của dữ liệu. Chuẩn hóa (thường tới 3NF) loại bỏ dữ liệu lặp và bất thường khi cập nhật; denormalize là quyết định có chủ đích để đọc nhanh hơn, kèm trách nhiệm giữ đồng bộ.", e:"<ul><li>Ràng buộc trong DB là tuyến phòng thủ cuối, kể cả khi có bug ở app hay script chạy tay: <code>NOT NULL</code>, <code>UNIQUE (user_id, name)</code>, <code>CHECK (amount_minor &lt;&gt; 0)</code>, khóa ngoại với <code>ON DELETE</code> phù hợp (RESTRICT cho giao dịch, CASCADE cho bảng con thuần túy). PostgreSQL không tự tạo index cho cột khóa ngoại ở bảng con; thiếu index thì JOIN chậm và mỗi lần xóa bản ghi cha phải quét bảng con.</li> <li>Tiền: không dùng float/double (<code>0.1 + 0.2</code>). Dùng <code>numeric(p, s)</code> hoặc <code>bigint</code> lưu theo đơn vị nhỏ nhất (cent; VND và JPY không có đơn vị lẻ) kèm cột <code>currency</code> theo ISO 4217. Tránh kiểu <code>money</code> của PostgreSQL vì phụ thuộc <code>lc_monetary</code>.</li> <li>Ở Node, driver <code>pg</code> trả <code>numeric</code> và <code>bigint</code> dưới dạng string để không mất chính xác; đừng <code>parseFloat</code>, hãy dùng <code>BigInt</code> hoặc thư viện decimal. Prisma ánh xạ <code>Decimal</code> sang Decimal.js, <code>BigInt</code> sang <code>bigint</code> của JS (nhớ xử lý khi <code>JSON.stringify</code>).</li> <li>Thời gian: <code>timestamptz</code> lưu một thời điểm tuyệt đối (nội bộ là UTC, hiển thị theo <code>TimeZone</code> của session); <code>timestamp</code> không múi giờ dễ sai khi server và người dùng khác múi. Báo cáo \"tháng 10\" phải tính theo múi giờ người dùng: <code>date_trunc('month', occurred_at AT TIME ZONE 'Asia/Ho_Chi_Minh')</code>.</li> <li>Khóa chính: <code>bigint generated always as identity</code> hoặc UUID. UUIDv7 có thứ tự thời gian nên chèn vào B-tree gọn hơn UUIDv4 ngẫu nhiên; PostgreSQL 18 có sẵn hàm <code>uuidv7()</code>.</li></ul>", x:"Hai bug cùng lúc trong báo cáo tháng. Một: giao dịch của người dùng Việt Nam từ 0h tới 7h ngày mùng 1 bị tính sang tháng trước, vì cột là <code>timestamp</code> lưu giờ UTC và query <code>date_trunc</code> trực tiếp. Hai: tổng chi lệch vài đồng vì <code>amount</code> là <code>double precision</code>. Schema sửa lại:<pre>CREATE TABLE wallets (\n  id            uuid PRIMARY KEY DEFAULT uuidv7(),\n  user_id       uuid NOT NULL REFERENCES users(id),\n  currency      char(3) NOT NULL,                       -- ISO 4217\n  balance_minor bigint NOT NULL DEFAULT 0               -- denormalized, updated in the same transaction\n);\nCREATE TABLE transactions (\n  id            uuid PRIMARY KEY DEFAULT uuidv7(),\n  wallet_id     uuid NOT NULL REFERENCES wallets(id) ON DELETE RESTRICT,\n  category_id   uuid REFERENCES categories(id) ON DELETE SET NULL,\n  amount_minor  bigint NOT NULL CHECK (amount_minor &lt;&gt; 0),\n  occurred_at   timestamptz NOT NULL\n);\nCREATE INDEX tx_wallet_time ON transactions (wallet_id, occurred_at);  -- FKs are not indexed automatically\n\nSELECT date_trunc('month', occurred_at AT TIME ZONE $2) AS month, sum(amount_minor) AS total\nFROM transactions WHERE wallet_id = $1 GROUP BY 1 ORDER BY 1;          -- $2 = 'Asia/Ho_Chi_Minh'</pre>Phía Node đọc <code>total</code> là string (<code>sum</code> của bigint trả <code>numeric</code>) và chuyển bằng <code>BigInt(row.total)</code>, không qua <code>Number</code>."},
  "w3k2": {c:"Index là cấu trúc dữ liệu phụ giúp tìm hàng mà không phải quét cả bảng. Mặc định PostgreSQL dùng B-tree: cây cân bằng đã sắp xếp, phục vụ <code>=</code>, <code>&lt;</code>, <code>&gt;</code>, <code>BETWEEN</code>, <code>ORDER BY</code>. Đổi lại, mỗi index làm chậm thao tác ghi và tốn dung lượng.", e:"<ul><li>Composite index <code>(a, b)</code> hiệu quả nhất khi cột đầu có điều kiện bằng, cột sau là range hoặc sort: \"equality trước, range sau\". Index <code>(user_id, occurred_at)</code> phục vụ <code>WHERE user_id = $1 AND occurred_at &gt;= $2 ORDER BY occurred_at</code>; đảo thứ tự cột thì kém hẳn. PostgreSQL 18 có skip scan cho B-tree nhiều cột khi query bỏ điều kiện bằng ở cột đầu, nhưng chỉ hiệu quả khi cột đầu có ít giá trị khác nhau; đừng thiết kế index dựa vào nó.</li> <li>Partial index (<code>WHERE deleted_at IS NULL</code>) nhỏ hơn và chỉ được dùng khi query có cùng điều kiện. Expression index (<code>lower(email)</code>) cho điều kiện trên biểu thức. Covering index với <code>INCLUDE (amount_minor)</code> cho phép Index Only Scan, không phải ghé heap (với điều kiện visibility map được VACUUM cập nhật).</li> <li>Đọc <code>EXPLAIN ANALYZE</code>: loại node (Seq Scan, Index Scan, Bitmap Heap Scan, Index Only Scan), so <code>rows</code> ước lượng với actual (lệch lớn là thống kê cũ, chạy <code>ANALYZE</code>), <code>loops</code> của nested loop, <code>Rows Removed by Filter</code>, Sort ra đĩa (<code>external merge</code>, thiếu <code>work_mem</code>). Từ PostgreSQL 18, <code>EXPLAIN ANALYZE</code> tự hiện số buffer. Lưu ý <code>ANALYZE</code> chạy thật câu lệnh: thử UPDATE/DELETE thì bọc trong <code>BEGIN … ROLLBACK</code>.</li> <li>Seq Scan không luôn xấu: bảng nhỏ hoặc query lấy phần lớn số hàng thì quét tuần tự rẻ hơn.</li> <li>Tạo index trên production dùng <code>CREATE INDEX CONCURRENTLY</code>: không chặn ghi, nhưng không chạy được trong transaction block và nếu thất bại để lại index INVALID phải xóa rồi tạo lại.</li></ul>", x:"Lab tuần này seed 1 triệu giao dịch. Query báo cáo tổng chi theo danh mục trong tháng chạy hàng trăm mili giây; <code>EXPLAIN</code> cho thấy Seq Scan và gần như toàn bộ hàng bị lọc bỏ. Thêm một index khớp đúng hình dạng query:<pre>EXPLAIN (ANALYZE, BUFFERS)\nSELECT category_id, sum(amount_minor)\nFROM transactions\nWHERE user_id = $1\n  AND occurred_at &gt;= '2026-10-01 00:00+07' AND occurred_at &lt; '2026-11-01 00:00+07'\n  AND deleted_at IS NULL\nGROUP BY category_id;\n-- before: Seq Scan on transactions ... Rows Removed by Filter: ~999000\n\nCREATE INDEX CONCURRENTLY tx_user_time_live\n  ON transactions (user_id, occurred_at)       -- equality column first, range column second\n  INCLUDE (category_id, amount_minor)          -- covering: no heap lookups\n  WHERE deleted_at IS NULL;                    -- same predicate as the query\n-- after: Index Only Scan using tx_user_time_live ... Heap Fetches: 0 (after VACUUM)</pre>Ghi lại thời gian trước và sau vào README của lab. Câu hỏi vặn hay gặp: \"sao không index riêng từng cột?\" Vì PostgreSQL có thể kết hợp bằng BitmapAnd nhưng vẫn phải đọc heap và sort lại, chậm hơn một composite index đúng thứ tự."},
  "w3k3": {c:"Transaction gom nhiều câu lệnh thành một đơn vị theo ACID: Atomicity (tất cả hoặc không có gì), Consistency (ràng buộc luôn đúng sau commit), Isolation (transaction đồng thời không thấy trạng thái dở dang của nhau, mức độ tùy isolation level), Durability (đã commit thì không mất, nhờ WAL).", e:"<ul><li>PostgreSQL mặc định READ COMMITTED: mỗi câu lệnh thấy snapshot tại lúc câu lệnh đó bắt đầu, nên hai lần SELECT trong cùng transaction có thể ra kết quả khác nhau. READ UNCOMMITTED của PostgreSQL chạy như READ COMMITTED, không có dirty read.</li> <li>REPEATABLE READ: snapshot cố định từ câu lệnh đầu tiên; trong PostgreSQL còn không có phantom read (chặt hơn chuẩn SQL). Nếu cập nhật một hàng mà transaction khác đã sửa và commit, câu lệnh lỗi <code>could not serialize access due to concurrent update</code>. SERIALIZABLE dùng SSI, phát hiện thêm các bất thường như write skew. Lỗi serialization luôn mang SQLSTATE <code>40001</code> và ứng dụng phải retry cả transaction, nên phải có cơ chế retry chung trước khi nâng isolation.</li> <li>Lost update kinh điển: đọc số dư lên app, cộng trừ, ghi lại. Ba cách sửa: cập nhật nguyên tử trong SQL (<code>SET balance = balance - $1 WHERE id = $2 AND balance &gt;= $1</code>); pessimistic locking với <code>SELECT … FOR UPDATE</code> giữ khóa hàng tới hết transaction; optimistic locking với cột <code>version</code> (<code>UPDATE … WHERE id = $1 AND version = $2</code>, 0 hàng bị ảnh hưởng thì trả 409 hoặc retry). Optimistic hợp khi xung đột hiếm, pessimistic hợp khi xung đột thường xuyên trên ít hàng (số dư ví).</li> <li>Deadlock: hai transaction khóa hai ví theo thứ tự ngược nhau; PostgreSQL phát hiện và hủy một bên với SQLSTATE <code>40P01</code>. Phòng bằng cách luôn khóa theo thứ tự cố định (<code>ORDER BY id FOR UPDATE</code>), giữ transaction ngắn, không gọi HTTP ra ngoài khi đang giữ khóa.</li> <li>Bẫy ở Node: với <code>pg</code>, <code>BEGIN</code>/<code>COMMIT</code> phải chạy trên cùng một client lấy từ <code>pool.connect()</code>; <code>pool.query</code> mỗi lần có thể ra kết nối khác. Prisma có <code>$transaction(async (tx) =&gt; …, { isolationLevel })</code> nhưng không có API cho <code>FOR UPDATE</code>, phải dùng <code>$queryRaw</code>.</li></ul>", x:"Bản đầu của tính năng chuyển tiền đọc số dư lên, kiểm tra, rồi <code>UPDATE wallets SET balance_minor = $newBalance</code>. Người dùng bấm nút hai lần, hai request chạy song song đều đọc cùng số dư cũ: tiền chỉ bị trừ một lần nhưng có hai bản ghi chuyển. Viết lại với khóa hàng theo thứ tự cố định:<pre>export async function transfer(pool, userId, fromId, toId, amount /* bigint, minor units */) {\n  const client = await pool.connect();          // BEGIN..COMMIT must share one connection\n  try {\n    await client.query('BEGIN');\n    const { rows } = await client.query(\n      `SELECT id, balance_minor FROM wallets\n        WHERE id = ANY($1) AND user_id = $2\n        ORDER BY id FOR UPDATE`,               // same lock order everywhere -&gt; no deadlock\n      [[fromId, toId], userId],\n    );\n    const from = rows.find((w) =&gt; w.id === fromId);\n    if (BigInt(from.balance_minor) &lt; amount) throw new AppError('INSUFFICIENT_FUNDS', 422, 'Insufficient funds');\n    await client.query('UPDATE wallets SET balance_minor = balance_minor - $1 WHERE id = $2', [amount, fromId]);\n    await client.query('UPDATE wallets SET balance_minor = balance_minor + $1 WHERE id = $2', [amount, toId]);\n    await client.query(\n      'INSERT INTO transfers (from_wallet_id, to_wallet_id, amount_minor) VALUES ($1, $2, $3)',\n      [fromId, toId, amount],\n    );\n    await client.query('COMMIT');\n  } catch (err) { await client.query('ROLLBACK'); throw err; }\n  finally { client.release(); }                 // forgetting this slowly drains the pool\n}</pre>Test tích hợp bắn 50 request chuyển tiền song song và kiểm tra tổng số dư hai ví không đổi."},
  "w3k4": {c:"ORM ánh xạ bảng thành model và sinh SQL từ API của ngôn ngữ; query builder cho viết SQL bằng API có kiểu mà không che giấu SQL. Lựa chọn ảnh hưởng tới type safety, hiệu năng, khả năng viết query phức tạp và cách quản lý migration.", e:"<ul><li>Prisma (dòng 7.x ổn định, 8 đang ở giai đoạn RC): schema riêng <code>schema.prisma</code>, sinh client có kiểu rất tốt, migrate dễ dùng. Prisma 7 bỏ query engine viết bằng Rust làm mặc định: client thuần TypeScript, generator <code>prisma-client</code> bắt buộc khai báo <code>output</code>, kết nối qua driver adapter (vd <code>@prisma/adapter-pg</code>), cấu hình CLI nằm trong <code>prisma.config.ts</code>. Nhược: không có API cho khóa hàng, một số SQL đặc thù (CTE, window function) phải viết bằng <code>$queryRaw</code> hoặc TypedSQL.</li> <li>Drizzle: schema khai báo bằng TypeScript, API gần SQL (<code>select().from().where()</code>), không có bước codegen, nhẹ, hợp serverless; <code>drizzle-kit</code> lo migration. Dòng 1.0 (đang beta) chỉ còn Relational Queries v2 với <code>defineRelations()</code>.</li> <li>TypeORM (1.0 ra 05/2026): entity bằng decorator, có Active Record lẫn Data Mapper, phổ biến trong hệ NestJS. Bẫy: lazy relation gây N+1, <code>synchronize: true</code> trên production có thể xóa cột, kiểu trả về không cho biết relation đã được load hay chưa.</li> <li>Sequelize lâu đời, viết cho JS trước nên typing yếu hơn. Knex là query builder kèm migration, không có model.</li> <li>Dù chọn gì: bật log query khi dev, xem SQL được sinh ra và kiểm tra bằng <code>EXPLAIN</code>. Raw SQL qua tagged template (<code>prisma.$queryRaw`…`</code>, <code>sql`…`</code> của Drizzle) tự tham số hóa nên an toàn; <code>$queryRawUnsafe</code> với chuỗi nối tay là SQL injection.</li></ul>", x:"Lab cần báo cáo tổng chi theo danh mục từng tháng theo múi giờ người dùng. <code>groupBy</code> của Prisma không gom được theo biểu thức <code>date_trunc</code>, nên team viết raw SQL có tham số; cùng query đó bằng Drizzle vẫn giữ được kiểu cột:<pre>// Prisma: tagged template, every ${} becomes a bind parameter\nconst rows = await prisma.$queryRaw&lt;{ month: Date; category_id: string; total: bigint }[]&gt;`\n  SELECT date_trunc('month', occurred_at AT TIME ZONE ${tz}) AS month,\n         category_id, sum(amount_minor)::bigint AS total\n  FROM transactions\n  WHERE user_id = ${userId}::uuid AND deleted_at IS NULL\n  GROUP BY 1, 2 ORDER BY 1`;\n\n// Drizzle: SQL stays visible, columns stay typed\nconst month = sql&lt;string&gt;`date_trunc('month', ${transactions.occurredAt} AT TIME ZONE ${tz})`;\nconst rows2 = await db\n  .select({ month, categoryId: transactions.categoryId, total: sum(transactions.amountMinor) })\n  .from(transactions)\n  .where(and(eq(transactions.userId, userId), isNull(transactions.deletedAt)))\n  .groupBy(month, transactions.categoryId);</pre>Quyết định cho dự án: Prisma cho CRUD và migration vì đồng đội quen, báo cáo và chuyển tiền viết SQL tay có test. Nếu chọn Drizzle thì một công cụ lo được cả hai, đổi lại phải tự viết nhiều hơn."},
  "w3k5": {c:"N+1 là khi lấy danh sách bằng 1 query rồi lấy dữ liệu liên quan cho từng phần tử bằng N query nữa. Connection pool là tập kết nối DB mở sẵn được tái sử dụng giữa các request, vì mở kết nối PostgreSQL tốn kém (mỗi kết nối là một process backend trên server DB).", e:"<ul><li>N+1 trong Node thường đến từ <code>for</code> + <code>await repo.find…</code> trong từng phần tử, lazy relation của TypeORM, hoặc resolver GraphQL. Phát hiện bằng cách đếm query mỗi request trong test hoặc nhìn trace APM.</li> <li>Eager loading: JOIN hoặc query thứ hai <code>WHERE id IN (…)</code>; <code>include</code> của Prisma hay <code>relations</code> của TypeORM gom thành vài query thay vì N. Eager quá mức cũng hại: JOIN nhiều quan hệ một-nhiều nhân số hàng (cartesian explosion), nên chỉ lấy field cần. Bài toán \"top N mỗi nhóm\" (5 giao dịch gần nhất của mỗi ví) giải gọn bằng <code>LATERAL</code>.</li> <li>Kích thước pool: <code>max_connections</code> mặc định của PostgreSQL là 100 và chia cho mọi instance. 10 pod × pool 20 = 200 kết nối là gặp <code>too many clients already</code>. Pool lớn không nhanh hơn: số kết nối thực sự làm việc hiệu quả gần với số core của DB. <code>pg.Pool</code> mặc định <code>max: 10</code>.</li> <li>Pool cạn thường do giữ kết nối quá lâu: transaction dài, gọi HTTP bên ngoài khi đang trong transaction, quên <code>client.release()</code>. Request mới chờ tới <code>connectionTimeoutMillis</code> rồi lỗi. Đặt <code>statement_timeout</code> và <code>idle_in_transaction_session_timeout</code> để DB tự cắt.</li> <li>Nhiều instance hoặc serverless: đặt PgBouncer ở chế độ transaction hoặc proxy managed phía trước. Ở chế độ transaction không dùng được trạng thái theo session (<code>SET</code>, <code>LISTEN</code>, advisory lock cấp session); prepared statement được hỗ trợ từ PgBouncer 1.21 khi bật <code>max_prepared_statements</code>. Prisma 7 dùng driver adapter nên pool do driver (vd <code>pg.Pool</code>) quản lý.</li></ul>", x:"<code>GET /v1/wallets</code> trả mỗi ví kèm 5 giao dịch gần nhất và tên danh mục. Code ban đầu lồng hai vòng <code>await</code>: user có 20 ví sinh ra 1 + 20 + 100 query. Khi tải tăng, pool 10 kết nối bị chiếm hết, p99 lên vài giây và các endpoint khác cũng chậm theo.<pre>// BUG: 1 query for wallets + 1 per wallet + 1 per transaction\nfor (const w of wallets) {\n  w.recent = await prisma.transaction.findMany({ where: { walletId: w.id }, take: 5, orderBy: { occurredAt: 'desc' } });\n  for (const t of w.recent) t.category = await prisma.category.findUnique({ where: { id: t.categoryId } });\n}\n\n-- Fix: one round trip, top-5 per wallet with LATERAL, served by index (wallet_id, occurred_at DESC)\nSELECT w.id AS wallet_id, w.name, t.id AS tx_id, t.amount_minor, t.occurred_at, c.name AS category\nFROM wallets w\nLEFT JOIN LATERAL (\n  SELECT id, amount_minor, occurred_at, category_id\n  FROM transactions\n  WHERE wallet_id = w.id\n  ORDER BY occurred_at DESC\n  LIMIT 5\n) t ON true\nLEFT JOIN categories c ON c.id = t.category_id\nWHERE w.user_id = $1;</pre>Pool được đặt sao cho tổng kết nối của mọi pod nhỏ hơn <code>max_connections</code>, chừa phần cho migration và admin."},
  "w3k6": {c:"Migration là các thay đổi schema ghi thành file có version, chạy theo thứ tự và được ghi nhận trong bảng lịch sử của tool (vd <code>_prisma_migrations</code>), để mọi môi trường có cùng schema và thay đổi được review như code.", e:"<ul><li>Quy trình: dev sinh migration (<code>prisma migrate dev</code>, <code>drizzle-kit generate</code>) và review file SQL sinh ra; CI/CD áp dụng bằng lệnh chỉ chạy migration có sẵn (<code>prisma migrate deploy</code>, <code>drizzle-kit migrate</code>). Không dùng <code>db push</code> hay <code>synchronize</code> trên production.</li> <li>Chạy ở đâu: một bước riêng trước khi rollout (job chạy một lần trong pipeline hoặc Kubernetes Job), không chạy trong lúc từng pod khởi động: nhiều pod chạy cùng lúc, startup chậm, lỗi migration làm pod crash loop.</li> <li>Trong rolling deploy, code cũ và mới chạy song song, nên schema phải tương thích với cả hai. Expand/contract: thêm cột/bảng mới (nullable) → deploy code ghi cả hai nơi → backfill theo batch → chuyển đọc sang chỗ mới → release sau mới xóa cột cũ. Đổi tên cột trực tiếp là breaking change.</li> <li>Khóa: phần lớn <code>ALTER TABLE</code> lấy khóa ACCESS EXCLUSIVE; nếu nó phải xếp hàng sau một query dài, mọi query đến sau cũng bị chặn theo và API treo. Đặt <code>lock_timeout</code> ngắn rồi retry. Từ PostgreSQL 11, thêm cột có DEFAULT hằng không viết lại bảng; đổi kiểu cột thì thường viết lại cả bảng. Thêm NOT NULL cho bảng lớn: thêm <code>CHECK (col IS NOT NULL) NOT VALID</code>, <code>VALIDATE CONSTRAINT</code> (khóa nhẹ), rồi <code>SET NOT NULL</code> sẽ dùng constraint đã validate để bỏ qua bước quét.</li> <li>Rollback: down migration hiếm khi an toàn với dữ liệu đã ghi; thực tế thường \"roll forward\" bằng migration mới, và có backup/PITR trước thay đổi lớn.</li></ul>", x:"Cần đổi <code>transactions.amount</code> (numeric) thành <code>amount_minor</code> (bigint). Lần thử đầu trên staging dùng một câu <code>ALTER COLUMN TYPE</code>: bảng triệu dòng bị viết lại, giữ khóa ACCESS EXCLUSIVE nhiều phút, app mobile timeout hàng loạt. Làm lại theo expand/contract qua ba release:<pre>-- Release 1 (expand)\nSET lock_timeout = '3s';\nALTER TABLE transactions ADD COLUMN amount_minor bigint;   -- nullable: metadata-only, instant\n-- app 1.1 writes both amount and amount_minor\n\n-- Backfill job, batch by batch (not inside the migration)\nUPDATE transactions t SET amount_minor = round(t.amount * 100)   -- scale depends on the currency\nWHERE t.id IN (SELECT id FROM transactions WHERE amount_minor IS NULL LIMIT 5000);\n\n-- Release 2: app reads amount_minor; enforce NOT NULL without a long lock\nALTER TABLE transactions ADD CONSTRAINT amount_minor_nn CHECK (amount_minor IS NOT NULL) NOT VALID;\nALTER TABLE transactions VALIDATE CONSTRAINT amount_minor_nn;\nALTER TABLE transactions ALTER COLUMN amount_minor SET NOT NULL;\nALTER TABLE transactions DROP CONSTRAINT amount_minor_nn;\n\n-- Release 3 (contract), once no running version reads it\nALTER TABLE transactions DROP COLUMN amount;</pre>Mỗi bước là một migration riêng chạy trong pipeline, và mỗi release đều rollback được về bản code liền trước mà không mất dữ liệu."},
  "w3k7": {c:"MongoDB lưu document BSON trong collection. Mongoose (dòng 9.x hiện tại) là ODM cho Node: định nghĩa Schema, validate, cast kiểu, middleware (hook) và <code>populate</code> trước khi gửi lệnh xuống MongoDB driver.", e:"<ul><li>Embed hay reference: embed khi dữ liệu con luôn đọc cùng cha, số lượng có giới hạn và không cần truy vấn riêng (tag, cấu hình ngân sách theo danh mục). Reference khi dữ liệu tăng không giới hạn (giao dịch của một user): mảng lớn tiến dần tới giới hạn 16MB và mỗi lần cập nhật phải ghi lại document lớn. Mẫu lai hay gặp: lưu reference kèm vài field denormalize (tên danh mục), đổi lại phải cập nhật nhiều nơi khi đổi tên.</li> <li><code>populate()</code> không phải JOIN: Mongoose chạy thêm query <code>$in</code> từ phía ứng dụng; populate lồng nhiều tầng là nhiều round trip. Join phía server dùng <code>$lookup</code> trong aggregation.</li> <li>Aggregation pipeline: đặt <code>$match</code> sớm nhất để dùng được index, rồi <code>$group</code>, <code>$sort</code>, <code>$project</code>; <code>$facet</code> cho nhiều thống kê trong một lần. Bẫy: <code>Model.aggregate()</code> không cast theo schema như <code>find()</code>, truyền <code>userId</code> dạng string sẽ không khớp document nào chứa ObjectId.</li> <li>Index: compound index theo quy tắc ESR (Equality, Sort, Range); kiểm tra bằng <code>explain('executionStats')</code>, so <code>totalDocsExamined</code> với <code>nReturned</code>, thấy <code>COLLSCAN</code> là thiếu index. Tắt <code>autoIndex</code> ở production và tạo index bằng script có kiểm soát.</li> <li>Mongoose: <code>lean()</code> trả object thuần, nhanh và nhẹ hơn hẳn cho API chỉ đọc (mất getter, virtual, <code>save()</code>). Mongoose 9 bỏ kiểu pre middleware dùng callback <code>next</code>, dùng async function. Transaction nhiều document cần replica set. Tiền dùng số nguyên đơn vị nhỏ nhất hoặc <code>Decimal128</code>, không dùng <code>Number</code> thập phân.</li></ul>", x:"Bản prototype của Expense Tracker lưu giao dịch thành mảng embed trong document user. User dùng lâu có document vài MB, mỗi lần thêm giao dịch là ghi lại cả document, latency tăng dần và có nguy cơ chạm 16MB. Chuyển sang collection riêng dùng reference, báo cáo bằng aggregation:<pre>const txSchema = new Schema({\n  userId:      { type: Schema.Types.ObjectId, ref: 'User', required: true },\n  categoryId:  { type: Schema.Types.ObjectId, ref: 'Category' },\n  amountMinor: { type: Number, required: true, validate: Number.isSafeInteger },  // integer minor units\n  occurredAt:  { type: Date, required: true },\n});\ntxSchema.index({ userId: 1, occurredAt: -1 });          // ESR: equality, then sort/range\nconst Tx = model('Transaction', txSchema);\n\nconst report = await Tx.aggregate([\n  { $match: {                                          // first stage, so it can use the index\n      userId: new Types.ObjectId(userId),              // aggregate() does NOT cast strings\n      occurredAt: { $gte: from, $lt: to } } },\n  { $group: { _id: '$categoryId', total: { $sum: '$amountMinor' }, count: { $sum: 1 } } },\n  { $lookup: { from: 'categories', localField: '_id', foreignField: '_id', as: 'category' } },\n  { $sort: { total: 1 } },\n]);</pre>Bug đầu tiên sau khi chuyển: báo cáo trả mảng rỗng vì <code>userId</code> truyền vào là string; <code>find()</code> tự cast nên trước đó không ai để ý."},
  "w3k8": {c:"Nhóm kỹ thuật cho bảng lớn sống lâu: phân trang không chậm dần theo số trang, tìm kiếm văn bản bằng index chuyên dụng thay cho <code>LIKE '%x%'</code>, xóa mềm để khôi phục được, và audit log để biết ai đổi gì, lúc nào.", e:"<ul><li>Phân trang: keyset cho infinite scroll và API cho mobile; offset chỉ cho bảng nhỏ hoặc trang admin cần nhảy trang. Cần tổng số thì dùng ước lượng (<code>reltuples</code> trong <code>pg_class</code>) hoặc bỏ hẳn.</li> <li>Full-text search của PostgreSQL: <code>tsvector</code> + GIN, truy vấn bằng <code>websearch_to_tsquery</code>, xếp hạng bằng <code>ts_rank</code>. PostgreSQL không có từ điển tiếng Việt sẵn, nên thường dùng cấu hình <code>simple</code> kết hợp extension <code>unaccent</code> để tìm không dấu, hoặc <code>pg_trgm</code> với GIN <code>gin_trgm_ops</code> để <code>ILIKE '%cafe%'</code> dùng được index. Bẫy: <code>unaccent()</code> chỉ là STABLE nên không đưa thẳng vào index được, phải bọc bằng hàm IMMUTABLE. Cần typo tolerance, relevance tốt trên dữ liệu lớn thì dùng search engine riêng (OpenSearch, Meilisearch) đồng bộ qua outbox hoặc CDC.</li> <li>Soft delete bằng <code>deleted_at</code>: mọi query phải lọc, quên một chỗ là lộ dữ liệu đã xóa (ORM extension hoặc view giúp giảm sót). Unique constraint phải thành partial unique index <code>WHERE deleted_at IS NULL</code>, nếu không người dùng không tạo lại được danh mục trùng tên đã xóa. Yêu cầu xóa dữ liệu cá nhân theo luật có thể đòi xóa thật, cần job purge.</li> <li>Audit log: bảng append-only (<code>actor_id</code>, <code>action</code>, <code>entity</code>, <code>entity_id</code>, <code>before</code>/<code>after</code> dạng jsonb, <code>request_id</code>, thời điểm). Ghi trong cùng transaction với thay đổi; trigger DB bắt được cả thay đổi ngoài app nhưng cần <code>SET LOCAL app.user_id</code> để biết actor. PostgreSQL 18 cho <code>RETURNING</code> lấy cả <code>OLD</code> và <code>NEW</code>, tiện lấy before/after trong một câu.</li></ul>", x:"Tính năng \"tìm giao dịch theo ghi chú\" ban đầu dùng <code>note ILIKE '%ca phe%'</code>: quét cả bảng và không khớp \"Cà phê sáng\". Cùng đợt đó có báo lỗi người dùng không tạo lại được danh mục \"Ăn uống\" sau khi đã xóa nó. Sửa cả hai:<pre>CREATE EXTENSION IF NOT EXISTS unaccent;\nCREATE EXTENSION IF NOT EXISTS pg_trgm;\n\n-- unaccent() is STABLE; an IMMUTABLE wrapper with an explicit dictionary can be indexed\nCREATE FUNCTION f_unaccent(text) RETURNS text\n  LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT\n  RETURN public.unaccent('public.unaccent'::regdictionary, $1);\n\nCREATE INDEX tx_note_trgm ON transactions\n  USING gin (f_unaccent(lower(note)) gin_trgm_ops)\n  WHERE deleted_at IS NULL;\n\nSELECT id, note, amount_minor FROM transactions\nWHERE user_id = $1 AND deleted_at IS NULL\n  AND f_unaccent(lower(note)) ILIKE '%' || f_unaccent(lower($2)) || '%';\n\n-- soft delete: uniqueness only among live rows\nALTER TABLE categories DROP CONSTRAINT categories_user_id_name_key;\nCREATE UNIQUE INDEX categories_name_live ON categories (user_id, lower(name))\n  WHERE deleted_at IS NULL;</pre>Xóa danh mục giờ là <code>UPDATE … SET deleted_at = now() RETURNING OLD.*, NEW.*</code> để ghi audit log trong cùng transaction."},
  "w3k9": {c:"Scale database theo thứ tự chi phí tăng dần: tối ưu query và index, cache, read replica cho tải đọc, partitioning để chia bảng lớn trong một server, cuối cùng là sharding để chia dữ liệu ra nhiều server. Idempotency key giúp một thao tác ghi (thanh toán, tạo giao dịch) được retry an toàn mà chỉ có hiệu lực đúng một lần.", e:"<ul><li>Read replica: streaming replication thường bất đồng bộ nên có replication lag; đọc ngay sau khi ghi có thể không thấy dữ liệu (tạo giao dịch xong, danh sách chưa có). Cách xử lý: read-your-writes (đọc từ primary trong vài giây sau khi user đó ghi, hoặc cho request quan trọng), chỉ đưa báo cáo và analytics sang replica.</li> <li>Partitioning (declarative): <code>PARTITION BY RANGE (occurred_at)</code> theo tháng; partition pruning khi query có điều kiện trên khóa partition; xóa dữ liệu cũ bằng <code>DETACH</code>/<code>DROP</code> partition thay vì <code>DELETE</code> khổng lồ. Ràng buộc: primary key và unique phải chứa cột khóa partition; partition tương lai phải được tạo trước (pg_partman hoặc job định kỳ).</li> <li>Sharding: chia theo <code>user_id</code> để dữ liệu một user nằm cùng shard và mọi query chính đều có <code>user_id</code>. Cái giá: query và transaction xuyên shard, resharding, vận hành nhiều cụm (Citus là một lựa chọn trên PostgreSQL). App như Expense Tracker hiếm khi cần tới bước này.</li> <li>Idempotency key: client sinh UUID cho mỗi thao tác, gửi qua header <code>Idempotency-Key</code> và giữ nguyên khi retry (header này có bản nháp ở IETF nhưng chưa thành RFC; Stripe dùng phổ biến). Server lưu <code>(user_id, key)</code> unique cùng hash của request và response; trùng key cùng request thì trả lại response cũ, trùng key khác body thì báo lỗi. Ghi key trong cùng transaction với thao tác, đặt TTL (vd 24 giờ).</li> <li>Có natural key (mã giao dịch ngân hàng khi import CSV) thì unique constraint trên dữ liệu là đủ; idempotency key là giải pháp tổng quát.</li></ul>", x:"Người dùng tạo giao dịch khi mạng chập chờn: <code>POST /v1/transactions</code> timeout phía app nhưng server đã ghi xong, app retry và giao dịch bị nhân đôi, số dư ví sai. Thêm idempotency key:<pre>CREATE TABLE idempotency_keys (\n  user_id      uuid NOT NULL,\n  key          text NOT NULL,\n  request_hash text NOT NULL,\n  status_code  int,\n  response     jsonb,\n  created_at   timestamptz NOT NULL DEFAULT now(),   -- purge after 24h\n  PRIMARY KEY (user_id, key)\n);\n\n// handler\nconst key = req.get('Idempotency-Key');\nconst hash = createHash('sha256').update(JSON.stringify(req.body)).digest('hex');\nconst client = await pool.connect();\ntry {\n  await client.query('BEGIN');\n  const ins = await client.query(\n    `INSERT INTO idempotency_keys (user_id, key, request_hash) VALUES ($1, $2, $3)\n     ON CONFLICT DO NOTHING`, [userId, key, hash]);\n  if (ins.rowCount === 0) {                      // key already used and committed\n    await client.query('ROLLBACK');\n    const { rows: [saved] } = await client.query(\n      'SELECT request_hash, status_code, response FROM idempotency_keys WHERE user_id = $1 AND key = $2',\n      [userId, key]);\n    if (saved.request_hash !== hash) throw new AppError('IDEMPOTENCY_KEY_REUSED', 422, 'Key reused with a different body');\n    return res.status(saved.status_code).json(saved.response);   // replay the original response\n  }\n  const tx = await createTransaction(client, userId, req.body);\n  await client.query(\n    'UPDATE idempotency_keys SET status_code = 201, response = $3 WHERE user_id = $1 AND key = $2',\n    [userId, key, tx]);\n  await client.query('COMMIT');\n  res.status(201).json(tx);\n} catch (err) { await client.query('ROLLBACK').catch(() =&gt; {}); throw err; }\nfinally { client.release(); }</pre>Vì key và response được commit cùng lúc, hai request trùng key chạy song song sẽ có một bên chờ ở <code>INSERT</code> (do unique index) tới khi bên kia commit, rồi đọc được response đã lưu thay vì tạo giao dịch thứ hai."},
};

const EXPL_ND_DB = {
  "w3k0": {"c":"Database quan hệ (PostgreSQL, MySQL) lưu dữ liệu thành bảng có schema cố định, quan hệ bằng khóa ngoại, truy vấn bằng SQL và đảm bảo ACID trên nhiều bảng. Document database (MongoDB) lưu mỗi bản ghi là một document JSON (BSON) linh hoạt, tối ưu cho việc đọc cả cụm dữ liệu liên quan trong một lần.","e":"<ul><li>Chọn theo dạng truy vấn và yêu cầu nhất quán, không theo độ \"hot\". Dữ liệu có nhiều quan hệ chéo, cần JOIN, báo cáo tổng hợp, ràng buộc chặt (số dư ví, chuyển tiền) thì quan hệ là mặc định an toàn.</li> <li>Document hợp khi dữ liệu được đọc/ghi nguyên cụm (một bài viết kèm comment, cấu hình), schema đổi liên tục, hoặc cần scale ngang bằng sharding có sẵn. MongoDB có transaction nhiều document từ bản 4.0, nhưng mô hình dữ liệu tốt vẫn là thiết kế để hầu hết thao tác chỉ chạm một document.</li> <li>PostgreSQL có <code>jsonb</code> kèm GIN index, nên phần \"linh hoạt\" (metadata của giao dịch import từ ngân hàng) vẫn nằm được trong Postgres mà không cần thêm một database nữa.</li> <li>PostgreSQL vs MySQL: Postgres mạnh hơn ở kiểu dữ liệu (numeric, timestamptz, array, jsonb), partial index, CTE, transactional DDL; MySQL InnoDB phổ biến, đơn giản vận hành, default isolation là REPEATABLE READ với gap lock (Postgres là READ COMMITTED). Khác biệt này ảnh hưởng tới hành vi khi có tranh chấp.</li> <li>Interviewer hay hỏi vặn: \"Mongo scale tốt hơn?\" Câu trả lời đúng là scale phụ thuộc vào access pattern và shard key; Postgres một node cộng read replica phục vụ được rất nhiều hệ thống trước khi phải nghĩ đến sharding.</li></ul>","x":"Lúc khởi động Expense Tracker API, team cân nhắc MongoDB vì \"giao dịch import từ sao kê có field khác nhau tùy ngân hàng\". Nhưng tính năng lõi là chuyển tiền giữa ví, ngân sách theo danh mục và báo cáo tháng, đều cần JOIN và ràng buộc. Quyết định: PostgreSQL, phần thô của ngân hàng để trong cột <code>jsonb</code>:<pre>CREATE TABLE transactions (\n  id          uuid PRIMARY KEY DEFAULT uuidv7(),   -- PG 18+, time-ordered\n  wallet_id   uuid NOT NULL REFERENCES wallets(id),\n  category_id uuid REFERENCES categories(id),\n  amount      bigint NOT NULL,                     -- minor units\n  occurred_at timestamptz NOT NULL,\n  raw         jsonb                                -- bank-specific fields\n);\nCREATE INDEX ON transactions USING gin (raw jsonb_path_ops);</pre>Kết quả: một database duy nhất, transaction và báo cáo viết bằng SQL, vẫn giữ được độ linh hoạt cho dữ liệu import. (<code>uuidv7()</code> có từ PostgreSQL 18; bản cũ hơn dùng <code>gen_random_uuid()</code> hoặc sinh UUIDv7 ở app.)"},
  "w3k1": {"c":"Thiết kế schema là quyết định bảng, cột, kiểu dữ liệu và ràng buộc. Chuẩn hóa (normalization) loại bỏ dữ liệu lặp để mỗi sự thật chỉ nằm một chỗ; khóa ngoại và constraint để database tự bảo vệ tính đúng đắn thay vì chỉ trông vào code.","e":"<ul><li>Chuẩn hóa tới khoảng 3NF là mặc định; chỉ denormalize có chủ đích (cột tổng cache, bảng tổng hợp) khi đo được truy vấn chậm, và phải có cơ chế giữ đồng bộ.</li> <li>Khóa ngoại chặn dữ liệu mồ côi; chọn rõ <code>ON DELETE</code> (<code>RESTRICT</code>, <code>CASCADE</code>, <code>SET NULL</code>). Postgres không tự tạo index cho cột khóa ngoại phía con, nên JOIN và DELETE cha có thể chậm nếu quên.</li> <li>Tiền: không bao giờ dùng <code>float</code>/<code>double</code>. Dùng <code>numeric(19,4)</code> hoặc số nguyên theo đơn vị nhỏ nhất (<code>bigint</code> đồng, cent). Driver <code>pg</code> trả <code>numeric</code> và <code>bigint</code> dưới dạng string vì <code>number</code> của JS chỉ an toàn tới 2^53; xử lý bằng <code>BigInt</code> hoặc thư viện decimal, đừng <code>parseFloat</code>. Lưu kèm mã tiền tệ.</li> <li>Thời gian: dùng <code>timestamptz</code>. Nó không lưu múi giờ mà lưu một thời điểm tuyệt đối (UTC), chuyển theo <code>TimeZone</code> của session khi hiển thị. <code>timestamp</code> không tz là \"giờ đồng hồ treo tường\" mơ hồ.</li> <li>Đẩy bất biến xuống DB: <code>NOT NULL</code>, <code>CHECK (amount &lt;&gt; 0)</code>, <code>UNIQUE</code>. Validation ở app có thể bị bỏ qua bởi script, job hay race condition; constraint thì không.</li></ul>","x":"Bug thật: báo cáo tháng 10 của người dùng ở Việt Nam thiếu các giao dịch tối 31/10 và lại thừa giao dịch sáng 1/10 của tháng sau. Nguyên nhân là <code>date_trunc</code> chạy theo UTC trên server, trong khi user ở UTC+7. Cùng lúc, tổng chi bị lệch vài đồng vì code cộng <code>parseFloat</code> các giá trị <code>numeric</code>:<pre>-- Group by the user's local month, not the server's\nSELECT date_trunc('month', occurred_at AT TIME ZONE $2) AS month,\n       category_id, sum(amount) AS total      -- bigint minor units\nFROM transactions\nWHERE wallet_id = $1\nGROUP BY 1, 2;\n-- $2 = 'Asia/Ho_Chi_Minh' (stored per user)</pre>Sửa: lưu múi giờ IANA trong hồ sơ user, gom nhóm bằng <code>AT TIME ZONE</code>, chuyển cột tiền sang <code>bigint</code> đơn vị nhỏ nhất và cộng bằng SQL hoặc <code>BigInt</code>. Thêm <code>CHECK (amount &lt;&gt; 0)</code> để chặn giao dịch 0 đồng do lỗi import."},
  "w3k2": {"c":"Index là cấu trúc dữ liệu phụ giúp database tìm hàng mà không quét cả bảng. B-tree là loại mặc định, hỗ trợ so sánh bằng, khoảng và sắp xếp. <code>EXPLAIN ANALYZE</code> chạy thật câu truy vấn và cho biết planner đã chọn kế hoạch nào, mỗi bước tốn bao lâu.","e":"<ul><li>Composite index <code>(a, b, c)</code> được sắp theo a rồi b rồi c. Quy tắc: cột so sánh bằng đặt trước, cột range hoặc ORDER BY đặt sau. <code>(user_id, occurred_at)</code> phục vụ tốt \"giao dịch của user X gần nhất\", còn <code>(occurred_at, user_id)</code> thì gần như vô dụng cho truy vấn đó. PostgreSQL 18 có skip scan cho B-tree nhiều cột, giúp một số truy vấn bỏ cột đầu, nhưng không thay thế được việc chọn đúng thứ tự.</li> <li>Partial index: <code>WHERE deleted_at IS NULL</code> chỉ index các hàng còn sống, nhỏ hơn và nhanh hơn. Covering index: <code>INCLUDE (amount)</code> cho phép index-only scan, nhưng chỉ hiệu quả khi visibility map đã được VACUUM cập nhật.</li> <li>Đọc plan: <code>Seq Scan</code> trên bảng lớn, <code>rows</code> ước lượng lệch xa thực tế (thống kê cũ, chạy <code>ANALYZE</code>), <code>Sort</code> tràn ra đĩa, <code>Rows Removed by Filter</code> lớn. Thêm <code>BUFFERS</code> để biết đọc từ cache hay đĩa (từ PG 18, <code>EXPLAIN ANALYZE</code> tự bật BUFFERS).</li> <li>Bẫy: <code>EXPLAIN ANALYZE</code> thực thi thật, với UPDATE/DELETE phải bọc trong <code>BEGIN … ROLLBACK</code>. Hàm trên cột (<code>lower(email)</code>, ép kiểu) làm mất index trừ khi có expression index.</li> <li>Index không miễn phí: mỗi INSERT/UPDATE phải cập nhật mọi index, tốn dung lượng. Bỏ index không dùng (xem <code>pg_stat_user_indexes</code>).</li></ul>","x":"Sau khi seed 1 triệu giao dịch, màn \"Lịch sử\" của Expense Tracker mất gần 2 giây. Plan cho thấy Postgres dùng index đơn trên <code>wallet_id</code> rồi sort hàng chục nghìn hàng:<pre>EXPLAIN (ANALYZE, BUFFERS)\nSELECT id, amount, occurred_at FROM transactions\nWHERE wallet_id = $1 AND deleted_at IS NULL\nORDER BY occurred_at DESC LIMIT 20;\n-- before: Bitmap Heap Scan + Sort (top-N heapsort)  ~1800 ms\n\nCREATE INDEX CONCURRENTLY tx_wallet_time_live\n  ON transactions (wallet_id, occurred_at DESC)\n  INCLUDE (amount)\n  WHERE deleted_at IS NULL;\n-- after: Index Only Scan using tx_wallet_time_live  ~0.3 ms</pre>Index composite đúng thứ tự cho phép Postgres đọc thẳng 20 hàng đầu đã sắp xếp, không cần sort. Dùng <code>CONCURRENTLY</code> để không khóa ghi bảng trên production; lệnh này không chạy được trong transaction, nên tách riêng file migration."},
  "w3k3": {"c":"Transaction gom nhiều câu lệnh thành một đơn vị: hoặc tất cả thành công, hoặc không có gì (ACID: Atomicity, Consistency, Isolation, Durability). Isolation level quyết định các transaction chạy song song nhìn thấy thay đổi của nhau tới mức nào; race condition xảy ra khi kết quả phụ thuộc vào thứ tự xen kẽ của chúng.","e":"<ul><li>PostgreSQL mặc định READ COMMITTED: mỗi câu lệnh thấy dữ liệu đã commit tại thời điểm câu đó bắt đầu. Vì vậy mẫu \"SELECT số dư, kiểm tra trong app, rồi UPDATE\" vẫn bị lost update khi hai request chạy cùng lúc.</li> <li>REPEATABLE READ trong Postgres là snapshot isolation (chặt hơn chuẩn SQL, không có phantom read); khi đụng hàng vừa bị transaction khác sửa sẽ lỗi <code>40001</code>. SERIALIZABLE (SSI) phát hiện cả write skew, nhưng app bắt buộc phải retry khi gặp serialization failure.</li> <li>Pessimistic locking: <code>SELECT … FOR UPDATE</code> khóa hàng tới hết transaction. Khóa nhiều hàng thì luôn khóa theo thứ tự cố định (sắp theo id) để tránh deadlock; Postgres sẽ phát hiện deadlock và hủy một bên.</li> <li>Optimistic locking: cột <code>version</code>, <code>UPDATE … WHERE id = $1 AND version = $2</code>; nếu 0 hàng bị ảnh hưởng nghĩa là có người sửa trước, trả 409 hoặc retry. Hợp khi tranh chấp hiếm và thao tác kéo dài (người dùng sửa form).</li> <li>Đơn giản nhất thường là cập nhật nguyên tử kèm điều kiện: <code>UPDATE wallets SET balance = balance - $1 WHERE id = $2 AND balance &gt;= $1</code>. Đừng giữ transaction mở trong lúc gọi HTTP bên ngoài: khóa bị giữ lâu và connection pool cạn.</li></ul>","x":"Bug ở tính năng chuyển tiền giữa hai ví: người dùng bấm hai lần liên tiếp, cả hai request đều đọc số dư 500.000, đều thấy đủ tiền và cùng trừ, ví về âm. Lần sửa đầu tiên dùng <code>FOR UPDATE</code> nhưng khóa theo thứ tự (from, to), nên hai lần chuyển ngược chiều A→B và B→A bị deadlock. Bản cuối:<pre>await prisma.$transaction(async (tx) =&gt; {\n  const [a, b] = [fromId, toId].sort();           // fixed lock order\n  await tx.$queryRaw`SELECT id FROM wallets\n    WHERE id IN (${a}, ${b}) ORDER BY id FOR UPDATE`;\n  const debited = await tx.$executeRaw`UPDATE wallets\n    SET balance = balance - ${amount}\n    WHERE id = ${fromId} AND balance &gt;= ${amount}`;\n  if (debited === 0) throw new InsufficientFundsError();\n  await tx.$executeRaw`UPDATE wallets SET balance = balance + ${amount}\n    WHERE id = ${toId}`;\n});</pre>Khóa theo thứ tự id cố định, trừ tiền bằng UPDATE có điều kiện, và nút chuyển tiền gửi kèm idempotency key để lần bấm thứ hai không tạo giao dịch mới."},
  "w3k4": {"c":"ORM (Prisma, TypeORM, Sequelize, Mongoose) ánh xạ bảng thành model/object và sinh SQL cho bạn. Query builder (Knex, Drizzle, Kysely) cho bạn viết SQL bằng API của ngôn ngữ, có kiểm tra kiểu, nhưng vẫn sát với SQL thật.","e":"<ul><li>Prisma: schema riêng (<code>schema.prisma</code>), sinh client type-safe, có migrate. Từ Prisma 7 (11/2025), client mặc định chạy không cần Rust engine: query được biên dịch bằng TypeScript và bắt buộc dùng driver adapter (ví dụ <code>@prisma/adapter-pg</code>). Điểm yếu: truy vấn phức tạp (CTE, window function, <code>FOR UPDATE</code>) phải xuống raw SQL.</li> <li>Drizzle: schema viết bằng TypeScript, API gần SQL, nhẹ, hợp serverless; drizzle-kit sinh migration. Bản 1.0 đang ở giai đoạn RC (10/2026), bản stable vẫn là 0.x.</li> <li>TypeORM: kiểu Active Record/Data Mapper với decorator, hợp với NestJS; đã lên 1.x. Lazy relation và <code>synchronize: true</code> là hai nguồn sự cố kinh điển. Sequelize: lâu đời, bản stable vẫn là v6, v7 nằm ở alpha rất lâu. Knex: query builder thuần JS, migration đơn giản.</li> <li>Tiêu chí chọn: an toàn kiểu, mức kiểm soát SQL, migration, hiệu năng, hỗ trợ transaction/lock, cộng đồng. Không có ORM nào giúp bạn khỏi phải hiểu SQL; luôn bật log query khi dev.</li> <li>Raw SQL vẫn phải tham số hóa: <code>$queryRaw</code> dạng tagged template của Prisma an toàn, còn <code>$queryRawUnsafe</code> với chuỗi nối là SQL injection.</li></ul>","x":"Expense Tracker dùng Prisma cho CRUD, nhưng báo cáo \"chi tiêu theo danh mục, so với cùng kỳ tháng trước\" cần window function. Lần đầu dev viết bằng <code>findMany</code> rồi gom trong JS: kéo 200.000 hàng về Node, tốn 1,5 GB RAM. Chuyển sang raw SQL có kiểu:<pre>type Row = { category_id: string; month: Date; total: bigint; prev: bigint | null };\n\nconst rows = await prisma.$queryRaw&lt;Row[]&gt;`\n  SELECT category_id, month, total,\n         lag(total) OVER (PARTITION BY category_id ORDER BY month) AS prev\n  FROM (\n    SELECT category_id,\n           date_trunc('month', occurred_at AT TIME ZONE ${tz}) AS month,\n           sum(amount) AS total\n    FROM transactions WHERE user_id = ${userId}\n    GROUP BY 1, 2\n  ) m`;</pre>Bài học trả lời phỏng vấn: dùng ORM cho phần lặp lại, để database làm việc tổng hợp, và giữ raw SQL được tham số hóa, có test, ở một repository riêng."},
  "w3k5": {"c":"N+1 query là khi lấy N bản ghi bằng 1 truy vấn rồi lại chạy thêm 1 truy vấn cho mỗi bản ghi để lấy dữ liệu liên quan. Eager loading tải quan hệ ngay từ đầu (JOIN hoặc một truy vấn <code>IN</code>); lazy loading chỉ tải khi truy cập. Connection pool là tập kết nối DB được mở sẵn và dùng lại.","e":"<ul><li>N+1 thường ẩn trong vòng lặp <code>for … await repo.findOne()</code>, trong GraphQL resolver, hoặc trong lazy relation của TypeORM (property là Promise, mỗi lần <code>await</code> là một query). Phát hiện bằng log query hoặc đếm query trong test integration.</li> <li>Sửa: eager load (<code>include</code> của Prisma, <code>relations</code>/<code>leftJoinAndSelect</code> của TypeORM), gom thành một truy vấn <code>WHERE id IN (…)</code>, hoặc DataLoader để batch theo tick. Eager load quá tay cũng hại: JOIN nhiều quan hệ một-nhiều tạo tích Descartes.</li> <li>Pool: mỗi connection Postgres là một process, tốn RAM; <code>max_connections</code> mặc định 100. Tổng kết nối = số instance × pool size; 20 pod × pool 10 đã là 200. <code>pg.Pool</code> mặc định <code>max: 10</code>.</li> <li>Serverless hoặc nhiều instance thì đặt PgBouncer (transaction mode) hoặc proxy của nhà cung cấp phía trước. Transaction mode không giữ trạng thái session (<code>SET</code>, advisory lock theo session, <code>LISTEN</code>).</li> <li>Triệu chứng pool cạn: request treo chờ connection rồi timeout, dù CPU DB thấp. Nguyên nhân hay gặp là transaction giữ connection quá lâu, hoặc quên <code>client.release()</code> khi dùng <code>pool.connect()</code>.</li></ul>","x":"Endpoint <code>GET /transactions</code> của Expense Tracker trả 50 giao dịch kèm tên danh mục và ví. Log cho thấy 101 query mỗi request; dưới tải, pool 10 connection cạn và p99 vọt lên 8 giây:<pre>// BUG: 1 + 2N queries\nconst txs = await prisma.transaction.findMany({ where: { userId }, take: 50 });\nfor (const t of txs) {\n  t.category = await prisma.category.findUnique({ where: { id: t.categoryId } });\n  t.wallet = await prisma.wallet.findUnique({ where: { id: t.walletId } });\n}\n\n// Fix: one call, relations loaded in bulk\nconst txs = await prisma.transaction.findMany({\n  where: { userId }, take: 50, orderBy: { occurredAt: 'desc' },\n  include: { category: { select: { name: true } }, wallet: { select: { name: true } } },\n});</pre>Sau khi sửa còn 1 đến 3 query mỗi request. Team cũng tính lại pool: 6 pod × 10 connection, cộng PgBouncer, để không vượt <code>max_connections</code> khi autoscale."},
  "w3k6": {"c":"Migration là các file thay đổi schema có đánh version, chạy theo thứ tự và được ghi lại trong một bảng của database để biết bản nào đã áp dụng. Đổi schema không downtime theo mẫu expand / contract: thêm cấu trúc mới tương thích với code cũ, chuyển dần, rồi mới gỡ cấu trúc cũ.","e":"<ul><li>Migration được commit cùng code, review như code, và chạy tự động ở bước deploy (job riêng hoặc init container), chỉ một tiến trình chạy tại một thời điểm. Không sửa migration đã chạy trên production; muốn đổi thì viết migration mới. Tuyệt đối không dùng <code>synchronize</code> của TypeORM trên production.</li> <li>Khi rolling deploy, code cũ và code mới chạy song song, nên schema phải tương thích với cả hai. Đổi tên cột theo expand/contract: thêm cột mới, ghi vào cả hai, backfill theo lô, chuyển đọc sang cột mới, ngừng ghi cột cũ, cuối cùng mới drop. Mỗi bước là một lần deploy.</li> <li>Lệnh nguy hiểm trên bảng lớn: thêm cột có default volatile, đổi kiểu cột (rewrite bảng), tạo index không <code>CONCURRENTLY</code>, thêm khóa ngoại hoặc <code>CHECK</code> không có <code>NOT VALID</code>. Từ PG 11, thêm cột với default hằng số chỉ sửa metadata.</li> <li>Mọi DDL cần khóa <code>ACCESS EXCLUSIVE</code> trong chốc lát; nếu phải chờ một transaction dài, nó xếp hàng và chặn luôn mọi truy vấn phía sau. Đặt <code>SET lock_timeout = '5s'</code> để fail nhanh rồi retry.</li> <li>Backfill hàng triệu hàng: chia lô, chạy ở job nền, không gói trong một transaction khổng lồ.</li></ul>","x":"Expense Tracker cần đổi <code>transactions.note</code> thành <code>description</code> và bắt buộc <code>category_id</code>. Lần thử đầu viết một migration <code>RENAME COLUMN</code> + <code>SET NOT NULL</code>: trong vài phút rolling deploy, pod cũ báo lỗi \"column note does not exist\", và <code>SET NOT NULL</code> quét cả bảng trong lúc giữ khóa. Làm lại theo nhiều bước:<pre>-- Release 1 (expand): new column, app writes both\nALTER TABLE transactions ADD COLUMN description text;\n-- background job: UPDATE ... SET description = note WHERE id BETWEEN ... (batches)\n\n-- Release 2: app reads description; enforce NOT NULL without a long lock\nSET lock_timeout = '5s';\nALTER TABLE transactions ADD CONSTRAINT tx_category_nn\n  CHECK (category_id IS NOT NULL) NOT VALID;\nALTER TABLE transactions VALIDATE CONSTRAINT tx_category_nn;  -- no write lock\nALTER TABLE transactions ALTER COLUMN category_id SET NOT NULL; -- uses the check, no scan\n\n-- Release 3 (contract): stop writing note, then\nALTER TABLE transactions DROP COLUMN note;</pre>Mỗi bước deploy riêng, rollback được, và không có lúc nào code đang chạy không khớp với schema."},
  "w3k7": {"c":"MongoDB lưu document BSON trong collection; Mongoose là ODM cho Node.js, thêm schema, validation, middleware và populate. Thiết kế dữ liệu xoay quanh lựa chọn embed (nhúng dữ liệu liên quan vào cùng document) hay reference (lưu id, tra ở collection khác).","e":"<ul><li>Embed khi dữ liệu luôn được đọc cùng nhau, thuộc về cha, và số lượng có giới hạn (địa chỉ của user, các dòng của một hóa đơn). Reference khi quan hệ một-nhiều không giới hạn, dữ liệu được dùng chung, hoặc cập nhật độc lập. Document tối đa 16 MB; mảng phình mãi là anti-pattern.</li> <li>Thao tác trên một document là nguyên tử. Transaction nhiều document có từ 4.0 nhưng cần replica set, tốn chi phí hơn; mô hình tốt thì hiếm khi cần đến.</li> <li>Aggregation pipeline: <code>$match</code> → <code>$group</code> → <code>$sort</code> → <code>$project</code>, <code>$lookup</code> để join. Đặt <code>$match</code> sớm để dùng được index. Mỗi stage có giới hạn bộ nhớ, vượt thì phải tràn ra đĩa (<code>allowDiskUse</code>, mặc định bật từ MongoDB 6.0).</li> <li>Compound index theo quy tắc ESR: Equality, Sort, Range. Dùng <code>explain('executionStats')</code> để xem <code>COLLSCAN</code> hay <code>IXSCAN</code>, và tỉ lệ <code>totalDocsExamined</code> so với số kết quả trả về.</li> <li>Mongoose: <code>populate</code> thực chất là thêm query (dễ thành N+1); <code>.lean()</code> trả object thuần, nhanh hơn nhiều cho API chỉ đọc. Index khai báo trong schema được <code>autoIndex</code> tạo khi khởi động; production nên tắt và tạo index bằng migration.</li></ul>","x":"Một bản prototype của Expense Tracker lưu mọi giao dịch nhúng trong document <code>wallet</code>. Sau một năm, ví của người dùng nhập sao kê hằng ngày chạm gần 16 MB, mỗi lần thêm giao dịch phải ghi lại cả document và màn danh sách ví chậm vì tải theo cả mảng. Tách giao dịch ra collection riêng, tham chiếu bằng <code>walletId</code>:<pre>const TxSchema = new Schema({\n  walletId: { type: Schema.Types.ObjectId, ref: 'Wallet', required: true },\n  userId:   { type: Schema.Types.ObjectId, required: true },\n  amount:   { type: Number, required: true },   // integer minor units\n  category: String,\n  occurredAt: { type: Date, required: true },\n});\nTxSchema.index({ userId: 1, category: 1, occurredAt: -1 }); // E, then S/R\n\nconst byCategory = await Tx.aggregate([\n  { $match: { userId, occurredAt: { $gte: from, $lt: to } } },\n  { $group: { _id: '$category', total: { $sum: '$amount' } } },\n  { $sort: { total: 1 } },\n]);</pre>Wallet chỉ giữ thông tin ví và số dư; danh sách giao dịch phân trang bằng index, báo cáo dùng aggregation với <code>$match</code> ở đầu pipeline."},
  "w3k8": {"c":"Phân trang là trả dữ liệu theo từng trang; offset dùng <code>LIMIT/OFFSET</code>, keyset (cursor) dùng giá trị của hàng cuối trang trước. Full-text search tìm theo từ thay vì so khớp chuỗi. Soft delete đánh dấu xóa thay vì xóa thật; audit log ghi lại ai làm gì, lúc nào.","e":"<ul><li><code>OFFSET 100000</code> vẫn phải đọc rồi bỏ đi 100.000 hàng, càng về sau càng chậm, và lệch trang khi có hàng mới chen vào. Keyset: <code>WHERE (occurred_at, id) &lt; ($1, $2) ORDER BY occurred_at DESC, id DESC LIMIT 20</code>, cần index khớp đúng thứ tự đó và một cột phá hòa (<code>id</code>). Đổi lại không nhảy được tới trang bất kỳ. Cursor trả cho client nên encode (base64) để client coi đó là chuỗi mờ.</li> <li>Full-text trong Postgres: cột <code>tsvector</code> (generated column) + GIN index, truy vấn bằng <code>websearch_to_tsquery</code>. Postgres không có dictionary tiếng Việt; dùng config <code>simple</code> kết hợp extension <code>unaccent</code>, hoặc <code>pg_trgm</code> để tìm gần đúng với <code>ILIKE '%…%'</code>. Nhu cầu lớn thì mới cần Elasticsearch/OpenSearch.</li> <li>Soft delete (<code>deleted_at</code>): mọi truy vấn phải nhớ lọc, rất dễ sót; ràng buộc <code>UNIQUE</code> bị vướng hàng đã xóa, nên dùng partial unique index <code>WHERE deleted_at IS NULL</code>. Với yêu cầu xóa dữ liệu cá nhân (GDPR, Nghị định 13/2023 về bảo vệ dữ liệu cá nhân), soft delete chưa đủ, cần xóa thật hoặc ẩn danh hóa.</li> <li>Audit log: bảng chỉ append (actor, action, entity, before/after, thời điểm, request id), ghi trong cùng transaction với thay đổi, hoặc bằng trigger. Không lưu token, mật khẩu trong before/after.</li></ul>","x":"App mobile Expense Tracker cuộn vô hạn lịch sử giao dịch bằng <code>?page=</code>. Người dùng có 30.000 giao dịch cuộn tới cuối thì mỗi trang mất hơn 1 giây, và khi đồng bộ thêm giao dịch mới thì có hàng bị lặp giữa hai trang. Đổi sang cursor:<pre>// GET /transactions?limit=20&amp;cursor=eyJ0IjoiMjAyNi0xMC0wMVQwOToxMjowMFoiLCJpZCI6Ii4uLiJ9\nconst c = cursor ? JSON.parse(Buffer.from(cursor, 'base64url').toString()) : null;\nconst rows = await sql`\n  SELECT id, amount, occurred_at FROM transactions\n  WHERE user_id = ${userId} AND deleted_at IS NULL\n    ${c ? sql`AND (occurred_at, id) &lt; (${c.t}, ${c.id})` : sql``}\n  ORDER BY occurred_at DESC, id DESC\n  LIMIT ${limit + 1}`;                 // fetch one extra to know if there is more\nconst next = rows.length &gt; limit ? encode(rows[limit - 1]) : null;</pre>Index <code>(user_id, occurred_at DESC, id DESC) WHERE deleted_at IS NULL</code> giúp mọi trang có thời gian như nhau. Phần tìm kiếm ghi chú giao dịch dùng <code>pg_trgm</code> + <code>unaccent</code> để gõ \"an trua\" vẫn ra \"ăn trưa\"."},
  "w3k9": {"c":"Scale database là tăng khả năng chịu tải: read replica nhân bản dữ liệu để chia tải đọc; partitioning chia một bảng lớn thành nhiều bảng con trên cùng server; sharding chia dữ liệu ra nhiều server theo shard key. Idempotency key là khóa do client gửi kèm để một yêu cầu bị gửi lại nhiều lần chỉ được thực hiện đúng một lần.","e":"<ul><li>Thứ tự nên thử: tối ưu truy vấn và index, cache, tăng cấu hình máy, read replica, partitioning, cuối cùng mới sharding. Mỗi bước sau tăng độ phức tạp vận hành rất nhiều.</li> <li>Read replica dùng streaming replication bất đồng bộ nên có độ trễ (replication lag): user vừa tạo giao dịch rồi đọc từ replica có thể không thấy. Giải pháp: đọc từ primary trong vài giây sau khi ghi, hoặc định tuyến luồng read-your-writes về primary.</li> <li>Declarative partitioning (theo range tháng, theo list, theo hash): partition pruning giúp truy vấn có điều kiện thời gian chỉ chạm vài partition, xóa dữ liệu cũ bằng <code>DROP</code>/<code>DETACH</code> partition thay vì <code>DELETE</code> hàng loạt. Ràng buộc: primary key và unique phải chứa cột partition key.</li> <li>Sharding (Citus, hoặc tự chia ở app): chọn shard key để phân bố đều và để phần lớn truy vấn chỉ chạm một shard (với Expense Tracker là <code>user_id</code>). Truy vấn xuyên shard và transaction xuyên shard là cái giá phải trả.</li> <li>Idempotency: client sinh UUID cho mỗi thao tác, gửi trong header <code>Idempotency-Key</code>; server lưu (user, key) với ràng buộc unique cùng kết quả trả về, lần gửi lại thì trả kết quả cũ. Nếu cùng key mà body khác thì trả 422.</li></ul>","x":"Sự cố: app mobile gửi <code>POST /transfers</code>, mạng 4G chập chờn khiến request timeout phía client dù server đã xử lý xong; app tự retry và người dùng bị trừ tiền hai lần. Thêm idempotency key, ghi chung transaction với nghiệp vụ:<pre>// client: one UUID per user action, reused on every retry\n// server:\nawait db.transaction(async (tx) =&gt; {\n  const inserted = await tx.query(\n    `INSERT INTO idempotency_keys (user_id, key, request_hash)\n     VALUES ($1, $2, $3) ON CONFLICT DO NOTHING RETURNING key`,\n    [userId, key, hash(body)]);\n  if (inserted.rowCount === 0) {\n    const prev = await tx.query(\n      'SELECT request_hash, response FROM idempotency_keys WHERE user_id=$1 AND key=$2',\n      [userId, key]);\n    if (prev.rows[0].request_hash !== hash(body)) throw new UnprocessableEntity();\n    return prev.rows[0].response;          // replay, no second debit\n  }\n  const result = await doTransfer(tx, body);\n  await tx.query('UPDATE idempotency_keys SET response=$3 WHERE user_id=$1 AND key=$2',\n                 [userId, key, result]);\n  return result;\n});</pre>Nếu request đầu chưa commit, request thứ hai sẽ chờ ở ràng buộc unique rồi rơi vào nhánh replay. Bảng <code>transactions</code> cũng được partition theo tháng để báo cáo chỉ quét các partition cần thiết."}
};

const EXPL_ND_4 = {
  "w4k0": {"c":"Session + cookie: server lưu trạng thái đăng nhập (trong Redis hoặc DB), client chỉ giữ một session id ngẫu nhiên. JWT: token tự chứa claim, được ký, server xác minh chữ ký mà không cần tra cứu. Mô hình phổ biến là access token ngắn hạn kèm refresh token dài hạn, xoay vòng mỗi lần dùng.","e":"<ul><li>Session thu hồi tức thì (xóa key), dễ hiểu, hợp web cùng domain. JWT hợp khi nhiều service cần xác minh độc lập, nhưng không thu hồi được trước khi hết hạn nếu không có denylist (theo <code>jti</code>), nên access token phải ngắn (5–15 phút).</li> <li>Xác minh JWT: luôn chỉ định danh sách thuật toán (<code>algorithms: ['RS256']</code>), kiểm <code>exp</code>, <code>iss</code>, <code>aud</code>. Hai lỗi kinh điển là chấp nhận <code>alg: none</code> và algorithm confusion (dùng public key RSA làm secret HMAC). JWT chỉ được ký, không được mã hóa: đừng đặt dữ liệu nhạy cảm vào payload.</li> <li>Refresh token: chuỗi ngẫu nhiên mờ, lưu hash trong DB, gắn với thiết bị. Mỗi lần refresh cấp cặp mới và vô hiệu token cũ. Nếu một token đã dùng rồi lại xuất hiện, coi như bị đánh cắp và thu hồi cả \"family\". RFC 9700 yêu cầu refresh token của public client phải sender-constrained hoặc xoay vòng.</li> <li>Lưu token: app mobile dùng Keychain/Keystore; web nên dùng cookie <code>HttpOnly</code> thay vì <code>localStorage</code> (XSS đọc được).</li> <li>Đăng xuất, đổi mật khẩu: thu hồi refresh token của thiết bị hoặc toàn bộ; access token còn sống tối đa vài phút, chấp nhận hoặc thêm denylist.</li></ul>","x":"Expense Tracker cấp access token 15 phút và refresh token 30 ngày. Lúc đầu refresh token cũng là JWT và không lưu DB, nên khi một máy Android bị root lộ token, không có cách thu hồi. Thiết kế lại:<pre>async function refresh(raw: string, deviceId: string) {\n  const row = await db.refreshToken.findUnique({ where: { hash: sha256(raw) } });\n  if (!row || row.expiresAt &lt; new Date()) throw new Unauthorized();\n  if (row.usedAt) {                                  // reuse =&gt; likely stolen\n    await db.refreshToken.updateMany({\n      where: { familyId: row.familyId }, data: { revokedAt: new Date() } });\n    throw new Unauthorized('token reuse detected');\n  }\n  if (row.revokedAt) throw new Unauthorized();\n  await db.refreshToken.update({ where: { id: row.id }, data: { usedAt: new Date() } });\n  const next = randomBytes(32).toString('base64url');\n  await db.refreshToken.create({ data: { hash: sha256(next), familyId: row.familyId,\n    userId: row.userId, deviceId, expiresAt: addDays(30) } });\n  return { accessToken: signAccess(row.userId), refreshToken: next };\n}</pre>Lưu ý race condition: app gửi hai request refresh song song khi mở lại sẽ bị nhầm là reuse. Client cần gom về một lần refresh, hoặc server cho một khoảng ân hạn vài giây."},
  "w4k1": {"c":"Mật khẩu không được lưu dạng thô hay mã hóa hai chiều, mà phải băm bằng hàm chậm có chủ đích, có salt riêng cho từng user: argon2id (ưu tiên), scrypt, bcrypt, hoặc PBKDF2 khi cần FIPS. \"Không tự viết crypto\" nghĩa là dùng thư viện và tham số đã được kiểm chứng.","e":"<ul><li>SHA-256 hay MD5 quá nhanh: GPU thử hàng tỉ lần mỗi giây. Hàm băm mật khẩu tốn CPU và (với argon2/scrypt) tốn RAM, khiến tấn công brute-force đắt.</li> <li>Tham số tối thiểu theo OWASP Password Storage Cheat Sheet: argon2id <code>m=19 MiB, t=2, p=1</code> (hoặc các cặp tương đương như <code>m=46 MiB, t=1</code>); scrypt <code>N=2^17, r=8, p=1</code>; bcrypt work factor từ 10 trở lên; PBKDF2-HMAC-SHA256 600.000 vòng.</li> <li>bcrypt chỉ dùng 72 byte đầu của input; mật khẩu dài hơn bị cắt im lặng. OWASP khuyên giới hạn độ dài mật khẩu ở 72 byte khi dùng bcrypt (chú ý ký tự tiếng Việt có dấu chiếm nhiều byte UTF-8).</li> <li>Trong Node: package <code>argon2</code> chạy native trên libuv thread pool (mặc định 4 thread, chỉnh bằng <code>UV_THREADPOOL_SIZE</code>), không chặn event loop nhưng có thể làm nghẽn các tác vụ khác dùng chung pool như <code>fs</code>, <code>dns.lookup</code>. Node có <code>crypto.argon2()</code> built-in từ v24.7.0. Đừng dùng bản <code>*Sync</code> trong request handler.</li> <li>Pepper (secret chung, lưu ngoài DB) là lớp phòng thủ thêm. Khi tăng tham số, rehash lúc user đăng nhập thành công. Trả cùng thông báo lỗi cho \"sai email\" và \"sai mật khẩu\" để tránh dò user.</li></ul>","x":"Review bảo mật Expense Tracker phát hiện endpoint đăng ký cũ băm mật khẩu bằng <code>sha256(password + 'expense')</code>, salt cố định cho mọi user. Nếu DB lộ, một rainbow table là bẻ được hàng loạt. Chuyển sang argon2id và nâng cấp dần khi user đăng nhập:<pre>import argon2 from 'argon2';\nconst OPTS = { type: argon2.argon2id, memoryCost: 19456, timeCost: 2, parallelism: 1 };\n\nasync function login(email: string, password: string) {\n  const user = await users.findByEmail(email);\n  if (!user) { await argon2.hash(password, OPTS); throw new Unauthorized(); } // same timing\n  const ok = user.hash.startsWith('$argon2')\n    ? await argon2.verify(user.hash, password)\n    : timingSafeEqualHex(legacySha256(password), user.hash);\n  if (!ok) throw new Unauthorized();\n  if (!user.hash.startsWith('$argon2') || argon2.needsRehash(user.hash, OPTS)) {\n    await users.updateHash(user.id, await argon2.hash(password, OPTS));\n  }\n  return issueTokens(user);\n}</pre>Chuỗi hash argon2 tự chứa thuật toán, tham số và salt, nên không cần cột salt riêng. Sau 90 ngày, tài khoản còn hash cũ bị buộc đặt lại mật khẩu."},
  "w4k2": {"c":"OAuth 2.0 là framework ủy quyền: cho phép app nhận access token để gọi API thay mặt user mà không cầm mật khẩu. OpenID Connect (OIDC) xây trên OAuth 2.0, thêm ID token (JWT) cho biết user là ai, tức là lớp xác thực. Authorization code + PKCE là luồng được khuyến nghị cho mọi loại client.","e":"<ul><li>Luồng: client tạo <code>code_verifier</code> ngẫu nhiên, gửi <code>code_challenge = BASE64URL(SHA256(verifier))</code> với <code>code_challenge_method=S256</code> lên trang authorize; nhận <code>code</code> qua redirect; đổi code kèm verifier lấy token. Kẻ chặn được code mà không có verifier thì không đổi được.</li> <li>RFC 9700 (OAuth 2.0 Security BCP, 01/2025): public client (app mobile, SPA) bắt buộc dùng PKCE, confidential client cũng nên dùng; không nên dùng implicit grant; không được dùng resource owner password credentials; authorization server phải so khớp redirect URI chính xác.</li> <li><code>state</code> chống CSRF trên redirect; <code>nonce</code> trong OIDC chống replay ID token. App native dùng trình duyệt hệ thống (ASWebAuthenticationSession, Custom Tabs), không dùng WebView nhúng (RFC 8252).</li> <li>Backend nhận ID token từ app (Google Sign-In, Sign in with Apple) phải xác minh chữ ký qua JWKS của provider, <code>iss</code>, <code>aud</code> đúng client id của mình, <code>exp</code>, <code>nonce</code>. Chỉ decode mà không verify là lỗ hổng.</li> <li>Apple chỉ trả tên user ở lần đăng nhập đầu và có thể trả email relay ẩn danh; dùng <code>sub</code> làm định danh, không dùng email. Chỉ tự động liên kết tài khoản theo email khi <code>email_verified</code> là true.</li></ul>","x":"Phiên bản đầu của tính năng \"Đăng nhập bằng Google\" trong Expense Tracker: app gửi ID token lên, backend chỉ <code>jwt.decode()</code> để lấy email rồi đăng nhập. Pentester tự tạo một JWT với email của nạn nhân và vào được tài khoản. Sửa bằng xác minh đầy đủ qua <code>jose</code>:<pre>import { createRemoteJWKSet, jwtVerify } from 'jose';\nconst googleJwks = createRemoteJWKSet(new URL('https://www.googleapis.com/oauth2/v3/certs'));\n\nasync function verifyGoogle(idToken: string, expectedNonce: string) {\n  const { payload } = await jwtVerify(idToken, googleJwks, {\n    issuer: ['https://accounts.google.com', 'accounts.google.com'],\n    audience: [IOS_CLIENT_ID, ANDROID_CLIENT_ID, WEB_CLIENT_ID],\n  });\n  if (payload.nonce !== expectedNonce) throw new Unauthorized();\n  return { provider: 'google', subject: payload.sub!,\n           email: payload.email_verified ? payload.email : undefined };\n}</pre>Tài khoản được khóa theo cặp (<code>provider</code>, <code>sub</code>). Apple làm tương tự với JWKS <code>https://appleid.apple.com/auth/keys</code> và issuer <code>https://appleid.apple.com</code>."},
  "w4k3": {"c":"Phân quyền (authorization) trả lời câu \"user này có được làm việc này trên tài nguyên này không\". RBAC cấp quyền theo vai trò (user, admin); ABAC quyết định dựa trên thuộc tính của user, tài nguyên và ngữ cảnh. BOLA (Broken Object Level Authorization) là lỗi không kiểm tra quyền trên từng object cụ thể.","e":"<ul><li>RBAC đơn giản, dễ audit, nhưng bùng nổ vai trò khi quy tắc phụ thuộc dữ liệu. ABAC (hoặc ReBAC, dựa trên quan hệ) diễn tả được \"chỉ thành viên ví chung có quyền editor mới được sửa giao dịch\". Thực tế thường kết hợp: RBAC cho chức năng, kiểm tra quan hệ cho dữ liệu.</li> <li>BOLA đứng đầu OWASP API Security Top 10 (API1:2023) vì nó rất dễ mắc: chỉ cần <code>GET /transactions/:id</code> tìm theo id mà không lọc theo chủ sở hữu. UUID khó đoán giảm rủi ro nhưng không thay thế kiểm tra quyền.</li> <li>Cách làm an toàn: đưa điều kiện sở hữu vào chính truy vấn (<code>WHERE id = $1 AND user_id = $2</code>), hoặc load rồi gọi policy tập trung. Trả 404 thay vì 403 để không tiết lộ object tồn tại.</li> <li>Guard ở controller (NestJS <code>@Roles</code>) chỉ kiểm tra cấp chức năng (API5: Broken Function Level Authorization); kiểm tra theo object phải nằm ở service/repository, nơi biết dữ liệu. Danh sách, export, endpoint lồng (<code>/wallets/:id/transactions</code>) và bulk action là chỗ hay sót.</li> <li>Defense in depth: Row Level Security của Postgres làm lưới an toàn cuối. Viết test cho mỗi endpoint: user A gọi tài nguyên của user B phải nhận 404.</li></ul>","x":"Bug bounty báo lỗi ở Expense Tracker: <code>PATCH /transactions/:id</code> có guard đăng nhập và RBAC, nhưng service chỉ <code>update({ where: { id } })</code>. Bất kỳ user nào biết id (lộ qua link chia sẻ báo cáo) đều sửa được giao dịch của người khác. Sửa bằng cách gắn quyền vào truy vấn và hỗ trợ ví chung:<pre>async updateTx(actor: User, id: string, dto: UpdateTxDto) {\n  const tx = await this.prisma.transaction.findFirst({\n    where: { id, wallet: { members: { some: { userId: actor.id } } } },\n    include: { wallet: { include: { members: { where: { userId: actor.id } } } } },\n  });\n  if (!tx) throw new NotFoundException();               // hide existence\n  const role = tx.wallet.members[0].role;               // 'owner' | 'editor' | 'viewer'\n  if (role === 'viewer') throw new NotFoundException();\n  return this.prisma.transaction.update({ where: { id }, data: pick(dto, ['amount', 'note', 'categoryId']) });\n}</pre>Thêm test e2e tự sinh cho mọi route có <code>:id</code>: đăng nhập bằng user khác và khẳng định nhận 404. Admin dùng endpoint riêng dưới <code>/admin</code>, có guard role và audit log."},
  "w4k4": {"c":"OWASP API Security Top 10 là danh sách 10 nhóm rủi ro phổ biến nhất của API. Bản mới nhất vẫn là bản 2023 (tính tới 10/2026): API1 BOLA, API2 Broken Authentication, API3 Broken Object Property Level Authorization, API4 Unrestricted Resource Consumption, API5 Broken Function Level Authorization, API6 Unrestricted Access to Sensitive Business Flows, API7 SSRF, API8 Security Misconfiguration, API9 Improper Inventory Management, API10 Unsafe Consumption of APIs.","e":"<ul><li>API3 gộp hai mục cũ của bản 2019: Excessive Data Exposure (trả thừa field như <code>passwordHash</code>, <code>role</code>) và Mass Assignment (client gửi thêm field <code>role: 'admin'</code> rồi server gán thẳng vào model). Chặn bằng DTO whitelist ở cả đầu vào và đầu ra.</li> <li>API4: không giới hạn kích thước body, số phần tử mỗi trang, số file upload, chi phí gọi dịch vụ trả tiền (SMS OTP, email). API6: lạm dụng luồng nghiệp vụ hợp lệ như spam tạo tài khoản để nhận khuyến mãi; cần chống bot, không chỉ sửa bug.</li> <li>API7 SSRF: server tải URL do user cung cấp (avatar, webhook, import sao kê từ link) và bị trỏ vào <code>http://169.254.169.254</code> (metadata cloud) hoặc mạng nội bộ. Chặn bằng allowlist, kiểm tra IP sau khi resolve DNS, tắt redirect.</li> <li>API9: các bản API cũ (<code>/v1</code>), môi trường staging lộ ra internet, endpoint debug bị quên. API10: tin dữ liệu từ bên thứ ba (webhook ngân hàng, API tỷ giá) mà không validate, không kiểm chữ ký, không timeout.</li> <li>Interviewer hay hỏi: khác gì OWASP Top 10 cho web? Bản web có bản 2025 (thêm Software Supply Chain Failures); bản API tập trung vào phân quyền theo object/property và lạm dụng tài nguyên.</li></ul>","x":"Pentest Expense Tracker tìm ra hai lỗi cùng nhóm API3. Một: <code>PATCH /me</code> làm <code>prisma.user.update({ data: req.body })</code>, gửi <code>{\"plan\":\"premium\",\"role\":\"admin\"}</code> là lên quyền. Hai: <code>GET /wallets/:id/members</code> trả nguyên object user kèm <code>passwordHash</code>, <code>email</code>. Sửa bằng schema cho cả input và output:<pre>import { z } from 'zod';\nconst UpdateMe = z.strictObject({            // unknown keys =&gt; 400\n  displayName: z.string().min(1).max(50).optional(),\n  timezone: z.string().optional(),\n  currency: z.enum(['VND', 'USD', 'JPY']).optional(),\n});\nconst MeOut = z.object({ id: z.string(), displayName: z.string(), timezone: z.string(), currency: z.string() });\n\napp.patch('/me', async (req, res) =&gt; {\n  const data = UpdateMe.parse(req.body);\n  const user = await prisma.user.update({ where: { id: req.user.id }, data });\n  res.json(MeOut.parse(user));                // strips everything not declared\n});</pre>Song song, endpoint import sao kê từ URL được chuyển sang chỉ nhận upload file, loại bỏ hẳn bề mặt SSRF (API7)."},
  "w4k5": {"c":"Injection xảy ra khi dữ liệu người dùng được nối vào câu lệnh (SQL, truy vấn NoSQL, shell, template) và bị diễn giải như code. Prototype pollution là lỗi riêng của JavaScript: kẻ tấn công ghi vào <code>Object.prototype</code> qua key <code>__proto__</code> hoặc <code>constructor.prototype</code>, làm thay đổi hành vi của mọi object.","e":"<ul><li>SQL injection: luôn dùng parameterized query (<code>$1</code>, <code>?</code>), dữ liệu được gửi tách khỏi câu lệnh. Tagged template của Prisma <code>$queryRaw`…${x}`</code> hay thư viện <code>postgres</code> đều tham số hóa; <code>$queryRawUnsafe</code>, <code>knex.raw</code> với chuỗi nối thì không.</li> <li>Tham số hóa không áp dụng cho tên cột, tên bảng, chiều <code>ORDER BY</code>: phải dùng allowlist (map từ giá trị client sang cột cố định).</li> <li>NoSQL injection: body JSON <code>{\"password\": {\"$ne\": null}}</code> biến điều kiện so sánh thành toán tử. Validate kiểu (phải là string), bật <code>sanitizeFilter</code> của Mongoose, hoặc ép kiểu tường minh.</li> <li>Prototype pollution: deep merge, <code>lodash.set</code> bản cũ, parse query string lồng nhau, gán <code>obj[key] = value</code> với key từ client. Hậu quả từ bypass kiểm tra quyền (<code>if (user.isAdmin)</code> đọc từ prototype) tới RCE qua gadget trong thư viện. Phòng: validate bằng schema loại key lạ, <code>Object.create(null)</code> hoặc <code>Map</code> cho dữ liệu dạng từ điển, chặn <code>__proto__</code>/<code>constructor</code>/<code>prototype</code>, cân nhắc cờ <code>--disable-proto=delete</code>.</li> <li>Command injection: dùng <code>execFile</code>/<code>spawn</code> với mảng tham số, không <code>exec</code> với chuỗi nối.</li></ul>","x":"Endpoint tìm kiếm của Expense Tracker cho phép sắp xếp theo cột: dev viết <code>$queryRawUnsafe</code> với <code>ORDER BY ${sort}</code> vì \"tham số hóa không dùng được cho ORDER BY\". Payload <code>sort=occurred_at; DROP TABLE wallets--</code> không chạy được nhờ driver không cho nhiều câu lệnh trong prepared statement, nhưng <code>sort=(CASE WHEN (SELECT …) THEN amount ELSE id END)</code> đủ để dò dữ liệu kiểu blind injection. Sửa:<pre>const SORTS = {\n  newest: Prisma.sql`occurred_at DESC, id DESC`,\n  oldest: Prisma.sql`occurred_at ASC, id ASC`,\n  amount: Prisma.sql`amount DESC, id DESC`,\n} as const;\nconst order = SORTS[req.query.sort as keyof typeof SORTS] ?? SORTS.newest;\nconst rows = await prisma.$queryRaw`\n  SELECT id, amount, note FROM transactions\n  WHERE user_id = ${userId} AND note ILIKE ${'%' + q + '%'}\n  ORDER BY ${order} LIMIT 50`;</pre>Cũng trong đợt đó, hàm <code>deepMerge(settings, req.body)</code> cho cài đặt user bị thay bằng parse qua Zod <code>strictObject</code>, sau khi test với <code>{\"__proto__\":{\"isAdmin\":true}}</code> cho thấy mọi object trong process đều có <code>isAdmin</code>."},
  "w4k6": {"c":"Cookie có các thuộc tính bảo mật: <code>HttpOnly</code> (JavaScript không đọc được), <code>Secure</code> (chỉ gửi qua HTTPS), <code>SameSite</code> (hạn chế gửi kèm request từ site khác). CSRF là tấn công lợi dụng việc trình duyệt tự gửi cookie để thực hiện hành động thay user. <code>helmet</code> là middleware đặt các HTTP security header.","e":"<ul><li><code>SameSite=Lax</code> (mặc định của Chrome khi không khai báo) chặn cookie trong POST cross-site nhưng vẫn gửi khi điều hướng GET top-level, nên GET không bao giờ được thay đổi dữ liệu. <code>Strict</code> chặn cả điều hướng. <code>None</code> bắt buộc kèm <code>Secure</code>.</li> <li>CSRF chỉ là vấn đề khi xác thực bằng thứ trình duyệt tự gửi (cookie, Basic auth). API dùng header <code>Authorization: Bearer</code> như app mobile thì không bị CSRF, nhưng token lại phơi ra cho XSS nếu lưu ở JS trên web.</li> <li>Phòng CSRF cho web dùng cookie: SameSite + kiểm tra header <code>Origin</code>, thêm CSRF token (double-submit có ký, ví dụ package <code>csrf-csrf</code>; <code>csurf</code> đã deprecated). Lưu ý \"same-site\" khác \"same-origin\": subdomain bị chiếm vẫn là same-site.</li> <li>Tiền tố <code>__Host-</code> buộc cookie có <code>Secure</code>, <code>Path=/</code>, không có <code>Domain</code>, chống subdomain ghi đè.</li> <li><code>helmet</code>: HSTS, <code>X-Content-Type-Options: nosniff</code>, CSP, <code>Referrer-Policy</code>, bỏ <code>X-Powered-By</code>. Với API JSON thuần, quan trọng nhất là HSTS, nosniff và <code>Content-Type</code> đúng. CORS không phải cơ chế chống CSRF: nó chỉ quyết định JS có đọc được response hay không, request vẫn tới server.</li></ul>","x":"Expense Tracker có thêm bản web dashboard, dùng refresh token trong cookie. Cấu hình CORS ban đầu phản chiếu mọi <code>Origin</code> kèm <code>credentials: true</code>, và cookie đặt <code>SameSite=None</code> \"để chạy được trên localhost\". Kết quả: một trang bất kỳ gọi được <code>POST /auth/refresh</code> bằng cookie của nạn nhân và đọc được access token mới. Sửa:<pre>app.use(helmet());\napp.use(cors({ origin: ['https://app.expense.example'], credentials: true }));\n\nres.cookie('__Host-rt', refreshToken, {\n  httpOnly: true, secure: true, sameSite: 'strict', path: '/',\n  maxAge: 30 * 24 * 3600 * 1000,\n});\n\n// state-changing routes that rely on cookies: verify Origin\napp.post('/auth/refresh', (req, res, next) =&gt; {\n  if (req.get('origin') !== 'https://app.expense.example') return res.sendStatus(403);\n  next();\n}, refreshHandler);</pre>Access token chỉ giữ trong bộ nhớ của web app, không ghi <code>localStorage</code>. App mobile không đổi gì: vẫn gửi Bearer header nên không chịu ảnh hưởng của CSRF."},
  "w4k7": {"c":"Rate limiting giới hạn số request một client được gửi trong một khoảng thời gian để chống brute-force, scraping và cạn tài nguyên. DoS ở tầng ứng dụng là làm server quá tải bằng request hợp lệ về mặt giao thức nhưng tốn kém (body lớn, regex chậm, truy vấn nặng).","e":"<ul><li>Thuật toán: fixed window (đơn giản, cho phép bùng gấp đôi ở ranh giới cửa sổ), sliding window, token bucket (cho phép burst có kiểm soát). Nhiều instance thì bộ đếm phải nằm ở store chung (Redis), thao tác nguyên tử (<code>INCR</code> + <code>EXPIRE</code> hoặc Lua script).</li> <li>Khóa giới hạn: theo IP cho anonymous, theo user/API key khi đã đăng nhập. Với <code>/auth/login</code>, giới hạn theo cả IP và theo tài khoản (chống credential stuffing từ botnet nhiều IP), tăng dần thời gian chờ thay vì khóa cứng tài khoản (kẻ xấu lợi dụng để khóa người khác).</li> <li>Sau load balancer, <code>req.ip</code> là IP của proxy nếu chưa cấu hình <code>app.set('trust proxy', …)</code> (Express) hoặc <code>trustProxy</code> (Fastify); tin <code>X-Forwarded-For</code> bừa bãi thì client tự giả IP được.</li> <li>Trả <code>429 Too Many Requests</code> kèm <code>Retry-After</code>. Thư viện: <code>express-rate-limit</code> + Redis store, <code>@fastify/rate-limit</code>, <code>@nestjs/throttler</code>. Rate limit ở gateway/WAF và ở app bổ sung cho nhau.</li> <li>DoS tầng app: giới hạn body (<code>express.json({ limit })</code>, Fastify <code>bodyLimit</code>), giới hạn <code>limit</code> phân trang, timeout cho truy vấn (<code>statement_timeout</code>), tránh regex dễ ReDoS, đưa việc nặng (export, import CSV) ra queue.</li></ul>","x":"Log của Expense Tracker cho thấy <code>/auth/login</code> nhận 40.000 request/giờ từ hàng nghìn IP, mỗi IP chỉ vài lần: credential stuffing bằng danh sách mật khẩu lộ từ nơi khác. Limiter theo IP (100/15 phút) không bắt được, còn argon2 làm CPU tăng vọt. Thêm limiter theo tài khoản bằng Redis:<pre>// fixed window per (email) and per (ip), atomic in Redis\nasync function hit(key: string, limit: number, windowSec: number) {\n  const n = await redis.incr(key);\n  if (n === 1) await redis.expire(key, windowSec);\n  return n &lt;= limit;\n}\n\napp.post('/auth/login', async (req, res) =&gt; {\n  const email = normalizeEmail(req.body.email);\n  const okIp = await hit(`rl:login:ip:${req.ip}`, 20, 900);\n  const okUser = await hit(`rl:login:user:${email}`, 5, 900);\n  if (!okIp || !okUser) return res.set('Retry-After', '900').status(429).end();\n  // ... verify password (argon2) only after passing the limiter\n});</pre>Kết hợp thêm kiểm tra mật khẩu bị lộ khi đăng ký và CAPTCHA sau vài lần sai. Lưu ý <code>INCR</code> rồi <code>EXPIRE</code> là hai lệnh; production nên gộp bằng <code>MULTI</code> hoặc Lua để không có key mất TTL nếu process chết giữa chừng."},
  "w4k8": {"c":"Secret (mật khẩu DB, khóa ký JWT, API key) phải nằm ngoài source code, được nạp lúc chạy từ biến môi trường hoặc secret manager. Supply chain security là bảo vệ chuỗi phụ thuộc: package npm, lockfile, script cài đặt, pipeline build, vì code của bên thứ ba chạy với đầy đủ quyền của ứng dụng.","e":"<ul><li>Không commit <code>.env</code>; dùng secret manager (AWS Secrets Manager, GCP Secret Manager, Vault, Kubernetes Secret có mã hóa) và có quy trình xoay vòng. Node có sẵn <code>--env-file</code> và <code>process.loadEnvFile()</code> cho môi trường dev. Validate config lúc khởi động để fail sớm.</li> <li>Secret bị push lên Git thì coi như đã lộ: thu hồi và tạo mới ngay, xóa khỏi lịch sử chỉ là bước phụ. Bật secret scanning trên repo.</li> <li>Lockfile + <code>npm ci</code> để build tái lập được; <code>npm audit</code>/Dependabot cho CVE đã biết. Nhưng audit không bắt được package vừa bị chiếm quyền.</li> <li>Các vụ thật: tháng 9/2025, nhiều package phổ biến như <code>chalk</code>, <code>debug</code> bị phát hành bản độc sau khi maintainer bị phishing; worm Shai-Hulud lây qua script cài đặt, đánh cắp token npm/GitHub rồi tự publish tiếp. Sau đó npm bỏ classic token và đẩy mạnh trusted publishing (OIDC từ CI, có provenance).</li> <li>Biện pháp: tắt lifecycle script của dependency (<code>npm ci --ignore-scripts</code>; pnpm 10 mặc định không chạy script của dependency trừ khi được cho phép), trì hoãn cài bản vừa phát hành (<code>minimumReleaseAge</code> của pnpm), ít dependency hơn, CI dùng token tối thiểu quyền.</li></ul>","x":"Expense Tracker từng có sự cố gần như xảy ra: Dependabot mở PR nâng một package tiện ích lên bản patch vừa phát hành vài giờ, CI chạy <code>npm install</code> và script <code>postinstall</code> của bản đó đọc biến môi trường, trong đó có <code>NPM_TOKEN</code> và khóa AWS của pipeline. Bản độc bị gỡ trước khi merge nhưng token đã bị gửi đi. Sau sự cố:<pre># .npmrc (CI)\nignore-scripts=true\n\n# pnpm-workspace.yaml\nminimumReleaseAge: 4320          # minutes: ignore versions younger than 3 days\nonlyBuiltDependencies:\n  - argon2                       # explicit allowlist for native builds\n\n# CI\npnpm install --frozen-lockfile\n# secrets injected only into the deploy job, via OIDC role, never into PR jobs</pre>Toàn bộ token bị xoay vòng, publish package nội bộ chuyển sang trusted publishing, và khóa ký JWT chuyển vào secret manager, đọc lúc khởi động thay vì nằm trong biến môi trường của mọi job CI."},
  "w4k9": {"c":"Mã hóa dữ liệu nhạy cảm gồm mã hóa khi truyền (TLS) và khi lưu (at rest: ổ đĩa, backup, hoặc từng field trong DB). Log không được chứa PII (thông tin định danh cá nhân như email, số điện thoại, số tài khoản) và secret (token, mật khẩu), vì log được nhiều người và nhiều hệ thống đọc, và giữ lâu hơn dữ liệu chính.","e":"<ul><li>TLS 1.2 trở lên (ưu tiên 1.3), HSTS; TLS thường kết thúc ở load balancer, nhưng kết nối nội bộ tới DB/Redis cũng nên mã hóa và xác minh certificate (<code>sslmode=verify-full</code>), không dùng <code>rejectUnauthorized: false</code> trên production.</li> <li>Mã hóa ổ đĩa của nhà cung cấp cloud chỉ chống mất ổ vật lý; ai có quyền truy vấn DB vẫn đọc được. Field nhạy cảm (số tài khoản ngân hàng, token liên kết ngân hàng) nên mã hóa ở tầng app bằng AES-256-GCM, IV 12 byte ngẫu nhiên cho mỗi lần mã hóa, lưu kèm auth tag.</li> <li>Envelope encryption: data key mã hóa dữ liệu, master key nằm trong KMS mã hóa data key. Lưu kèm key id để xoay vòng khóa mà vẫn giải mã được dữ liệu cũ. Cần tìm theo field đã mã hóa thì lưu thêm HMAC (blind index), vì GCM với IV ngẫu nhiên không tìm kiếm được.</li> <li>Log: dùng structured logger có redact (<code>pino</code> có option <code>redact</code>), không log nguyên <code>req.body</code>/header <code>Authorization</code>, che số tài khoản còn 4 số cuối. Log URL cũng có thể lộ token nằm trong query string.</li> <li>Pháp lý: Nghị định 13/2023/NĐ-CP của Việt Nam và GDPR đều đòi tối thiểu hóa dữ liệu; dữ liệu không cần thì đừng thu thập.</li></ul>","x":"Expense Tracker cho liên kết tài khoản ngân hàng để tự import giao dịch. Audit phát hiện hai vấn đề: token truy cập ngân hàng lưu dạng thô trong bảng <code>bank_links</code>, và middleware log in nguyên body request <code>/bank/link</code> lên hệ thống log tập trung. Sửa cả hai:<pre>import { createCipheriv, createDecipheriv, randomBytes } from 'node:crypto';\n\nfunction encrypt(plain: string, key: Buffer, keyId: string) {\n  const iv = randomBytes(12);                          // never reuse an IV with the same key\n  const c = createCipheriv('aes-256-gcm', key, iv);\n  const data = Buffer.concat([c.update(plain, 'utf8'), c.final()]);\n  return [keyId, iv, c.getAuthTag(), data].map(p =&gt; Buffer.from(p).toString('base64url')).join('.');\n}\n\nconst logger = pino({\n  redact: { paths: ['req.headers.authorization', 'req.headers.cookie',\n                    '*.password', '*.accessToken', '*.refreshToken', '*.accountNumber'],\n            censor: '[REDACTED]' },\n});</pre>Data key được lấy từ KMS khi khởi động và có <code>keyId</code> để xoay vòng; log cũ chứa token bị xóa và các token ngân hàng liên quan bị thu hồi. Một test kiểm tra chụp log của luồng đăng nhập, liên kết ngân hàng và khẳng định không có chuỗi nào trông giống token hay mật khẩu."}
};

const EXPL_ND_5 = {
  "w5k0": {c:"Redis là kho dữ liệu in-memory dạng key-value với nhiều kiểu dữ liệu (string, hash, list, set, sorted set, stream…), mỗi key có thể gắn TTL để tự hết hạn. Cache-aside và write-through là hai cách phối hợp cache với database; invalidation là làm cache hết hiệu lực khi dữ liệu gốc đổi, còn cache stampede là khi nhiều request cùng lúc cache miss và cùng dội xuống database.", e:"<ul><li>Chọn kiểu dữ liệu theo thao tác: hash cho object (đọc/sửa từng field), sorted set cho bảng xếp hạng và sliding window, set cho tập duy nhất, stream cho log sự kiện có consumer group. Redis chạy lệnh trên một luồng chính nên mỗi lệnh là nguyên tử, nhưng lệnh O(N) như <code>KEYS *</code> trên production sẽ chặn mọi client; dùng <code>SCAN</code>.</li> <li>Cache-aside (lazy loading): đọc cache, miss thì đọc DB rồi ghi cache kèm TTL; ghi thì cập nhật DB rồi xóa key. Write-through: ghi cache đồng thời với DB, cache luôn \"ấm\" nhưng tốn công cho dữ liệu ít đọc. Xóa key thường an toàn hơn ghi đè giá trị mới, vì hai request ghi song song có thể để lại giá trị cũ.</li> <li>Invalidation là phần khó: dữ liệu tổng hợp (báo cáo tháng) phụ thuộc nhiều bản ghi. Cách thực dụng là key có version (<code>report:{user}:{month}:v{n}</code>), tăng version khi có giao dịch mới; TTL luôn là lưới an toàn cuối.</li> <li>Stampede: key nóng hết hạn, hàng trăm request cùng tính lại. Phòng: single-flight (gom request trùng trong process), khóa ngắn bằng <code>SET NX PX</code> để chỉ một tiến trình tính lại, TTL có jitter để các key không hết hạn cùng lúc, hoặc làm mới sớm theo xác suất trước khi hết hạn.</li> <li>Cache là bản sao có thể mất: cấu hình <code>maxmemory-policy</code> (vd <code>allkeys-lru</code>) và chịu được Redis restart. Đừng dùng cùng một instance vừa làm cache dễ bị evict, vừa làm queue BullMQ (cần <code>noeviction</code>).</li></ul>", x:"Lab Expense Tracker cache báo cáo tháng. Phiên bản đầu đặt TTL cố định 1 giờ cho mọi key; đúng 9 giờ sáng thứ Hai, hàng nghìn key tạo từ đợt email tuần cùng hết hạn, CPU Postgres lên 100%. Sửa bằng key có version, TTL jitter và single-flight:<pre>const inflight = new Map&lt;string, Promise&lt;Report&gt;&gt;();\n\nasync function getMonthlyReport(userId: string, month: string) {\n  const v = (await redis.get(`report:ver:${userId}`)) ?? '0';\n  const key = `report:${userId}:${month}:v${v}`;\n  const hit = await redis.get(key);\n  if (hit) return JSON.parse(hit) as Report;\n\n  if (!inflight.has(key)) {                       // single-flight per process\n    inflight.set(key, (async () =&gt; {\n      const report = await buildReportFromDb(userId, month);\n      const ttl = 3600 + Math.floor(Math.random() * 600);   // jitter\n      await redis.set(key, JSON.stringify(report), 'EX', ttl);\n      return report;\n    })().finally(() =&gt; inflight.delete(key)));\n  }\n  return inflight.get(key)!;\n}\n\n// after a transaction is created/updated/deleted (after commit):\nawait redis.incr(`report:ver:${userId}`);         // old keys simply expire</pre>Tăng version thay vì xóa từng key tháng giúp không phải biết giao dịch ảnh hưởng tới những báo cáo nào. Việc tăng version phải chạy sau khi transaction DB commit, nếu không request khác có thể kịp cache lại dữ liệu cũ."},
  "w5k1": {c:"Distributed lock là khóa dùng chung giữa nhiều process hoặc máy để chỉ một bên được làm một việc tại một thời điểm, thường hiện thực bằng <code>SET key token NX PX ttl</code> trong Redis. Rate limit bằng Redis dùng bộ đếm nguyên tử dùng chung cho mọi instance. Giới hạn cốt lõi: lock dựa trên thời gian không thể đảm bảo tuyệt đối loại trừ lẫn nhau.", e:"<ul><li>Lấy lock: <code>SET lock:x &lt;token ngẫu nhiên&gt; NX PX 30000</code>. Nhả lock phải so token rồi mới xóa, gói trong Lua script để nguyên tử; <code>DEL</code> thẳng có thể xóa lock mà process khác vừa lấy sau khi lock của mình hết hạn.</li> <li>TTL là con dao hai lưỡi: không có TTL thì process chết giữ lock mãi; có TTL thì một GC pause dài, process bị treo hay mạng chậm khiến lock hết hạn trong khi process vẫn tưởng mình đang giữ, và hai bên cùng chạy đoạn găng.</li> <li>Redlock (thuật toán của antirez) lấy lock trên đa số N node Redis độc lập để chịu được một node chết. Martin Kleppmann (bài \"How to do distributed locking\", 2016) chỉ ra Redlock vẫn dựa trên giả định về thời gian (độ trôi đồng hồ, độ trễ có giới hạn) và không cung cấp fencing token; antirez đã phản biện. Kết luận thực dụng: lock Redis đủ cho mục đích hiệu năng (tránh làm trùng việc), không đủ cho tính đúng đắn.</li> <li>Khi cần đúng tuyệt đối: fencing token (số tăng dần, tài nguyên đích từ chối token cũ hơn), hoặc đẩy ràng buộc xuống database: unique constraint, <code>SELECT … FOR UPDATE</code>, advisory lock của Postgres, optimistic version.</li> <li>Package <code>redlock</code> trên npm: bản 5 vẫn ở beta từ 2022; nhiều team tự viết lock một node với Lua. Rate limit: <code>INCR</code> + <code>EXPIRE</code> (fixed window), sorted set (sliding window log) hoặc token bucket bằng Lua.</li></ul>", x:"Expense Tracker chạy job đồng bộ sao kê ngân hàng mỗi 15 phút trên 3 pod. Ban đầu dùng lock Redis TTL 60 giây để chỉ một pod đồng bộ mỗi tài khoản; một lần API ngân hàng chậm 90 giây, lock hết hạn, pod thứ hai vào đồng bộ cùng tài khoản và nhập trùng 40 giao dịch. Lock vẫn giữ để tránh làm thừa, nhưng tính đúng được đẩy xuống DB:<pre>const RELEASE = `if redis.call('get', KEYS[1]) == ARGV[1]\n  then return redis.call('del', KEYS[1]) else return 0 end`;\n\nasync function withLock&lt;T&gt;(key: string, ttlMs: number, fn: () =&gt; Promise&lt;T&gt;) {\n  const token = randomUUID();\n  const ok = await redis.set(key, token, 'PX', ttlMs, 'NX');\n  if (!ok) return null;                                   // someone else is syncing\n  try { return await fn(); }\n  finally { await redis.eval(RELEASE, 1, key, token); }   // only delete our own lock\n}\n\n// correctness: the DB rejects duplicates even if two workers overlap\n// CREATE UNIQUE INDEX ON transactions (bank_link_id, bank_ref);\n// INSERT ... ON CONFLICT (bank_link_id, bank_ref) DO NOTHING;</pre>Câu trả lời phỏng vấn: \"Lock Redis để tiết kiệm công, unique constraint để đảm bảo đúng.\" Nếu interviewer hỏi Redlock, nêu được lập luận về GC pause, độ trôi đồng hồ và fencing token của Kleppmann."},
  "w5k2": {c:"BullMQ là thư viện job queue cho Node.js chạy trên Redis: producer thêm job vào <code>Queue</code>, <code>Worker</code> lấy job ra xử lý, job lỗi được retry theo backoff. Job định kỳ được tạo bằng Job Scheduler. Vì job có thể chạy lại, handler phải idempotent.", e:"<ul><li>Retry: <code>attempts</code> &gt; 1 kèm <code>backoff: { type: 'exponential', delay, jitter }</code> (độ trễ <code>2^(attempts-1) × delay</code>, <code>jitter</code> từ 0 tới 1). Lỗi chắc chắn không sửa được bằng retry (dữ liệu sai, user đã xóa) thì ném <code>UnrecoverableError</code> để chuyển thẳng sang failed.</li> <li>Job được giao ít nhất một lần: worker crash hoặc lock của job hết hạn (job bị coi là stalled) thì job chạy lại. Vì vậy side effect phải idempotent: <code>jobId</code> cố định để không thêm trùng, ghi DB bằng upsert hoặc unique constraint, gửi email kèm khóa chống trùng. Cần chống thêm trùng trong một khoảng thời gian thì dùng option <code>deduplication</code>.</li> <li>Dead letter: BullMQ không có DLQ riêng; job hết lượt thử nằm ở tập failed. Giữ lại bằng <code>removeOnFail: { count }</code>, có alert, và có thể chuyển sang một queue riêng ở sự kiện <code>failed</code> để xử lý tay hoặc replay.</li> <li>Job định kỳ: <code>queue.upsertJobScheduler(id, { pattern | every, tz }, template)</code>. BullMQ v6 (phát hành 30/07/2026) đã gỡ hẳn API repeatable cũ (option <code>repeat</code> của <code>add</code>, <code>getRepeatableJobs</code>, <code>removeRepeatableByKey</code>); tài liệu cũ và nhiều bài blog vẫn dùng chúng. v6 cũng đổi <code>ioredis</code> thành optional peer dependency, phải cài riêng.</li> <li>Vận hành: Redis cho queue cần <code>maxmemory-policy noeviction</code>; ioredis dùng cho Worker cần <code>maxRetriesPerRequest: null</code>; đặt <code>concurrency</code> theo tài nguyên; tắt worker bằng <code>await worker.close()</code> khi nhận SIGTERM để job đang chạy kịp xong.</li></ul>", x:"Lab Expense Tracker có hai job: import CSV sao kê ở nền và email tóm tắt chi tiêu tối Chủ nhật. Sự cố đầu tiên: worker bị OOM kill giữa lúc import, job chạy lại từ đầu và nhân đôi 2.000 giao dịch. Sự cố thứ hai: sau khi nâng lên BullMQ v6, code <code>queue.add('weekly', {}, { repeat: … })</code> không còn được hỗ trợ. Bản sửa:<pre>import { Queue, Worker, UnrecoverableError } from 'bullmq';\nimport IORedis from 'ioredis';\nconst connection = new IORedis(process.env.REDIS_URL!, { maxRetriesPerRequest: null });\n\nconst jobs = new Queue('jobs', { connection });\nawait jobs.upsertJobScheduler('weekly-summary',\n  { pattern: '0 0 20 * * 0', tz: 'Asia/Ho_Chi_Minh' },      // Sunday 20:00\n  { name: 'weekly-summary', opts: { attempts: 5, backoff: { type: 'exponential', delay: 10_000, jitter: 0.5 } } });\n\nawait jobs.add('import-csv', { importId }, {\n  jobId: `import-${importId}`,                               // re-adding is a no-op\n  attempts: 3, backoff: { type: 'exponential', delay: 5_000 },\n  removeOnComplete: 1000, removeOnFail: { count: 5000 },\n});\n\nnew Worker('jobs', async (job) =&gt; {\n  if (job.name === 'import-csv') {\n    const imp = await getImport(job.data.importId);\n    if (!imp) throw new UnrecoverableError('import deleted');\n    await importRows(imp);   // INSERT ... ON CONFLICT (import_id, row_no) DO NOTHING\n  }\n}, { connection, concurrency: 4 });</pre>Mỗi dòng CSV có khóa (<code>import_id</code>, <code>row_no</code>), nên chạy lại bao nhiêu lần cũng không nhân đôi. Job failed được alert về Slack kèm nút replay trên trang admin."},
  "w5k3": {c:"Message broker là hệ thống trung gian chuyển message giữa các service. RabbitMQ là broker kiểu hàng đợi: message được route qua exchange vào queue, consumer ack thì message bị xóa. Kafka là log phân tán: message được append vào partition của topic, giữ lại theo thời gian, consumer tự quản lý offset và có thể đọc lại.", e:"<ul><li>RabbitMQ hợp cho task queue, routing linh hoạt (direct, topic, fanout, headers), độ trễ thấp, prefetch và ack từng message, retry với dead letter exchange. Từ RabbitMQ 4.0, classic queue mirroring bị gỡ; muốn chịu lỗi dùng quorum queue (Raft) hoặc stream.</li> <li>Kafka hợp cho luồng sự kiện khối lượng lớn, nhiều consumer độc lập cùng đọc một luồng, replay lịch sử, event sourcing, CDC. Kafka 4.0 chỉ còn chạy KRaft (bỏ ZooKeeper). Kafka 4.2 đưa share groups (\"Queues for Kafka\", KIP-932) lên production-ready, cho nhiều consumer cùng xử lý một partition với ack từng record.</li> <li>Thứ tự: Kafka chỉ đảm bảo thứ tự trong một partition; chọn key (vd <code>userId</code>) để mọi sự kiện của một user vào cùng partition. Consumer group: mỗi partition được giao cho đúng một consumer trong group, nên số consumer hữu ích tối đa bằng số partition. RabbitMQ giữ thứ tự trong một queue với một consumer; nhiều consumer hoặc requeue là mất thứ tự.</li> <li>Ngữ nghĩa giao nhận: at-most-once (ack/commit trước khi xử lý), at-least-once (xử lý xong mới ack/commit, mặc định nên dùng, chấp nhận trùng), exactly-once của Kafka (idempotent producer + transaction + <code>read_committed</code>) chỉ đúng trong phạm vi đọc-ghi Kafka; side effect ra ngoài (DB, email) vẫn cần idempotency ở ứng dụng.</li> <li>Client Node: <code>amqplib</code> cho RabbitMQ; với Kafka, KafkaJS không còn phát hành từ 2023, Confluent có client chính thức <code>@confluentinc/kafka-javascript</code> (dựa trên librdkafka).</li></ul>", x:"Expense Tracker có hai nhu cầu khác nhau: gửi push/email khi có giao dịch (task, cần retry từng message) và dòng sự kiện <code>transaction.*</code> cho service báo cáo và chống gian lận đọc độc lập, có thể replay khi sửa bug tính toán. Team ban đầu dùng một queue RabbitMQ cho cả hai; khi thêm service thứ hai, hai service \"tranh\" message của nhau vì cùng consume một queue. Thiết kế lại:<pre>// Kafka: event stream, keyed by userId to keep per-user order\nawait producer.send({\n  topic: 'transaction-events',\n  messages: [{ key: userId, value: JSON.stringify(event),\n               headers: { 'event-type': 'transaction.created', 'event-version': '2' } }],\n});\n// reporting-service and fraud-service use different consumer groups:\n// each group receives every event; within a group, partitions are split.\n\n// RabbitMQ (or BullMQ): notification tasks with retry + dead letter\nawait ch.assertQueue('notify', { durable: true, arguments: {\n  'x-queue-type': 'quorum', 'x-dead-letter-exchange': 'notify.dlx' } });</pre>Khi phỏng vấn, đừng nói \"Kafka nhanh hơn\"; hãy nói theo mô hình: log có thể replay, nhiều consumer group, thứ tự theo partition, so với hàng đợi task có routing và ack từng message."},
  "w5k4": {c:"WebSocket là kết nối hai chiều, lâu dài trên một TCP connection, bắt đầu bằng HTTP Upgrade. Server-Sent Events (SSE) là luồng một chiều từ server xuống client qua HTTP thường (<code>text/event-stream</code>). Socket.IO là thư viện xây trên WebSocket (có fallback HTTP long-polling), thêm room, ack, tự kết nối lại; khi chạy nhiều instance cần adapter (Redis) để broadcast giữa các node.", e:"<ul><li>Chọn: chỉ cần server đẩy xuống (số dư, tiến độ import) thì SSE đơn giản, đi qua proxy và HTTP/2 tốt, trình duyệt tự reconnect với <code>Last-Event-ID</code>. Cần hai chiều tần suất cao (chat, cộng tác) thì WebSocket. Socket.IO tiện nhưng có giao thức riêng: client phải là client Socket.IO, không phải WebSocket thuần.</li> <li>Nhiều instance: mỗi socket chỉ nằm trên một node, nên <code>io.to(room).emit()</code> trên node A không tới được socket ở node B nếu không có adapter. <code>@socket.io/redis-adapter</code> dùng Redis Pub/Sub; tài liệu khuyên dùng <code>createShardedAdapter</code> (sharded Pub/Sub, Redis 7.0+) cho dự án mới. <code>@socket.io/redis-streams-adapter</code> dùng Redis Streams, chịu được Redis mất kết nối tạm thời và hỗ trợ connection state recovery, điều mà adapter Pub/Sub không hỗ trợ.</li> <li>Sticky session vẫn bắt buộc khi có long-polling (nếu không sẽ lỗi HTTP 400); nếu chỉ cho phép transport <code>websocket</code> thì không cần.</li> <li>Xác thực ở handshake (<code>socket.handshake.auth.token</code> trong middleware <code>io.use</code>), không tin room client tự xin; đưa socket vào room <code>user:{id}</code> ở server. Access token hết hạn trong lúc kết nối vẫn mở là chuyện phải tính.</li> <li>Mobile: app vào background thì hệ điều hành cắt kết nối; realtime chỉ dành cho lúc app mở, còn lại dùng push. Khi reconnect, client nên gọi API lấy trạng thái mới nhất thay vì trông vào việc không mất message.</li></ul>", x:"Expense Tracker đẩy số dư mới xuống app sau mỗi giao dịch. Chạy một pod thì ổn; scale lên 3 pod, khoảng 2/3 lần người dùng không thấy số dư cập nhật, vì job BullMQ import CSV phát sự kiện trên pod không giữ socket của user đó. Thêm Redis adapter, xác thực ở handshake và room theo user:<pre>import { Server } from 'socket.io';\nimport { createClient } from 'redis';\nimport { createShardedAdapter } from '@socket.io/redis-adapter';\n\nconst pub = createClient({ url: process.env.REDIS_URL });\nconst sub = pub.duplicate();\nawait Promise.all([pub.connect(), sub.connect()]);\n\nconst io = new Server(httpServer, {\n  adapter: createShardedAdapter(pub, sub),\n  transports: ['websocket'],              // mobile clients only: no sticky sessions needed\n});\nio.use(async (socket, next) =&gt; {\n  try { socket.data.userId = await verifyAccess(socket.handshake.auth.token); next(); }\n  catch { next(new Error('unauthorized')); }\n});\nio.on('connection', (s) =&gt; s.join(`user:${s.data.userId}`));\n\n// anywhere (API pod or worker with the same adapter):\nio.to(`user:${userId}`).emit('balance.updated', { walletId, balance: balance.toString() });</pre>Worker không có HTTP server thì dùng <code>@socket.io/redis-emitter</code> để phát qua Redis. App khi reconnect gọi <code>GET /wallets</code> để đồng bộ lại, vì adapter Pub/Sub không đảm bảo giao message bị lỡ."},
  "w5k5": {c:"Microservices chia hệ thống thành nhiều service triển khai độc lập, mỗi service sở hữu dữ liệu riêng và giao tiếp qua mạng. Modular monolith là một ứng dụng triển khai một khối nhưng chia module có ranh giới rõ ràng bên trong. Giao tiếp giữa các phần có thể đồng bộ (REST, gRPC: gọi và chờ kết quả) hoặc bất đồng bộ (phát event qua broker).", e:"<ul><li>Microservices giải quyết vấn đề tổ chức nhiều hơn kỹ thuật: nhiều team triển khai độc lập, scale riêng phần nóng, cô lập lỗi, dùng công nghệ khác nhau. Cái giá: lỗi mạng, transaction phân tán, nhất quán cuối cùng, quan sát và debug khó, hạ tầng CI/CD phức tạp.</li> <li>Team nhỏ, domain còn đang thay đổi thì bắt đầu bằng modular monolith: mỗi module có API công khai, không truy vấn bảng của module khác, giao tiếp qua interface hoặc event nội bộ. Khi cần tách, ranh giới đã sẵn. \"Distributed monolith\" (các service gọi nhau dày đặc, deploy phải đi cùng nhau, dùng chung DB) là kết cục tệ nhất.</li> <li>Đồng bộ: dễ hiểu, có kết quả ngay, nhưng tạo phụ thuộc thời gian chạy; độ khả dụng nhân với nhau theo chuỗi gọi (3 service 99,9% nối tiếp còn khoảng 99,7%). Luôn đặt timeout, retry có giới hạn, circuit breaker.</li> <li>REST/JSON phổ biến, dễ debug; gRPC (HTTP/2 + Protobuf) có contract chặt, nhanh, hỗ trợ streaming, hợp cho gọi nội bộ, kém thân thiện với trình duyệt.</li> <li>Bất đồng bộ: giảm coupling, chịu được service nhận tạm chết, nhưng nhất quán cuối cùng, cần idempotency, khó theo dõi luồng; dùng correlation id và distributed tracing (OpenTelemetry).</li></ul>", x:"Có đề xuất tách Expense Tracker API thành 5 service (auth, wallet, transaction, report, notification) khi team chỉ có 3 backend dev. Prototype cho thấy tạo một giao dịch phải gọi đồng bộ wallet → transaction → report, p99 tăng gấp ba và một lần report-service deploy lỗi làm luôn cả việc thêm giao dịch thất bại. Quyết định: modular monolith, ranh giới được lint kiểm tra, chỉ notification tách ra worker riêng vì tải và nhịp deploy khác:<pre>src/modules/\n  wallet/        index.ts (public API)  internal/...\n  transaction/   index.ts               internal/...\n  report/        index.ts               internal/...   // listens to events, never queries tx tables\n\n// .eslintrc: forbid deep imports across modules\n'no-restricted-imports': ['error', { patterns: ['@/modules/*/internal/*'] }]\n\n// in-process event now; same contract can move to a broker later\nevents.emit('transaction.created', { id, userId, walletId, amount, occurredAt });</pre>Câu trả lời phỏng vấn: tách service khi có lý do đo được (team, scale, cô lập lỗi), không phải vì \"microservices hiện đại hơn\"."},
  "w5k6": {c:"Các pattern hệ phân tán: API gateway là cửa vào chung cho client; saga chia một giao dịch nghiệp vụ trải qua nhiều service thành chuỗi bước cục bộ, mỗi bước có hành động bù; outbox ghi event vào DB trong cùng transaction với dữ liệu rồi mới phát ra broker; circuit breaker ngắt gọi tới dependency đang lỗi; retry có jitter thêm ngẫu nhiên vào thời gian chờ giữa các lần thử.", e:"<ul><li>API gateway: routing, xác thực, rate limit, TLS, gom response (BFF cho mobile). Đừng nhét logic nghiệp vụ vào gateway; nó sẽ thành monolith mới khó test.</li> <li>Saga: choreography (mỗi service nghe event rồi phát event tiếp, ít phụ thuộc nhưng khó nhìn toàn cảnh) hoặc orchestration (một điều phối viên gọi từng bước, dễ theo dõi). Hành động bù không phải rollback: tiền đã trừ thì bù bằng giao dịch hoàn tiền, email đã gửi thì không lấy lại được.</li> <li>Outbox giải quyết dual write: \"ghi DB rồi publish Kafka\" có thể ghi DB thành công nhưng publish thất bại (hoặc ngược lại). Ghi event vào bảng <code>outbox</code> trong cùng transaction; relay đọc bảng (polling với <code>FOR UPDATE SKIP LOCKED</code>, hoặc CDC như Debezium) và publish, at-least-once nên consumer phải idempotent.</li> <li>Circuit breaker (closed → open → half-open): khi tỷ lệ lỗi vượt ngưỡng thì fail nhanh, không chiếm thread/connection chờ timeout; sau một khoảng cho vài request thử. Trong Node có <code>opossum</code>. Kết hợp với timeout và fallback.</li> <li>Retry: chỉ retry lỗi tạm thời và thao tác idempotent, giới hạn số lần, exponential backoff + jitter (vd full jitter: chờ ngẫu nhiên từ 0 tới mức trần) để hàng nghìn client không retry đồng loạt. Retry ở nhiều tầng chồng nhau sẽ nhân số request lên theo cấp số.</li></ul>", x:"Expense Tracker cần phát event <code>transaction.created</code> cho service báo cáo. Bản đầu publish ngay sau <code>COMMIT</code>; khi broker bảo trì 2 phút, khoảng 300 giao dịch không bao giờ có trong báo cáo. Chuyển sang outbox:<pre>// 1) same transaction as the business write\nawait db.transaction(async (tx) =&gt; {\n  const t = await tx.insertTransaction(input);\n  await tx.query(\n    `INSERT INTO outbox (id, aggregate_id, type, payload) VALUES ($1, $2, $3, $4)`,\n    [randomUUID(), t.id, 'transaction.created', JSON.stringify(toEventV2(t))]);\n});\n\n// 2) relay (several instances can run safely)\nasync function relayOnce() {\n  await db.transaction(async (tx) =&gt; {\n    const { rows } = await tx.query(\n      `SELECT * FROM outbox WHERE published_at IS NULL\n       ORDER BY created_at LIMIT 100 FOR UPDATE SKIP LOCKED`);\n    for (const e of rows) {\n      await breaker.fire(() =&gt; publish(e.type, e.aggregate_id, e.payload, { eventId: e.id }));\n      await tx.query('UPDATE outbox SET published_at = now() WHERE id = $1', [e.id]);\n    }\n  });\n}</pre><code>breaker</code> là một circuit breaker <code>opossum</code> bọc hàm publish; khi broker chết, relay ngừng nhanh và thử lại theo backoff có jitter. Consumer bỏ qua <code>eventId</code> đã xử lý. Không có sự kiện nào bị mất, chỉ bị trễ."},
  "w5k7": {c:"Idempotency là tính chất thực hiện một thao tác nhiều lần cho cùng kết quả như một lần. Trong hệ phân tán, message hay request bị gửi lại là chuyện bình thường (retry, at-least-once delivery, rebalance), nên \"exactly-once\" thực tế là at-least-once delivery cộng với xử lý idempotent ở ứng dụng (effectively-once).", e:"<ul><li>Nguồn trùng lặp: client retry khi timeout, broker giao lại khi consumer chưa ack/commit, consumer crash sau khi xử lý nhưng trước khi commit offset, outbox relay publish lại, webhook bên thứ ba gửi lại.</li> <li>Kỹ thuật: (1) thao tác vốn idempotent (<code>SET status = 'paid'</code>, upsert theo khóa tự nhiên); (2) bảng <code>processed_messages</code> với unique <code>(consumer, message_id)</code>, ghi trong cùng transaction với side effect; (3) idempotency key cho API, lưu kèm response để trả lại; (4) điều kiện theo version/trạng thái (<code>UPDATE … WHERE status = 'pending'</code>).</li> <li>Bẫy: kiểm tra \"đã xử lý chưa\" rồi mới xử lý, ở hai bước tách rời, sẽ có race khi hai consumer nhận cùng message; phải dựa vào ràng buộc unique hoặc khóa nguyên tử. Lưu dấu đã xử lý trong Redis còn side effect ghi Postgres thì hai thứ không cùng transaction.</li> <li>Side effect ra ngoài (gửi email, gọi API thanh toán) không nằm trong transaction DB: truyền idempotency key sang bên thứ ba nếu họ hỗ trợ, hoặc chấp nhận \"có thể gửi trùng\" và ghi trạng thái trước/sau.</li> <li>Interviewer hay hỏi: \"Kafka có exactly-once rồi sao còn cần?\" Exactly-once của Kafka chỉ bao trọn khi cả input và output đều là Kafka trong một transaction; ghi ra Postgres hay gửi push thì vẫn phải tự dedupe.</li></ul>", x:"Service báo cáo của Expense Tracker nghe <code>transaction.created</code> và cộng dồn vào bảng <code>monthly_totals</code>. Sau một lần consumer group rebalance khi deploy, vài trăm event bị giao lại và tổng chi tháng 9 của một số người dùng tăng gấp đôi. Sửa bằng cách ghi dấu đã xử lý trong cùng transaction với phép cộng:<pre>async function onTransactionCreated(evt: TxCreatedV2) {\n  await db.transaction(async (tx) =&gt; {\n    const first = await tx.query(\n      `INSERT INTO processed_events (consumer, event_id) VALUES ('report', $1)\n       ON CONFLICT DO NOTHING`, [evt.eventId]);\n    if (first.rowCount === 0) return;                 // duplicate: already applied\n\n    await tx.query(\n      `INSERT INTO monthly_totals (user_id, month, category_id, total)\n       VALUES ($1, $2, $3, $4)\n       ON CONFLICT (user_id, month, category_id)\n       DO UPDATE SET total = monthly_totals.total + EXCLUDED.total`,\n      [evt.userId, evt.month, evt.categoryId, evt.amount]);\n  });\n  // commit the Kafka offset only after the DB transaction has committed\n}</pre>Phép cộng dồn vốn không idempotent, nên phải có bảng dedupe. Một cách khác là tính lại tổng của tháng từ bảng gốc mỗi lần, vốn idempotent sẵn nhưng tốn hơn. Bảng <code>processed_events</code> được dọn định kỳ những dòng cũ hơn thời gian retention của topic."},
  "w5k8": {c:"Push notification gửi tới thiết bị qua dịch vụ của nền tảng: FCM (Firebase Cloud Messaging) cho Android và có thể cho cả iOS, APNs (Apple Push Notification service) cho iOS. Email giao dịch gửi qua nhà cung cấp SMTP/API. Webhook là việc server gọi HTTP tới URL của bên khác khi có sự kiện; chữ ký HMAC giúp bên nhận xác minh nguồn gốc và tính toàn vẹn.", e:"<ul><li>FCM: dùng HTTP v1 API (qua <code>firebase-admin</code>, <code>messaging().send()</code> hoặc <code>sendEachForMulticast()</code>); legacy API và batch send cũ đã bị tắt từ 2024. Token chết (<code>messaging/registration-token-not-registered</code>) phải xóa khỏi DB, nếu không danh sách phình ra và tỷ lệ lỗi tăng.</li> <li>APNs: HTTP/2, xác thực bằng token (khóa <code>.p8</code>, JWT ES256) hoặc certificate. Push không đảm bảo tới nơi và có thể bị hệ điều hành gộp hoặc trì hoãn; không dùng push làm kênh dữ liệu duy nhất, và không đặt dữ liệu nhạy cảm (số tiền, số dư) trên màn hình khóa nếu user chưa đồng ý.</li> <li>Email: luôn gửi qua queue, có retry; cấu hình SPF, DKIM, DMARC cho domain. Gmail và Yahoo yêu cầu bulk sender có xác thực, unsubscribe một chạm (RFC 8058) và tỷ lệ spam thấp. Tách luồng email giao dịch và email marketing.</li> <li>Webhook gửi đi: ký HMAC-SHA256 trên <code>id.timestamp.rawBody</code>, gửi kèm id và timestamp (theo mẫu Standard Webhooks); retry với backoff trong nhiều giờ; bên nhận trả 2xx nhanh rồi xử lý bất đồng bộ.</li> <li>Webhook nhận vào: xác minh trên raw body (không phải JSON đã parse rồi stringify lại), so sánh bằng <code>crypto.timingSafeEqual</code>, từ chối timestamp quá cũ (chống replay), dedupe theo id. URL webhook do user nhập là bề mặt SSRF.</li></ul>", x:"Expense Tracker nhận webhook \"có giao dịch mới\" từ đối tác tổng hợp ngân hàng. Bản đầu verify chữ ký trên <code>JSON.stringify(req.body)</code>: thỉnh thoảng sai chữ ký do khác thứ tự key và khoảng trắng, nên dev \"tạm\" bỏ verify, và endpoint mở cho bất kỳ ai giả giao dịch. Sửa:<pre>app.post('/webhooks/bank', express.raw({ type: 'application/json', limit: '256kb' }),\n  async (req, res) =&gt; {\n    const id = req.get('webhook-id')!, ts = req.get('webhook-timestamp')!;\n    if (Math.abs(Date.now() / 1000 - Number(ts)) &gt; 300) return res.sendStatus(400); // replay\n    const expected = createHmac('sha256', BANK_SECRET)\n      .update(`${id}.${ts}.`).update(req.body).digest();     // req.body is a Buffer\n    const given = Buffer.from((req.get('webhook-signature') ?? '').replace(/^v1,/, ''), 'base64');\n    if (given.length !== expected.length || !timingSafeEqual(given, expected))\n      return res.sendStatus(401);\n    await jobs.add('bank-event', JSON.parse(req.body.toString()), { jobId: `bank-${id}` }); // dedupe\n    res.sendStatus(204);                                        // ack fast, process async\n  });</pre>Job xử lý tạo giao dịch rồi đẩy push qua FCM; token trả về lỗi not-registered bị xóa ngay trong job. Nội dung push chỉ ghi \"Có giao dịch mới\", số tiền chỉ hiện trong app."},
  "w5k9": {c:"Event-driven architecture là kiến trúc trong đó các service giao tiếp bằng cách phát và nghe sự kiện (sự thật đã xảy ra, như <code>transaction.created</code>). Schema của event là hợp đồng giữa producer và nhiều consumer, nên cần quy tắc versioning để thay đổi mà không làm vỡ consumer. NestJS microservices là module <code>@nestjs/microservices</code> cung cấp các transport (TCP, Redis, NATS, MQTT, RabbitMQ, Kafka, gRPC) và decorator để viết handler.", e:"<ul><li>Event đặt tên ở thì quá khứ, mang đủ dữ liệu cho consumer phổ biến (event-carried state) hoặc chỉ id (consumer gọi lại API, gây coupling và tải). Có envelope chuẩn: <code>id</code>, <code>type</code>, <code>version</code>, <code>occurredAt</code>, <code>source</code>, <code>correlationId</code>; CloudEvents là một chuẩn tham khảo cho envelope.</li> <li>Thay đổi tương thích ngược: thêm field optional, consumer bỏ qua field lạ. Thay đổi phá vỡ (đổi tên, đổi kiểu, đổi nghĩa) thì tạo version mới, phát song song v1 và v2 trong giai đoạn chuyển, rồi gỡ v1 khi mọi consumer đã chuyển. Kafka thường dùng schema registry (Avro, Protobuf, JSON Schema) để chặn schema không tương thích ngay khi publish.</li> <li>Validate event ở consumer (Zod, JSON Schema); event bị hỏng đưa vào dead letter thay vì chặn cả partition (poison message).</li> <li>NestJS: <code>@MessagePattern</code> cho request-response (client gọi <code>send()</code>, observable lạnh, phải subscribe hoặc <code>firstValueFrom</code>), <code>@EventPattern</code> cho event (client gọi <code>emit()</code>, không chờ kết quả). Có hybrid app: một ứng dụng vừa phục vụ HTTP vừa nghe broker qua <code>connectMicroservice()</code>.</li> <li>Bẫy: abstraction của NestJS che bớt ngữ nghĩa của broker (ack, retry, offset commit); phải hiểu transport bên dưới làm gì khi handler ném lỗi.</li></ul>", x:"Expense Tracker đổi <code>amount</code> trong <code>transaction.created</code> từ số thập phân (<code>12.5</code>, đơn vị nghìn đồng) sang số nguyên đơn vị đồng dạng string (<code>\"12500\"</code>). Producer deploy trước, và service báo cáo cũ hiểu <code>\"12500\"</code> là 12.500 nghìn: báo cáo tháng của mọi người tăng 1000 lần trong 20 phút. Làm lại theo versioning:<pre>// producer: publish v1 and v2 side by side during migration\nconst base = { id: randomUUID(), occurredAt: t.occurredAt, source: 'tx-service', correlationId };\nawait outbox.add({ ...base, type: 'transaction.created', version: 1, data: { ...t, amount: t.amount / 1000 } });\nawait outbox.add({ ...base, id: randomUUID(), type: 'transaction.created', version: 2,\n                   data: { ...t, amount: t.amount.toString(), currency: 'VND' } });\n\n// consumer (NestJS, Kafka transport): only handle the version it understands\n@Controller()\nexport class ReportConsumer {\n  @EventPattern('transaction-events')\n  async handle(@Payload() evt: unknown) {\n    const parsed = TxCreatedV2.safeParse(evt);   // zod schema of the v2 envelope\n    if (!parsed.success) return;                 // other versions or unknown types: ignore\n    await this.reports.apply(parsed.data);       // idempotent by event id\n  }\n}</pre>Khi metric cho thấy không còn consumer nào đọc v1, producer ngừng phát v1. Từ đó, quy ước chung: mọi thay đổi phá vỡ schema đều phải tăng <code>version</code>, và CI chạy contract test giữa producer với từng consumer."}
};

const EXPL_ND_67 = {
  "w6k0": {c:"Profiling là đo xem CPU thực sự tiêu thời gian vào hàm nào, thay vì đoán. V8 có sampling profiler: cứ mỗi khoảng ngắn (mặc định khoảng 1ms) nó chụp call stack, rồi gộp lại thành profile; flame graph là cách vẽ profile đó, trục ngang là tỉ lệ thời gian, trục dọc là độ sâu call stack.", e:"<ul><li>Hai cách lấy profile: <code>node --cpu-prof dist/main.js</code> ghi file <code>.cpuprofile</code> khi process thoát (chỉnh bằng <code>--cpu-prof-dir</code>, <code>--cpu-prof-name</code>, <code>--cpu-prof-interval</code>); hoặc <code>node --inspect</code> rồi mở <code>chrome://inspect</code>, bấm Record ở tab Performance/Profiler trong lúc bắn tải. File <code>.cpuprofile</code> mở được bằng Chrome DevTools hoặc speedscope.</li> <li>Bẫy hay gặp: process bị kill bằng tín hiệu mà không có handler (Ctrl+C, <code>kill</code>) thì <code>--cpu-prof</code> <b>không ghi file</b>. App cần bắt <code>SIGINT</code>/<code>SIGTERM</code> rồi gọi <code>process.exit()</code>, việc này đằng nào cũng phải làm cho graceful shutdown.</li> <li>Đọc flame graph: tìm khối <b>rộng</b> ở gần đỉnh (self time lớn), không phải khối cao. Khối <code>(garbage collector)</code> rộng nghĩa là vấn đề nằm ở cấp phát bộ nhớ, không phải ở thuật toán. Khối <code>(idle)</code> lớn mà latency vẫn cao thì bottleneck nằm ở I/O (DB, pool cạn), CPU profile không giúp được, phải xem trace.</li> <li>Profile trên build production (<code>NODE_ENV=production</code>, code đã build), với tải gần giống thật; profile ở dev với ts-node/hot reload cho kết quả sai lệch.</li> <li>Không mở <code>--inspect=0.0.0.0:9229</code> trên production: ai kết nối được vào cổng đó là chạy được code tùy ý trong process. Nếu cần, bind localhost và vào qua <code>kubectl port-forward</code>, hoặc dùng <code>--cpu-prof</code> trên một pod tách khỏi load balancer.</li></ul> Interviewer hay hỏi: \"API chậm, bạn bắt đầu từ đâu?\" Câu trả lời tốt: xem trace để biết chậm ở CPU hay chờ I/O, rồi mới chọn công cụ.", x:"<code>GET /reports/monthly</code> của Expense Tracker có p95 1,8s với user có khoảng 5.000 giao dịch/tháng; trace cho thấy query Postgres chỉ mất 60ms, phần còn lại là CPU. Chạy profile dưới tải k6:<pre>node --cpu-prof --cpu-prof-dir=./prof dist/main.js\n# bắn tải 30s, rồi gửi SIGTERM; app có handler gọi process.exit(0) nên file được ghi\n</pre>Flame graph có một khối rộng chiếm khoảng 55% CPU trong constructor <code>Intl.NumberFormat</code>: hàm format tiền tạo formatter mới cho từng dòng.<pre>// trước: tạo formatter cho mỗi giao dịch\nconst fmt = (v) =&gt; new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(v);\n// sau: tạo một lần, dùng lại\nconst vnd = new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' });\nconst fmt = (v) =&gt; vnd.format(v);</pre>p95 giảm xuống khoảng 250ms. Bài học ghi vào PR: đo trước, sửa đúng một chỗ, đo lại với cùng kịch bản tải."},
  "w6k1": {c:"Memory leak trong Node là khi object không còn cần nhưng vẫn còn đường tham chiếu từ GC root (biến global, module scope, closure đang sống, listener đã đăng ký), nên GC không thu hồi được và heap tăng dần tới khi process bị OOM. V8 dùng GC thế hệ: young generation (scavenge, nhanh, thường xuyên) và old generation (mark-sweep-compact, chạy incremental/concurrent).", e:"<ul><li>Bốn nguồn leak kinh điển: cache dạng <code>Map</code> ở module scope không có giới hạn/TTL; listener đăng ký mỗi request mà không gỡ (<code>emitter.on</code> trong handler, cảnh báo <code>MaxListenersExceededWarning</code> là dấu hiệu); closure giữ tham chiếu tới object lớn (ví dụ <code>req</code>) trong timer hoặc callback sống lâu; <code>setInterval</code> không <code>clearInterval</code>.</li> <li>Chẩn đoán bằng heap snapshot: chụp 3 lần (sau warm-up, sau N request, sau 2N request), dùng chế độ Comparison trong DevTools để tìm constructor có số lượng tăng đều, rồi xem <b>Retainers</b> để biết ai đang giữ nó. Cách chụp: <code>v8.writeHeapSnapshot()</code>, <code>--heapsnapshot-signal=SIGUSR2</code>, hoặc <code>--heapsnapshot-near-heap-limit=1</code> để tự chụp khi heap sắp chạm giới hạn.</li> <li>Lưu ý: chụp snapshot làm process dừng (stop-the-world) và cần thêm bộ nhớ cỡ bằng heap hiện tại; làm trên pod đã rút khỏi load balancer. <code>--heap-prof</code> là sampling heap profiler, nhẹ hơn, cho biết chỗ cấp phát nhiều.</li> <li><code>--max-old-space-size</code> (MB) đặt giới hạn old space. Trong container nên đặt rõ, khoảng 70–80% memory limit, chừa chỗ cho buffer, stack và native memory; các bản Node mới (có trong Node 24) có thêm <code>--max-old-space-size-percentage</code>. Tăng giới hạn chỉ làm leak chết chậm hơn, không sửa được leak.</li> <li>Phân biệt leak với tải cao: heap tăng rồi giảm sau GC là bình thường; leak là đường \"heap sau mỗi lần GC\" đi lên mãi. RSS cao nhưng heap ổn thì nghi native memory hoặc <code>Buffer</code> (external memory).</li></ul> WeakMap/WeakRef giải quyết được một số trường hợp, nhưng cách chắc chắn nhất là cache có giới hạn (LRU + TTL) và gỡ listener trong <code>finally</code>.", x:"Pod API của Expense Tracker bị OOMKilled khoảng mỗi 18 giờ, memory tăng tuyến tính theo số request. Bật <code>--heapsnapshot-near-heap-limit=1</code> rồi so hai snapshot: hàng chục nghìn object <code>ExchangeRate</code> được giữ bởi một <code>Map</code> trong <code>fx.service.ts</code>.<pre>// trước: key gồm cả timestamp đến mili giây, nên mỗi request tạo một key mới và Map không bao giờ nhỏ lại\nconst cache = new Map();\ncache.set(`${from}-${to}-${Date.now()}`, rate);\n\n// sau: key theo ngày, giới hạn số phần tử và TTL\nimport { LRUCache } from 'lru-cache';\nconst cache = new LRUCache({ max: 500, ttl: 60 * 60 * 1000 });\ncache.set(`${from}-${to}-${day}`, rate);</pre>Thêm metric <code>nodejs_heap_size_used_bytes</code> (từ <code>prom-client</code>) vào dashboard và alert khi heap sau GC tăng liên tục 6 giờ, để lần sau phát hiện trước khi OOM."},
  "w6k2": {c:"Tối ưu backend Node chủ yếu xoay quanh một nguyên tắc: event loop chỉ có một luồng chạy JavaScript, nên mọi việc CPU nặng hoặc đồng bộ sẽ chặn tất cả request khác. Phần còn lại là giảm chi phí I/O: stream thay vì đọc hết vào RAM, gom việc thành batch, dùng lại kết nối qua pool và keep-alive.", e:"<ul><li>Chặn event loop: <code>JSON.parse</code>/<code>JSON.stringify</code> payload vài chục MB, regex có backtracking thảm họa, <code>bcrypt.hashSync</code>, <code>fs.readFileSync</code> trong handler, vòng lặp lớn tính báo cáo. Đo bằng <code>perf_hooks.monitorEventLoopDelay()</code> hoặc <code>performance.eventLoopUtilization()</code>. Cách xử lý: chia nhỏ việc, đẩy sang <code>worker_threads</code> (Piscina) hoặc sang job BullMQ.</li> <li>Stream: export CSV 200.000 dòng thì dùng cursor DB + <code>stream.pipeline()</code> để có backpressure, RAM giữ phẳng; đọc hết vào mảng rồi <code>res.send</code> làm heap phình và GC dài.</li> <li>Batch: N+1 query (mỗi giao dịch một query lấy danh mục) thay bằng một query <code>WHERE id = ANY($1)</code> hoặc DataLoader; insert hàng loạt thì dùng multi-row insert hoặc <code>COPY</code>.</li> <li>Connection pool: <code>pg.Pool</code> mặc định <code>max: 10</code>. Tổng kết nối = số pod × số process × max phải nhỏ hơn <code>max_connections</code> của Postgres; nhiều pod thì cân nhắc PgBouncer. Pool cạn biểu hiện là latency cao mà CPU thấp.</li> <li>HTTP client: <code>fetch</code> có sẵn của Node dựng trên undici và dùng lại kết nối. Với service gọi một upstream rất nhiều (tỉ giá, push gateway), tạo <code>Agent</code>/<code>Pool</code> của undici với số <code>connections</code> phù hợp và timeout rõ ràng; không có timeout thì một upstream chậm sẽ giữ request tới mức cạn bộ nhớ.</li></ul> Thứ tự đúng: đo (trace, profile) → sửa bottleneck lớn nhất → đo lại. Tối ưu micro (thay <code>forEach</code> bằng <code>for</code>) gần như không bao giờ là câu trả lời.", x:"Tính năng import sao kê CSV của Expense Tracker: file 30MB làm p99 của mọi endpoint khác vọt lên 4s trong lúc import, vì handler đọc cả file rồi parse đồng bộ. Sửa thành stream, ghi theo lô 500 dòng:<pre>import { pipeline } from 'node:stream/promises';\nimport { parse } from 'csv-parse';\n\nawait pipeline(\n  file.stream,                       // stream từ multipart, không buffer cả file\n  parse({ columns: true }),\n  async function* (rows) {\n    let batch = [];\n    for await (const row of rows) {\n      batch.push(toTransaction(row));\n      if (batch.length === 500) { await repo.insertMany(batch); batch = []; }\n    }\n    if (batch.length) await repo.insertMany(batch);\n  },\n);</pre>Event loop delay p99 trong lúc import giảm từ khoảng 900ms xuống dưới 30ms, RSS ổn định quanh 180MB. Sau đó chuyển hẳn việc import sang job BullMQ để API chỉ nhận file và trả 202."},
  "w6k3": {c:"Load test là bắn tải có kiểm soát vào hệ thống để đo throughput (request/giây xử lý được) và phân phối latency, nhất là p95/p99 (95%/99% request nhanh hơn mức này), rồi tìm điểm bão hòa. k6 viết kịch bản bằng JavaScript (từ k6 1.0 chạy thẳng được file <code>.ts</code>); autocannon là công cụ Node nhẹ để benchmark nhanh một endpoint.", e:"<ul><li>Vì sao không dùng trung bình: trung bình che mất đuôi. Một trang mobile gọi 5 API thì xác suất người dùng gặp ít nhất một request chậm hơn p99 là khoảng 5%, nên p99 ảnh hưởng tới nhiều người hơn ta nghĩ.</li> <li>Open vs closed model: closed model (N virtual user lặp lại) tự giảm tải khi server chậm, nên che mất vấn đề (coordinated omission). Muốn đo đúng \"chịu được 500 req/s không\" thì dùng executor <code>constant-arrival-rate</code> hoặc <code>ramping-arrival-rate</code> của k6.</li> <li>Các loại test: smoke (tải nhỏ, kiểm tra kịch bản), load (tải mong đợi), stress (tăng dần tới khi hỏng), soak (tải vừa trong nhiều giờ để lộ leak), spike (tăng đột ngột).</li> <li><code>thresholds</code> trong k6 biến kết quả thành pass/fail (exit code khác 0), nên chạy được trên CI làm cổng chặn hồi quy hiệu năng.</li> <li>Bẫy: chạy load generator trên cùng máy với API; test với DB rỗng; mọi VU dùng cùng một user nên chỉ đo được cache; quên warm-up. Ghi lại môi trường (số pod, CPU limit, kích thước DB) cùng với kết quả, không thì số liệu không so sánh được.</li></ul> autocannon hợp để so nhanh hai cách viết một handler trên máy local (<code>npx autocannon -c 50 -d 20 http://localhost:3000/health</code>); k6 hợp cho kịch bản nhiều bước, có login, có dữ liệu ngẫu nhiên.", x:"Kịch bản k6 cho luồng chính của app: lấy danh sách giao dịch và tạo giao dịch, giữ tốc độ 200 req/s trong 5 phút trên staging (DB đã seed 2 triệu giao dịch):<pre>import http from 'k6/http';\nimport { check } from 'k6';\n\nexport const options = {\n  scenarios: {\n    main: { executor: 'constant-arrival-rate', rate: 200, timeUnit: '1s',\n            duration: '5m', preAllocatedVUs: 100, maxVUs: 400 },\n  },\n  thresholds: {\n    http_req_failed: ['rate&lt;0.01'],\n    'http_req_duration{name:list}': ['p(95)&lt;300', 'p(99)&lt;800'],\n  },\n};\n\nexport default function () {\n  const h = { headers: { Authorization: `Bearer ${__ENV.TOKEN}` } };\n  const r = http.get(`${__ENV.BASE}/transactions?limit=50`, { ...h, tags: { name: 'list' } });\n  check(r, { 'status 200': (res) =&gt; res.status === 200 });\n}</pre>Lần đầu p95 của <code>list</code> là 920ms. <code>EXPLAIN ANALYZE</code> cho thấy query lọc theo <code>user_id</code> và sắp theo <code>occurred_at</code> phải sort trên đĩa; thêm index <code>(user_id, occurred_at DESC)</code> và chuyển sang cursor pagination, p95 còn 140ms. Ghi cả hai con số vào README như lab yêu cầu."},
  "w6k4": {c:"Unit test kiểm tra một đơn vị logic (hàm domain, service) tách khỏi I/O, chạy trong vài mili giây. Node có sẵn test runner <code>node:test</code> (chạy bằng <code>node --test</code>); Vitest và Jest là hai framework phổ biến với hệ sinh thái mock, snapshot, watch mode. Test double gồm: fake (implementation đơn giản chạy được, như repository in-memory), stub (trả giá trị định sẵn), spy/mock (ghi lại cách được gọi để kiểm tra).", e:"<ul><li>Chọn công cụ: <code>node:test</code> không cần cài gì, có <code>mock.fn</code>, <code>mock.method</code>, <code>mock.timers</code>, coverage (vẫn sau cờ <code>--experimental-test-coverage</code>); mock cả module cần cờ <code>--experimental-test-module-mocks</code>. Vitest chạy TypeScript/ESM tự nhiên, API gần như Jest, nhanh, hợp project mới. Jest vẫn phổ biến trong codebase NestJS cũ; ESM trên Jest vẫn cần cấu hình thêm.</li> <li>Ưu tiên fake cho repository (<code>InMemoryTransactionRepo</code>) để test hành vi; dùng mock khi muốn khẳng định một tương tác (đã gửi push đúng 1 lần, không gọi payment gateway). Mock mọi thứ khiến test chỉ lặp lại implementation và vỡ mỗi lần refactor.</li> <li>Test async: luôn <code>await</code> hoặc <code>return</code> promise, dùng <code>assert.rejects</code>/<code>expect(...).rejects</code>; quên await thì test pass dù code lỗi.</li> <li>Timer: fake timers (<code>t.mock.timers.enable()</code>, <code>vi.useFakeTimers()</code>, <code>jest.useFakeTimers()</code>) để test debounce, retry backoff, TTL mà không chờ thật. Khi code vừa có timer vừa có promise, dùng biến thể async (<code>vi.advanceTimersByTimeAsync</code>) để promise kịp chạy giữa các lần tick.</li> <li>Thiết kế để test được: inject dependency (clock, id generator, repository) qua constructor thay vì gọi <code>Date.now()</code> hay import singleton trực tiếp.</li></ul> Unit test đáng viết nhất là logic có nhánh: tính số dư, chia tiền nhóm, quy đổi tiền tệ, quy tắc ngân sách. Getter và mapping đơn giản thì không cần.", x:"Expense Tracker gửi push \"Bạn đã vượt ngân sách\" khi user nhập nhiều giao dịch liên tiếp; yêu cầu là gom các giao dịch trong 500ms thành một push. Test bằng <code>node:test</code> với fake timer, không chờ thật:<pre>import { test } from 'node:test';\nimport assert from 'node:assert/strict';\nimport { batchAlerts } from './batch-alerts.js';\n\ntest('gom các giao dịch trong 500ms thành một push', (t) =&gt; {\n  t.mock.timers.enable({ apis: ['setTimeout'] });\n  const send = t.mock.fn();\n  const notify = batchAlerts(send, 500);\n  notify({ id: 'a' });\n  notify({ id: 'b' });\n  t.mock.timers.tick(499);\n  assert.equal(send.mock.callCount(), 0);\n  t.mock.timers.tick(1);\n  assert.equal(send.mock.callCount(), 1);\n  assert.equal(send.mock.calls[0].arguments[0].length, 2);\n});</pre>Test chạy trong vài mili giây. Trước đó team dùng <code>await sleep(600)</code> trong test, bộ test chậm và thỉnh thoảng fail trên CI khi máy runner bận."},
  "w6k5": {c:"Integration test kiểm tra nhiều thành phần chạy cùng nhau với hạ tầng thật: HTTP layer, validation, service, ORM và database. Supertest gửi request vào app (không cần mở cổng thật); Testcontainers khởi động Postgres/Redis thật trong Docker cho mỗi lần chạy test rồi dọn đi.", e:"<ul><li>Vì sao không mock DB: phần lớn bug backend nằm ở ranh giới với DB: constraint, transaction, migration, query sai kiểu, timezone, collation. SQLite in-memory thay cho Postgres cũng không đủ: khác kiểu dữ liệu, khác hành vi lock, không có <code>jsonb</code>.</li> <li>Testcontainers for Node: <code>new PostgreSqlContainer('postgres:17-alpine').start()</code> (gói <code>@testcontainers/postgresql</code>), lấy <code>getConnectionUri()</code>, chạy migration, rồi dừng container ở cuối. Container có cổng ngẫu nhiên nên nhiều job CI chạy song song không đụng nhau. Chạy được trên GitHub Actions vì runner Ubuntu có sẵn Docker.</li> <li>Cô lập dữ liệu giữa các test: mỗi test chạy trong transaction rồi rollback; hoặc <code>TRUNCATE</code> các bảng trong <code>beforeEach</code>; hoặc dùng <code>snapshot()</code>/<code>restoreSnapshot()</code> của module Postgres. Không để test phụ thuộc thứ tự chạy.</li> <li>Supertest: với Express/NestJS truyền app hoặc <code>app.getHttpServer()</code> vào <code>request(...)</code>; Fastify có sẵn <code>app.inject()</code> nhanh hơn vì không đi qua socket.</li> <li>Tốc độ: khởi động container một lần cho cả suite (global setup), không phải mỗi file; cố định tag image để kết quả lặp lại được.</li></ul> Interviewer hay hỏi vặn: \"test như vậy có chậm không?\" Trả lời bằng số đo của bạn (ví dụ container khởi động khoảng 3–5s một lần, mỗi test API vài chục mili giây) và nói rõ test nào nằm ở tầng nào.", x:"Bug production của Expense Tracker: hai request tạo giao dịch song song (app mobile retry khi mạng chập chờn) làm số dư ví bị cộng hai lần. Unit test với repository fake không bắt được vì lỗi nằm ở cách dùng transaction trong Postgres. Integration test tái hiện lỗi bằng DB thật:<pre>import request from 'supertest';\nimport { PostgreSqlContainer } from '@testcontainers/postgresql';\n\nlet pg, app;\nbeforeAll(async () =&gt; {\n  pg = await new PostgreSqlContainer('postgres:17-alpine').start();\n  app = await buildApp({ databaseUrl: pg.getConnectionUri() }); // chạy migration bên trong\n}, 60_000);\nafterAll(async () =&gt; { await app.close(); await pg.stop(); });\n\ntest('retry cùng Idempotency-Key không cộng tiền hai lần', async () =&gt; {\n  const send = () =&gt; request(app.server).post('/wallets/w1/transactions')\n    .set('Idempotency-Key', 'k-1').send({ amountMinor: 50000 });\n  await Promise.all([send(), send()]);\n  const res = await request(app.server).get('/wallets/w1');\n  expect(res.body.balanceMinor).toBe(50000);\n});</pre>Test fail trước khi sửa. Sau khi thêm unique constraint trên <code>(wallet_id, idempotency_key)</code> và bắt lỗi <code>23505</code> để trả lại kết quả cũ, test pass và được giữ lại làm regression test."},
  "w6k6": {c:"E2E test kiểm tra một luồng người dùng xuyên qua toàn bộ hệ thống đã deploy (API, worker, DB, queue). Contract test kiểm tra hai bên (app mobile và API, hoặc hai service) vẫn đồng ý với nhau về định dạng request/response mà không cần chạy cả hai cùng lúc. Test pyramid là nguyên tắc: nhiều unit test, ít hơn integration, rất ít E2E.", e:"<ul><li>Vì sao kim tự tháp: tầng càng cao càng chậm, càng dễ flaky và càng khó chỉ ra lỗi ở đâu. E2E chỉ nên phủ vài luồng sống còn: đăng ký, đăng nhập, tạo giao dịch, đồng bộ, thanh toán gói premium. Với backend, nhiều team dùng hình \"kim cương\": integration test API với DB thật là tầng dày nhất vì cho nhiều tự tin nhất trên chi phí.</li> <li>Contract test: consumer-driven với Pact (consumer ghi kỳ vọng thành pact file, provider chạy verify trên CI); hoặc schema-based: OpenAPI là nguồn sự thật, CI so response thật với schema và phát hiện breaking change (xóa field, đổi kiểu, thêm field bắt buộc ở request).</li> <li>Với API phục vụ app mobile, contract quan trọng hơn bình thường: bản app cũ vẫn chạy trên máy người dùng nhiều tháng, nên không thể đổi API rồi \"deploy lại client\" như web.</li> <li>Coverage vừa đủ: coverage đo dòng code đã chạy, không đo assertion có đúng không. Đặt ngưỡng hợp lý (ví dụ 80% cho thư mục domain) và theo dõi coverage trên phần thay đổi của PR; đuổi theo 100% dẫn tới test vô nghĩa. Mutation testing (Stryker) đo chất lượng test tốt hơn coverage.</li> <li>E2E flaky: dùng dữ liệu riêng cho mỗi lần chạy, chờ theo điều kiện (poll tới khi job xong) thay vì sleep cố định, retry có giới hạn và theo dõi tỉ lệ flaky.</li></ul>", x:"Backend đổi <code>amount</code> (số thực, đơn vị đồng) thành <code>amountMinor</code> (số nguyên) để tránh lỗi làm tròn. Ở bản đầu, PR đã merge và làm app Android bản 3.x crash khi parse response. Sau sự cố, team thêm bước kiểm tra breaking change của OpenAPI trên CI:<pre># .github/workflows/contract.yml (trích)\n- name: Build OpenAPI spec of this PR\n  run: npm run openapi:generate   # ghi ra openapi.json\n- name: Compare with spec on main\n  run: |\n    git show origin/main:openapi.json &gt; base.json\n    docker run --rm -v \"$PWD:/specs\" tufin/oasdiff breaking /specs/base.json /specs/openapi.json --fail-on ERR</pre>Từ đó thay đổi kiểu này phải đi theo cách mở rộng: thêm <code>amountMinor</code>, giữ <code>amount</code> và đánh dấu deprecated, chờ tỉ lệ người dùng app cũ giảm dưới ngưỡng rồi mới xóa. E2E chỉ giữ 6 luồng, chạy trên staging sau mỗi lần deploy."},
  "w6k7": {c:"Logging có cấu trúc là ghi log dạng JSON với các field cố định (level, time, msg, requestId, userId…) thay vì chuỗi tự do, để hệ thống log (Loki, Elasticsearch, CloudWatch) lọc và tổng hợp được. pino là logger JSON nhanh nhất phổ biến trong Node, là logger mặc định của Fastify. Correlation id là id gắn vào mọi log của cùng một request, truyền ngầm qua code async bằng <code>AsyncLocalStorage</code>.", e:"<ul><li>pino nhanh vì làm rất ít trên luồng chính: serialize JSON tối giản và ghi ra stdout; format đẹp (<code>pino-pretty</code>) hay gửi đi nơi khác thì chạy trong transport ở worker thread hoặc giao cho hạ tầng (container ghi stdout, agent thu gom). Không dùng <code>pino-pretty</code> trên production.</li> <li><code>AsyncLocalStorage</code>: <code>als.run(store, fn)</code> tạo context, mọi code async xuất phát từ <code>fn</code> (await, timer, callback) đọc được bằng <code>als.getStore()</code>. Kết hợp với option <code>mixin</code> của pino để tự thêm <code>requestId</code> vào mọi dòng log mà không phải truyền logger qua từng hàm. Từ Node 24, ALS dùng <code>AsyncContextFrame</code> làm mặc định, nhanh hơn cách cũ dựa trên async_hooks.</li> <li>Request id: nhận từ header (<code>x-request-id</code> từ gateway, hoặc trace id của OpenTelemetry) nếu có, không thì tạo bằng <code>crypto.randomUUID()</code>; trả lại trong response header để app mobile gửi kèm khi báo lỗi.</li> <li>Bẫy: log token, mật khẩu, số tài khoản (dùng <code>redact</code>); log nguyên body lớn; log ở level <code>debug</code> trên production làm chi phí lưu trữ tăng vọt; dùng <code>enterWith</code> thay vì <code>run</code> khiến context rò sang request khác.</li> <li>Level có ý nghĩa: <code>error</code> là cần người xem, <code>warn</code> là bất thường nhưng tự xử lý được, <code>info</code> là sự kiện nghiệp vụ. Log lỗi kèm <code>err</code> object để pino serialize stack.</li></ul>", x:"Support nhận phản hồi \"import sao kê báo lỗi\" kèm mã request mà app hiển thị. Trước đây không tìm được log vì log của worker và API không có id chung. Sau khi thêm ALS và <code>mixin</code>, tìm theo <code>requestId</code> ra cả chuỗi từ API tới job BullMQ (id được đưa vào data của job và <code>als.run</code> lại trong worker):<pre>import pino from 'pino';\nimport { AsyncLocalStorage } from 'node:async_hooks';\nimport { randomUUID } from 'node:crypto';\n\nexport const als = new AsyncLocalStorage();\nexport const logger = pino({\n  redact: ['req.headers.authorization', '*.password'],\n  mixin: () =&gt; als.getStore() ?? {},\n});\n\n// Fastify hook: mỗi request chạy trong context riêng\napp.addHook('onRequest', (req, reply, done) =&gt; {\n  const requestId = req.headers['x-request-id'] ?? randomUUID();\n  reply.header('x-request-id', requestId);\n  als.run({ requestId, userId: req.user?.id }, done);\n});\n\n// ở bất kỳ đâu trong service\nlogger.info({ walletId }, 'transaction created');\n// {\"level\":30,...,\"requestId\":\"6f1c...\",\"walletId\":\"w-1\",\"msg\":\"transaction created\"}</pre>Thời gian điều tra một ticket loại này giảm từ cả buổi xuống vài phút."},
  "w6k8": {c:"Metrics là số liệu tổng hợp theo thời gian (request rate, error rate, latency histogram, độ dài queue); tracing ghi lại đường đi của một request qua nhiều service dưới dạng các span có quan hệ cha con. OpenTelemetry là chuẩn mở và bộ SDK để thu cả hai (cùng log) rồi xuất qua giao thức OTLP; Prometheus lưu và truy vấn metrics, Grafana vẽ dashboard. Health check cho orchestrator biết process còn sống (liveness) và có sẵn sàng nhận traffic không (readiness).", e:"<ul><li>OpenTelemetry JS: <code>NodeSDK</code> trong <code>@opentelemetry/sdk-node</code> cùng <code>getNodeAutoInstrumentations()</code> tự tạo span cho http, Express/Fastify, pg, ioredis… Phải nạp trước code ứng dụng (<code>node --import ./instrumentation.mjs dist/main.js</code>), vì instrumentation hoạt động bằng cách patch module lúc được require/import. Cách zero-code: <code>--require @opentelemetry/auto-instrumentations-node/register</code> cùng các biến <code>OTEL_SERVICE_NAME</code>, <code>OTEL_EXPORTER_OTLP_ENDPOINT</code>.</li> <li>Metrics theo RED (Rate, Errors, Duration) cho API và USE cho tài nguyên. Latency phải là histogram để tính p95/p99 ở phía Prometheus (<code>histogram_quantile</code>); không lấy trung bình của các percentile.</li> <li>Bẫy cardinality: label là URL thô (<code>/transactions/123</code>) hay <code>userId</code> tạo ra hàng triệu time series và làm sập Prometheus. Dùng route template (<code>/transactions/:id</code>).</li> <li>Sampling trace: production thường lấy mẫu theo tỉ lệ (head sampling) hoặc giữ toàn bộ trace lỗi/chậm ở collector (tail sampling).</li> <li>Liveness chỉ kiểm tra process còn phản hồi, <b>không</b> kiểm tra DB: DB chập chờn mà liveness fail thì Kubernetes restart toàn bộ pod cùng lúc, biến sự cố nhỏ thành sập hẳn. Readiness mới kiểm tra phụ thuộc (DB, Redis) và trả 503 khi đang shutdown để bị rút khỏi Service. Startup probe dùng cho app khởi động chậm.</li></ul>", x:"Expense Tracker gửi trace tới OpenTelemetry Collector, rồi từ đó sang Tempo/Jaeger; metrics được Prometheus scrape. File nạp đầu tiên:<pre>// instrumentation.mjs, chạy bằng: node --import ./instrumentation.mjs dist/main.js\nimport { NodeSDK } from '@opentelemetry/sdk-node';\nimport { OTLPTraceExporter } from '@opentelemetry/exporter-trace-otlp-http';\nimport { getNodeAutoInstrumentations } from '@opentelemetry/auto-instrumentations-node';\n\nconst sdk = new NodeSDK({\n  serviceName: 'expense-api',\n  traceExporter: new OTLPTraceExporter(), // đọc OTEL_EXPORTER_OTLP_ENDPOINT\n  instrumentations: [getNodeAutoInstrumentations()],\n});\nsdk.start();\nprocess.on('SIGTERM', () =&gt; sdk.shutdown()); // flush span còn trong buffer</pre>Hai endpoint health:<pre>app.get('/healthz', async () =&gt; ({ ok: true }));            // liveness: không chạm DB\napp.get('/readyz', async (req, reply) =&gt; {                   // readiness\n  if (shuttingDown) return reply.code(503).send();\n  await Promise.all([db.query('SELECT 1'), redis.ping()]);\n  return { ok: true };\n});</pre>Nhờ trace, team thấy <code>POST /sync</code> chậm vì 40 query tuần tự cho 40 bản ghi; gộp thành một batch upsert thì span DB giảm từ 600ms còn 35ms."},
  "w6k9": {c:"Error tracking (Sentry và các công cụ tương tự) gom exception thành nhóm theo stack trace, kèm ngữ cảnh (release, user, request, breadcrumbs) để biết lỗi nào mới, lỗi nào ảnh hưởng nhiều người. SLO (Service Level Objective) là mục tiêu độ tin cậy đo bằng SLI, ví dụ 99,9% request <code>POST /transactions</code> thành công và dưới 500ms trong 30 ngày; phần còn lại (0,1%) là error budget. Postmortem là tài liệu phân tích sự cố theo tinh thần không đổ lỗi.", e:"<ul><li>Sentry cho Node: SDK từ v8 trở đi dựng trên OpenTelemetry, cần <code>Sentry.init</code> trong file nạp sớm (<code>node --import ./instrument.mjs</code>) để tự instrument; upload source map trong CI để stack trace trỏ về file TypeScript; gắn <code>release</code> theo git SHA để biết lỗi xuất hiện từ bản deploy nào. Lọc dữ liệu nhạy cảm bằng <code>beforeSend</code>.</li> <li>Bắt lỗi ở biên: error handler của framework, worker BullMQ (event <code>failed</code>), <code>process.on('unhandledRejection')</code> và <code>uncaughtException</code>. Với <code>uncaughtException</code>: log, flush rồi thoát để orchestrator khởi động lại, vì trạng thái process không còn tin được.</li> <li>Alert theo SLO thay vì theo ngưỡng thô: alert theo burn rate (tốc độ tiêu error budget), dùng hai cửa sổ (ví dụ 1 giờ và 5 phút) để vừa bắt nhanh sự cố lớn vừa không kêu vì một spike ngắn. Alert phải dựa trên triệu chứng người dùng cảm nhận (lỗi, chậm), CPU cao không phải lý do để gọi người dậy lúc 3 giờ sáng.</li> <li>Xử lý sự cố: có người chỉ huy (incident commander), ưu tiên giảm thiệt hại trước (rollback, tắt feature flag, scale) rồi mới tìm root cause; ghi timeline ngay trong lúc xử lý.</li> <li>Postmortem: tác động (bao nhiêu người dùng, bao lâu), timeline, nguyên nhân gốc và các yếu tố góp phần, điều gì đã chạy tốt, action item có người phụ trách và hạn chót. Không đổ lỗi cá nhân; câu hỏi là \"hệ thống nào đã cho phép lỗi này lọt qua\".</li></ul>", x:"SLO của Expense Tracker: 99,5% request đồng bộ (<code>POST /sync</code>) thành công trong 30 ngày. Một tối thứ Sáu, alert burn rate báo error budget đang cháy gấp 14 lần bình thường. Sentry gom lỗi thành một issue mới, xuất hiện từ release <code>a41c2e9</code>:<pre>QueryFailedError: invalid input syntax for type uuid: \"tmp-1739\"\n  at SyncService.applyChanges (src/sync/sync.service.ts:88)\n  release: a41c2e9, users affected: 2.140</pre>App iOS bản mới gửi id tạm cho bản ghi chưa lưu, backend không validate trước khi query. Người trực rollback API về release trước trong 6 phút, error rate về bình thường; sau đó thêm validation Zod cho payload sync (trả 422 rõ ràng thay vì 500) và contract test cho định dạng id. Postmortem ghi hai action item: validate mọi input ở biên, và chạy test với payload thật từ bản app beta trước khi phát hành."},
  "w7k0": {c:"Docker đóng gói app cùng runtime và dependency thành image chạy giống nhau ở mọi nơi. Multi-stage build tách giai đoạn build (cần devDependencies, TypeScript compiler) khỏi image chạy cuối cùng (chỉ có <code>dist</code> và dependency production), nên image nhỏ và ít bề mặt tấn công. Docker Compose khai báo nhiều container (API, Postgres, Redis) để dựng môi trường dev bằng một lệnh.", e:"<ul><li>Thứ tự layer quyết định cache: copy <code>package.json</code> và lockfile trước, <code>npm ci</code>, rồi mới copy source; sửa code không làm cài lại dependency. Dùng <code>--mount=type=cache,target=/root/.npm</code> để tăng tốc thêm.</li> <li>Image nền: <code>node:24-slim</code> (Debian) là lựa chọn an toàn; <code>alpine</code> nhỏ hơn nhưng dùng musl, có thể gặp vấn đề với native module (bcrypt, sharp) và DNS; distroless không có shell, an toàn hơn nhưng khó debug. Cố định tag (hoặc digest) thay vì <code>latest</code>.</li> <li>Non-root: image <code>node</code> chính thức chạy bằng root mặc định nhưng có sẵn user <code>node</code> (uid 1000); thêm <code>USER node</code> và <code>COPY --chown=node:node</code>. Container bị chiếm quyền thì kẻ tấn công không có root.</li> <li>PID 1 và tín hiệu: dùng exec form <code>CMD [\"node\", \"dist/main.js\"]</code>, không dùng <code>npm start</code> (npm có thể không chuyển tiếp SIGTERM tới app) hay shell form. Node chạy làm PID 1 không có handler mặc định cho SIGTERM, nên app phải tự bắt tín hiệu, hoặc chạy với <code>docker run --init</code>/tini.</li> <li><code>.dockerignore</code> loại <code>node_modules</code>, <code>.git</code>, <code>.env</code>, coverage: build nhanh hơn và không lọt secret vào image. Secret lúc build (token npm private) dùng <code>--mount=type=secret</code>, không dùng <code>ARG</code>/<code>ENV</code> vì sẽ nằm trong lịch sử image.</li></ul>", x:"Image ban đầu của Expense Tracker nặng khoảng 1,2GB (dựa trên <code>node:24</code> bản đầy đủ, chứa cả devDependencies và source TypeScript), chạy bằng root. Dockerfile multi-stage sau khi sửa:<pre># syntax=docker/dockerfile:1\nFROM node:24-slim AS build\nWORKDIR /app\nCOPY package.json package-lock.json ./\nRUN --mount=type=cache,target=/root/.npm npm ci\nCOPY . .\nRUN npm run build &amp;&amp; npm prune --omit=dev\n\nFROM node:24-slim\nENV NODE_ENV=production\nWORKDIR /app\nCOPY --from=build --chown=node:node /app/node_modules ./node_modules\nCOPY --from=build --chown=node:node /app/dist ./dist\nCOPY --chown=node:node package.json ./\nUSER node\nEXPOSE 3000\nCMD [\"node\", \"dist/main.js\"]</pre>Image còn khoảng 250MB, quét lỗ hổng (Trivy/Docker Scout) ít cảnh báo hơn hẳn. <code>docker-compose.yml</code> cho dev chạy <code>api</code>, <code>postgres:17</code>, <code>redis:7</code>, với <code>depends_on</code> kèm <code>condition: service_healthy</code> để API chỉ khởi động khi Postgres đã nhận kết nối."},
  "w7k1": {c:"Graceful shutdown là tắt process một cách có trật tự khi nhận tín hiệu dừng (thường là <code>SIGTERM</code> từ Kubernetes, ECS hay Docker): ngừng nhận request mới, chờ các request và job đang chạy hoàn tất trong một khoảng thời gian giới hạn, đóng kết nối DB/Redis/queue, flush log và trace, rồi thoát. Không làm vậy thì mỗi lần deploy là một đợt lỗi 502 và job dở dang.", e:"<ul><li>Trình tự trong Kubernetes: pod bị đánh dấu terminating, chạy <code>preStop</code> hook, gửi <code>SIGTERM</code>, chờ tối đa <code>terminationGracePeriodSeconds</code> (mặc định 30s) rồi <code>SIGKILL</code>. Việc rút pod khỏi Service/load balancer diễn ra <b>song song</b>, nên vài giây đầu vẫn có request mới tới; vì vậy thường thêm <code>preStop</code> sleep vài giây, hoặc tiếp tục phục vụ trong lúc readiness trả 503.</li> <li><code>server.close()</code> ngừng nhận kết nối mới và gọi callback khi mọi kết nối đã đóng; từ Node 19 nó cũng đóng các kết nối keep-alive đang rảnh. Kết nối còn đang xử lý thì chờ; đặt thêm timer cứng (ví dụ 25s) rồi <code>closeAllConnections()</code> và thoát để không bị SIGKILL giữa chừng. Fastify có <code>app.close()</code>, NestJS có <code>app.enableShutdownHooks()</code>.</li> <li>Thứ tự đóng: HTTP server và consumer queue trước (ngừng nhận việc), chờ việc đang chạy, rồi mới đóng DB pool, Redis, cuối cùng là flush OpenTelemetry/Sentry. Đóng DB trước thì các request đang chạy sẽ lỗi.</li> <li>Worker BullMQ: <code>await worker.close()</code> chờ job hiện tại xong. Job phải idempotent vì vẫn có lúc bị kill giữa chừng (OOM, node hỏng); BullMQ sẽ coi job đó là stalled và chạy lại.</li> <li>Bẫy: chạy qua <code>npm start</code> hoặc shell form nên app không nhận SIGTERM; chỉ bắt SIGINT mà quên SIGTERM; gọi <code>process.exit()</code> ngay trong handler.</li></ul>", x:"Mỗi lần rolling deploy, Expense Tracker có khoảng 0,3% request <code>POST /transactions</code> trả 502 và vài job gửi push bị chạy lại hai lần. Nguyên nhân: Dockerfile dùng <code>CMD npm start</code>, app không bao giờ nhận SIGTERM nên bị SIGKILL sau 30s. Sửa CMD thành exec form và thêm handler:<pre>let shuttingDown = false;   // /readyz trả 503 khi true\n\nasync function shutdown(signal) {\n  if (shuttingDown) return;\n  shuttingDown = true;\n  logger.info({ signal }, 'shutting down');\n  const force = setTimeout(() =&gt; process.exit(1), 25_000);\n  force.unref();\n  await new Promise((r) =&gt; setTimeout(r, 5_000)); // chờ load balancer rút pod\n  await app.close();          // ngừng nhận request, chờ request đang chạy\n  await pushWorker.close();   // chờ job push hiện tại\n  await db.end();\n  await redis.quit();\n  await otelSdk.shutdown();\n  process.exit(0);\n}\nprocess.on('SIGTERM', shutdown);\nprocess.on('SIGINT', shutdown);</pre>Kết hợp với <code>terminationGracePeriodSeconds: 40</code>, deploy giờ không còn 502, và job push dùng <code>jobId</code> theo id thông báo để chạy lại cũng không gửi trùng."},
  "w7k2": {c:"Node chạy JavaScript trên một luồng, nên một process chỉ tận dụng một core CPU cho code ứng dụng. Muốn dùng nhiều core hoặc nhiều máy thì chạy nhiều process: module <code>cluster</code> (process master phân phối kết nối cho các worker), PM2 (process manager có cluster mode, tự restart, quản lý log), hoặc để orchestrator như Kubernetes chạy nhiều pod, mỗi pod một process.", e:"<ul><li>Trên VM hoặc server riêng: PM2 <code>exec_mode: 'cluster'</code>, <code>instances: 'max'</code> và <code>pm2 reload</code> để restart lần lượt từng worker, không downtime. Trên Kubernetes: thường chạy <b>một process mỗi pod</b> và scale bằng số replica; thêm PM2/cluster bên trong container làm orchestrator không thấy được từng process, health check và giới hạn tài nguyên khó đúng.</li> <li>Deployment khai báo số replica và chiến lược rolling update (<code>maxSurge</code>, <code>maxUnavailable</code>); đặt <code>resources.requests</code>/<code>limits</code> cho CPU và memory. Với Node, CPU request khoảng 1 core hoặc thấp hơn là hợp lý vì process chủ yếu dùng một luồng.</li> <li>HPA (<code>autoscaling/v2</code>) tăng giảm replica theo CPU, memory hoặc custom metric (độ dài queue, request/giây). Worker xử lý queue nên scale theo số job chờ (KEDA hỗ trợ sẵn) thay vì CPU.</li> <li>Probe: <code>startupProbe</code> cho thời gian khởi động (migration, warm-up); <code>readinessProbe</code> quyết định pod có nhận traffic không; <code>livenessProbe</code> restart pod bị treo. Liveness đặt quá nhạy (timeout 1s) thì một đợt GC dài hay event loop bị chặn làm pod bị restart dây chuyền.</li> <li>Mọi thứ trên chỉ đúng khi service stateless: session, rate limit counter, kết nối Socket.IO cần Redis (adapter) hoặc sticky session, vì request tiếp theo có thể vào process khác.</li></ul>", x:"Expense Tracker chạy trên Kubernetes với API và worker BullMQ tách thành hai Deployment. Trích manifest của API:<pre>apiVersion: apps/v1\nkind: Deployment\nmetadata: { name: expense-api }\nspec:\n  replicas: 3\n  strategy: { rollingUpdate: { maxSurge: 1, maxUnavailable: 0 } }\n  template:\n    spec:\n      terminationGracePeriodSeconds: 40\n      containers:\n        - name: api\n          image: ghcr.io/acme/expense-api:a41c2e9\n          resources:\n            requests: { cpu: 500m, memory: 512Mi }\n            limits: { memory: 512Mi }\n          startupProbe:   { httpGet: { path: /healthz, port: 3000 }, failureThreshold: 30, periodSeconds: 2 }\n          readinessProbe: { httpGet: { path: /readyz, port: 3000 }, periodSeconds: 5 }\n          livenessProbe:  { httpGet: { path: /healthz, port: 3000 }, periodSeconds: 10, timeoutSeconds: 3, failureThreshold: 3 }</pre>HPA cho API scale 3–12 replica theo CPU 65%. Lúc đầu liveness gọi cả DB; một lần Postgres failover mất 20 giây, tất cả pod bị restart cùng lúc và app mất hẳn kết nối trong 2 phút. Sau khi tách liveness khỏi DB, lần failover sau chỉ làm một số request lỗi trong lúc readiness trả 503."},
  "w7k3": {c:"CI/CD là pipeline tự động: CI chạy lint, type check, test và build image cho mỗi PR; CD đưa bản đã kiểm tra lên staging rồi production, kèm migration DB. Blue-green, canary và rollback là các chiến lược giảm rủi ro khi phát hành.", e:"<ul><li>Build một lần, deploy nhiều nơi: image gắn tag bằng git SHA, cùng một image đi từ staging lên production; cấu hình khác nhau nằm ở biến môi trường. Build lại cho từng môi trường thì thứ được test không phải thứ chạy production.</li> <li>Migration: chạy như một bước riêng (job trước khi deploy), không chạy lúc từng pod khởi động (nhiều pod chạy cùng lúc sẽ tranh nhau). Theo mẫu expand / contract: thêm cột nullable, deploy code ghi cả hai, backfill, chuyển đọc sang cột mới, rồi mới xóa cột cũ ở bản sau. Migration phải tương thích với cả code cũ lẫn code mới vì trong lúc rolling cả hai cùng chạy.</li> <li>Blue-green: dựng đủ môi trường mới song song, chuyển traffic một lần, rollback bằng cách chuyển lại; tốn gấp đôi tài nguyên trong lúc chuyển. Canary: đưa 5% → 25% → 100% traffic sang bản mới, theo dõi error rate/p95 ở mỗi bước, tự dừng khi vượt ngưỡng (Argo Rollouts, Flagger, CodeDeploy).</li> <li>Rollback code dễ, rollback dữ liệu khó: migration xóa cột hay đổi kiểu không quay lại được, nên mới cần expand / contract. Feature flag cho phép tắt tính năng mà không cần deploy.</li> <li>Bảo mật pipeline: dùng OIDC để CI lấy credential cloud tạm thời thay vì lưu access key lâu dài trong secret; production cần approval (GitHub Environments); pin phiên bản action.</li></ul>", x:"Pipeline GitHub Actions của Expense Tracker (trích): PR chạy kiểm tra, merge vào <code>main</code> thì build image, chạy migration rồi deploy staging.<pre>jobs:\n  ci:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v7\n      - uses: actions/setup-node@v7\n        with: { node-version: 24, cache: npm }\n      - run: npm ci\n      - run: npm run lint &amp;&amp; npm run typecheck\n      - run: npm test               # unit + integration (Testcontainers)\n  deploy-staging:\n    if: github.ref == 'refs/heads/main'\n    needs: ci\n    environment: staging\n    permissions: { id-token: write, contents: read, packages: write }\n    steps:\n      - uses: actions/checkout@v7\n      - run: docker build -t ghcr.io/acme/expense-api:${{ github.sha }} .\n      - run: docker push ghcr.io/acme/expense-api:${{ github.sha }}\n      - run: ./scripts/migrate.sh staging   # chạy migration như một job riêng\n      - run: ./scripts/deploy.sh staging ${{ github.sha }}</pre>Một lần migration đổi tên cột <code>note</code> thành <code>description</code> trong một bước đã làm bản cũ còn đang chạy trả 500 trong lúc rolling. Từ đó team chỉ chấp nhận migration theo expand / contract, và reviewer kiểm tra mục này trong checklist PR."},
  "w7k4": {c:"Trên AWS, backend Node thường dùng: ECS (chạy container, với Fargate thì không quản lý máy), Lambda (chạy hàm theo sự kiện, trả tiền theo lượt và thời gian chạy), RDS (Postgres được quản lý), S3 (lưu file), SQS (hàng đợi message). Cold start là độ trễ thêm khi Lambda phải tạo môi trường thực thi mới: tải code, khởi động runtime và chạy phần init.", e:"<ul><li>Runtime Node trên Lambda tại 10/2026: <code>nodejs22.x</code> và <code>nodejs24.x</code> được hỗ trợ; <code>nodejs20.x</code> đã deprecated từ 30/04/2026; <code>nodejs26.x</code> đang public preview, dự kiến GA khoảng 11/2026. Code dùng AWS SDK v3, nên tự đóng gói các module SDK mình dùng thay vì dựa vào bản có sẵn trong runtime.</li> <li>Giảm cold start: bundle và tree-shake bằng esbuild, chỉ import client SDK cần dùng; khởi tạo client, kết nối ngoài handler để dùng lại giữa các lần gọi; tăng memory (CPU tăng theo); provisioned concurrency cho endpoint nhạy cảm về latency. Tránh dựng cả app NestJS lớn trong Lambda nếu cold start quan trọng.</li> <li>Lambda với Postgres: mỗi môi trường thực thi giữ kết nối riêng, khi concurrency tăng đột ngột sẽ làm cạn <code>max_connections</code>; dùng RDS Proxy. ECS với process chạy lâu dùng pool bình thường.</li> <li>Chọn ECS hay Lambda: API có traffic đều, cần WebSocket, kết nối lâu, cần job dài hơn 15 phút thì ECS; tác vụ theo sự kiện, traffic thất thường (xử lý file vừa upload lên S3, consumer SQS, cron) thì Lambda. Nhiều hệ thống dùng cả hai.</li> <li>S3: app upload thẳng bằng presigned URL thay vì đi qua API. SQS: consumer phải idempotent vì giao hàng ít nhất một lần; đặt visibility timeout lớn hơn thời gian xử lý; cấu hình dead-letter queue.</li></ul>", x:"Luồng quét hóa đơn của Expense Tracker: app xin presigned URL từ API (chạy trên ECS Fargate), upload ảnh thẳng lên S3; S3 event đẩy vào SQS; một Lambda <code>nodejs24.x</code> đọc SQS, gọi OCR rồi ghi kết quả vào RDS qua RDS Proxy.<pre>// handler.mjs (bundle bằng esbuild)\nimport { S3Client, GetObjectCommand } from '@aws-sdk/client-s3';\nimport pg from 'pg';\n\nconst s3 = new S3Client({});                      // tạo một lần, ngoài handler\nconst pool = new pg.Pool({ connectionString: process.env.DB_URL, max: 1 });\n\nexport const handler = async (event) =&gt; {\n  const failures = [];\n  for (const record of event.Records) {\n    try {\n      const { bucket, key } = JSON.parse(record.body);\n      const img = await s3.send(new GetObjectCommand({ Bucket: bucket, Key: key }));\n      await saveReceipt(pool, key, await ocr(img.Body)); // upsert theo key: chạy lại không trùng\n    } catch {\n      failures.push({ itemIdentifier: record.messageId });\n    }\n  }\n  return { batchItemFailures: failures };  // cần bật ReportBatchItemFailures: chỉ retry message lỗi\n};</pre>Bundle ban đầu kéo cả SDK v2 và thư viện ảnh, cold start khoảng 2,5s. Sau khi bỏ SDK v2, bundle bằng esbuild và đưa xử lý ảnh nặng sang bước khác, cold start còn khoảng 600ms; luồng này chạy nền nên không cần provisioned concurrency."},
  "w7k5": {c:"12-factor app là tập nguyên tắc cho ứng dụng chạy trên cloud; với cấu hình, nguyên tắc chính là: mọi thứ khác nhau giữa các môi trường (URL DB, secret, cờ tính năng) nằm trong biến môi trường, không nằm trong code; cùng một build chạy được ở dev, staging và prod. Feature flag là công tắc bật tắt tính năng lúc runtime, tách việc deploy code khỏi việc phát hành tính năng.", e:"<ul><li>Validate cấu hình lúc khởi động bằng schema (Zod, <code>@nestjs/config</code> với Joi/Zod): thiếu <code>DATABASE_URL</code> hay <code>JWT_SECRET</code> quá ngắn thì app dừng ngay với thông báo rõ, thay vì chạy được và lỗi lúc 2 giờ sáng. Export một object config đã có kiểu, không gọi <code>process.env.X</code> rải rác khắp code.</li> <li>File <code>.env</code> chỉ dành cho dev local và không commit (commit <code>.env.example</code>). Node 20.6+ có <code>--env-file=.env</code> nên không cần dotenv cho trường hợp đơn giản. Production lấy secret từ secret manager (AWS Secrets Manager, Kubernetes Secret, Vault) inject thành biến môi trường hoặc file.</li> <li>Không phân nhánh theo tên môi trường (<code>if (env === 'staging')</code>); dùng cấu hình mô tả hành vi (<code>EMAIL_PROVIDER=smtp</code>, <code>LOG_LEVEL=debug</code>). Staging nên giống production nhất có thể: cùng phiên bản Postgres, cùng cách deploy.</li> <li>Các nguyên tắc 12-factor khác hay được hỏi: process stateless, log ra stdout, dependency khai báo rõ (lockfile), tác vụ admin (migration) chạy như process riêng, khởi động nhanh và tắt êm.</li> <li>Feature flag: release flag (sống ngắn, xóa sau khi rollout xong), ops flag/kill switch (tắt tính năng nặng khi có sự cố), permission flag (gói premium). Đánh giá flag theo user để rollout theo phần trăm ổn định. Bẫy: flag cũ không dọn thành nợ kỹ thuật, nhiều tổ hợp flag không ai test.</li></ul>", x:"Expense Tracker từng có lần staging gửi email thật cho người dùng production vì một biến cấu hình bị copy nhầm. Sau đó team viết lại module config:<pre>import { z } from 'zod';\n\nconst Env = z.object({\n  NODE_ENV: z.enum(['development', 'test', 'production']),\n  DATABASE_URL: z.url(),\n  REDIS_URL: z.url(),\n  JWT_SECRET: z.string().min(32),\n  EMAIL_PROVIDER: z.enum(['console', 'ses']).default('console'),\n  FLAG_RECEIPT_OCR_PERCENT: z.coerce.number().min(0).max(100).default(0),\n});\n\nexport const config = Env.parse(process.env); // sai hoặc thiếu là dừng ngay khi khởi động</pre>Mặc định của <code>EMAIL_PROVIDER</code> là <code>console</code>, nên môi trường nào quên cấu hình cũng không gửi email thật. Tính năng OCR hóa đơn được rollout 5% → 50% → 100% bằng flag, chọn user theo <code>hash(userId) % 100</code> để mỗi người luôn ở cùng một nhóm; flag được xóa khỏi code hai tuần sau khi lên 100%."},
  "w7k6": {c:"Vòng system design yêu cầu thiết kế một hệ thống từ yêu cầu mơ hồ: làm rõ yêu cầu chức năng và phi chức năng, ước lượng tải, đề xuất API và data model, vẽ kiến trúc, rồi đào sâu vào chỗ khó và nêu trade-off. Ước lượng tải (back-of-the-envelope) là tính nhanh QPS, dung lượng lưu trữ, băng thông để biết cần một máy hay cả cụm.", e:"Khung 45 phút: yêu cầu (5 phút) → ước lượng (5) → API + data model (10) → kiến trúc tổng quát (10) → đào sâu và trade-off (15). Ước lượng: 1 triệu request/ngày ≈ 12 req/s trung bình, peak thường lấy gấp 3–10 lần. Năm đề hay gặp: <ul><li><b>URL shortener</b>: đọc nhiều hơn ghi rất nhiều; id bằng base62 của counter (hoặc Snowflake id) thay vì hash rồi xử lý trùng; cache Redis cho link nóng; 301 hay 302 (302 mới đếm được lượt click).</li> <li><b>Rate limiter</b>: token bucket hoặc sliding window trong Redis, thao tác atomic bằng Lua script; key theo user/API key/IP; trả 429 kèm <code>Retry-After</code>; quyết định fail-open hay fail-closed khi Redis chết.</li> <li><b>Chat</b>: WebSocket qua Socket.IO + Redis adapter để nhiều node phát được cho nhau; message id do client tạo để chống trùng; thứ tự theo sequence của server trong từng cuộc hội thoại; push khi user offline.</li> <li><b>Notification</b>: API ghi vào queue, worker gửi qua FCM/APNs/email; idempotency key; retry có backoff; tôn trọng tùy chọn của user và giờ yên lặng; theo dõi tỉ lệ gửi thành công.</li> <li><b>Thanh toán</b>: idempotency key bắt buộc, sổ cái bút toán kép (ledger) chỉ ghi thêm, transaction DB, webhook của cổng thanh toán xác thực chữ ký và xử lý được việc đến trùng hoặc sai thứ tự, đối soát hằng ngày.</li></ul> Senior được đánh giá ở việc tự đặt câu hỏi, tự nêu điểm hỏng và chọn có lý do.", x:"Đề: \"Thiết kế rate limiter cho API của Expense Tracker: mỗi user tối đa 100 request/phút, chạy trên 6 pod.\" Ước lượng: 200.000 user hoạt động ngày, peak khoảng 2.000 req/s, nên mỗi request phải thêm dưới 1ms; bộ đếm trong RAM của từng pod không dùng được vì user bị chia sang nhiều pod. Đề xuất: fixed window trong Redis, đủ đơn giản cho bản đầu:<pre>-- KEYS[1] = rl:{userId}:{epochMinute}, ARGV[1] = limit\nlocal n = redis.call('INCR', KEYS[1])\nif n == 1 then redis.call('EXPIRE', KEYS[1], 60) end\nif n &gt; tonumber(ARGV[1]) then return 0 end\nreturn 1</pre>Rồi tự nêu trade-off: fixed window cho phép tới 200 request quanh ranh giới hai phút, nếu cần chặt hơn thì chuyển sang sliding window log bằng sorted set (tốn bộ nhớ hơn) hoặc token bucket. Redis chết thì fail-open cho endpoint đọc, fail-closed cho endpoint đăng nhập để chống dò mật khẩu. Thêm limit theo IP ở gateway để chặn tấn công trước khi tới app."},
  "w7k7": {c:"Scale ngang là thêm máy chạy cùng một service thay vì nâng cấp một máy; điều kiện tiên quyết là service stateless (không giữ session hay dữ liệu chỉ có ở RAM của một process). Load balancer chia request cho các instance; CDN cache nội dung ở gần người dùng; cache nhiều tầng giảm tải cho DB; sharding chia dữ liệu ra nhiều DB khi một máy không còn đủ. Định lý CAP: khi có phân vùng mạng, hệ thống phân tán phải chọn giữa nhất quán (C) và sẵn sàng (A).", e:"<ul><li>Stateless: session/JWT blacklist trong Redis, file trên S3, job trong queue, Socket.IO dùng Redis adapter. Thử nghiệm đơn giản: kill một pod bất kỳ, người dùng không được nhận ra.</li> <li>Cache nhiều tầng: CDN (asset, response công khai) → cache trong process (LRU, rất nhanh nhưng mỗi pod một bản, khó invalidate) → Redis (dùng chung) → DB. Bẫy: cache stampede khi key nóng hết hạn cùng lúc (giải bằng lock/single-flight, TTL có jitter, stale-while-revalidate); invalidation sai làm user thấy số dư cũ.</li> <li>Thứ tự scale DB trước khi nghĩ tới sharding: index và query tốt → connection pooling → read replica (chấp nhận replication lag, đọc-sau-ghi phải về primary) → partition bảng theo thời gian → cache → tách DB theo domain. Sharding (ví dụ theo <code>user_id</code>) là bước cuối vì làm query xuyên shard, transaction và resharding trở nên khó.</li> <li>CAP thực tế: phân vùng mạng là chuyện sẽ xảy ra, nên lựa chọn thật là CP hay AP cho từng loại dữ liệu. Số dư ví, thanh toán: ưu tiên nhất quán. Bộ đếm lượt xem, feed: chấp nhận eventual consistency. PACELC bổ sung: kể cả khi không có phân vùng vẫn có trade-off giữa latency và nhất quán.</li> <li>Interviewer hay hỏi vặn: \"vì sao không shard luôn từ đầu?\" Câu trả lời tốt: Postgres một primary với index tốt chịu được hàng nghìn ghi mỗi giây; shard sớm là trả chi phí vận hành cho một vấn đề chưa có.</li></ul>", x:"Đầu tháng, lượng người mở màn hình \"Báo cáo tháng\" của Expense Tracker tăng gấp 8 lần, CPU của Postgres lên 90% vì cùng một query tổng hợp chạy lại liên tục. Giải pháp theo tầng: thêm read replica cho các query báo cáo, và cache Redis cho kết quả báo cáo theo <code>(userId, month)</code>, có cơ chế chống stampede:<pre>async function monthlyReport(userId, month) {\n  const key = `report:${userId}:${month}`;\n  const hit = await redis.get(key);\n  if (hit) return JSON.parse(hit);\n  // chỉ một request được tính lại, các request khác chờ ngắn rồi đọc cache\n  const locked = await redis.set(`${key}:lock`, '1', 'PX', 5000, 'NX');\n  if (!locked) { await sleep(100); return monthlyReport(userId, month); }\n  const data = await replica.computeReport(userId, month);\n  const ttl = 600 + Math.floor(Math.random() * 120); // jitter để không hết hạn đồng loạt\n  await redis.set(key, JSON.stringify(data), 'EX', ttl);\n  return data;\n}</pre>Khi user thêm hoặc sửa giao dịch trong tháng đó, service xóa key tương ứng. Riêng số dư ví vẫn luôn đọc từ primary, không cache, vì người dùng vừa thêm giao dịch mà thấy số dư cũ sẽ nghĩ app bị lỗi. CPU primary về khoảng 35%."},
  "w7k8": {c:"AI trong backend gồm hai phần: tích hợp LLM API vào sản phẩm (phân loại giao dịch, tóm tắt chi tiêu, trợ lý hỏi đáp) với streaming response để người dùng thấy chữ hiện dần; và dùng AI coding tool trong quá trình phát triển một cách có kiểm soát, nghĩa là người viết vẫn chịu trách nhiệm hiểu, kiểm tra và review mọi dòng code.", e:"<ul><li>Gọi LLM từ backend, không từ app mobile: API key nằm ở server; backend kiểm soát quota theo user, log chi phí token, cache, và áp chính sách dữ liệu. Đặt timeout, retry có backoff cho lỗi 429/5xx, và giới hạn <code>max_tokens</code>.</li> <li>Streaming: SDK chính thức (OpenAI, Anthropic…) trả về luồng sự kiện; backend chuyển tiếp xuống client bằng Server-Sent Events (<code>Content-Type: text/event-stream</code>) hoặc WebSocket. Cần xử lý khi client ngắt kết nối: hủy request tới LLM bằng <code>AbortController</code> để không tốn token vô ích. Proxy/load balancer có thể buffer response, phải tắt buffering cho route này.</li> <li>Output có cấu trúc: yêu cầu JSON theo schema (structured output/tool use) và validate lại bằng Zod; không bao giờ tin output của model như input đã kiểm tra. Prompt injection: dữ liệu người dùng (ghi chú giao dịch, nội dung sao kê) có thể chứa chỉ dẫn, nên không cho model quyền gọi hành động nguy hiểm mà không qua kiểm tra phía server.</li> <li>Dữ liệu tài chính là dữ liệu nhạy cảm: chỉ gửi trường cần thiết, xem điều khoản lưu trữ dữ liệu của nhà cung cấp, cho người dùng biết tính năng dùng AI.</li> <li>AI coding tool có kiểm soát: giao việc lặp lại (boilerplate, test, migration, viết lại theo mẫu), đọc từng dòng trước khi commit, chạy test, không dán secret hay mã nguồn ngoài chính sách công ty vào tool. Khi được hỏi trong phỏng vấn, kể một lần AI gợi ý sai (API không tồn tại, lỗ hổng SQL injection) và bạn phát hiện bằng cách nào.</li></ul>", x:"Tính năng \"Hỏi về chi tiêu của tôi\" trong Expense Tracker: backend tổng hợp số liệu tháng từ DB (không gửi danh sách giao dịch thô), gọi LLM và stream câu trả lời về app bằng SSE:<pre>import Anthropic from '@anthropic-ai/sdk';\nconst client = new Anthropic(); // đọc ANTHROPIC_API_KEY từ env\n\napp.get('/insights/stream', async (req, reply) =&gt; {\n  const summary = await reports.monthlySummary(req.user.id); // số tổng theo danh mục\n  const ac = new AbortController();\n  req.raw.on('close', () =&gt; ac.abort());                     // user thoát màn hình thì dừng\n  reply.raw.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache' });\n  const stream = client.messages.stream({\n    model: config.LLM_MODEL, max_tokens: 600,\n    system: 'Bạn là trợ lý tài chính cá nhân. Chỉ dùng số liệu được cung cấp.',\n    messages: [{ role: 'user', content: `${JSON.stringify(summary)}\\n\\nCâu hỏi: ${req.query.q}` }],\n  }, { signal: ac.signal });\n  stream.on('text', (t) =&gt; reply.raw.write(`data: ${JSON.stringify(t)}\\n\\n`));\n  try { await stream.finalMessage(); } finally { reply.raw.end(); }\n});</pre>Đo trên staging: chữ đầu tiên hiện sau khoảng 1s thay vì chờ 6–8s cho cả câu trả lời. Quota 20 câu hỏi/ngày cho mỗi user (dùng lại rate limiter Redis) giữ chi phí trong ngân sách; token dùng cho mỗi request được ghi vào log để theo dõi chi phí."},
  "w7k9": {c:"STAR (Situation, Task, Action, Result) là khung kể lại một trải nghiệm thật trong vòng phỏng vấn hành vi: bối cảnh, nhiệm vụ của bạn, những gì chính bạn đã làm, và kết quả đo được. Giai đoạn chuẩn bị cuối còn gồm phỏng vấn thử và luyện các dạng bài live coding backend hay gặp.", e:"<ul><li>Chuẩn bị 5–6 câu chuyện dùng được cho nhiều câu hỏi: sự cố production nghiêm trọng, tối ưu hiệu năng có số đo, bất đồng kỹ thuật với đồng nghiệp hoặc PM, migration dữ liệu rủi ro, mentor junior, một lần thất bại. Phần Action chiếm nhiều thời lượng nhất và nói \"tôi\" thay vì \"chúng tôi\". Result có con số (p95, error rate, chi phí hạ tầng, thời gian deploy) và bài học.</li> <li>Câu chuyện backend tốt thường có: cách bạn phát hiện (alert, trace, log), cách giảm thiệt hại trước (rollback, flag), cách tìm nguyên nhân gốc, và thay đổi để không lặp lại (test, alert, quy trình).</li> <li>Mock interview: tự ghi âm hoặc nhờ đồng nghiệp hỏi; tập nghĩ thành tiếng khi code; bấm giờ như thật; tập cả tiếng Anh nếu công ty phỏng vấn bằng tiếng Anh.</li> <li>7 bài live coding backend nên luyện: CRUD REST có validation và phân trang cursor; middleware auth JWT + phân quyền; rate limiter (in-memory rồi Redis); xử lý song song có giới hạn concurrency và retry/backoff; đọc file lớn bằng stream và tổng hợp; tìm và sửa bug trong một service có sẵn (race condition, N+1, leak); system design.</li> <li>Về AI tool: mỗi công ty có quy định riêng cho buổi phỏng vấn, nên hỏi recruiter trước. Nếu được dùng, cho thấy bạn kiểm chứng output thay vì chép nguyên.</li></ul> Với Senior, trả lời theo khung: bối cảnh → quyết định → phương án khác đã cân nhắc → khi nào cách này hỏng → bằng chứng.", x:"Câu hỏi: \"Kể về một lần bạn cải thiện hiệu năng hệ thống.\" <ul><li><b>S</b>: Đầu mỗi tháng, API Expense Tracker có p95 tăng từ 200ms lên 2,5s, CPU Postgres 90%, app mobile hiện spinner rất lâu ở màn hình báo cáo; khoảng 30.000 người dùng hoạt động mỗi ngày.</li> <li><b>T</b>: Tôi phụ trách backend báo cáo, mục tiêu được giao là đưa p95 về dưới 300ms trước kỳ đầu tháng tiếp theo, không tăng chi phí DB quá 20%.</li> <li><b>A</b>: Tôi dùng trace OpenTelemetry để xác định 70% thời gian nằm ở một query tổng hợp, tái hiện bằng k6 trên staging với dữ liệu cỡ production, thêm index ghép và viết lại query, cache kết quả báo cáo trong Redis có chống stampede và xóa cache khi giao dịch thay đổi, chuyển query báo cáo sang read replica. Tôi cân nhắc materialized view nhưng bỏ vì độ trễ refresh làm số liệu cũ; tôi viết lý do vào ADR.</li> <li><b>R</b>: p95 đầu tháng còn 180ms, CPU primary 35%, chi phí tăng 12% cho replica. Tôi thêm ngưỡng p95 của k6 vào CI để chặn hồi quy, và alert theo SLO cho endpoint báo cáo.</li></ul> Khi kể, dành khoảng 60% thời gian cho phần A, nêu cả phương án đã loại và lý do, và chuẩn bị trả lời câu hỏi vặn \"nếu dữ liệu tăng gấp 10 thì sao\"."},
};

const EXPL_ND = {...EXPL_ND_01, ...EXPL_ND_23, ...EXPL_ND_DB, ...EXPL_ND_4, ...EXPL_ND_5, ...EXPL_ND_67};
